#!/usr/bin/env python3
import base64,copy,hashlib,importlib,json,os,sys
from pathlib import Path
PAYLOAD=json.loads("{\"root\":\"/Users/qianqi/Documents/Codex/2026-10-18/pocket4-razr60-ui/work/followthrough-20261106-fc33-source-audit01/native-trust-audit01\",\"v2\":\"/Users/qianqi/Documents/Codex/2026-10-18/pocket4-razr60-ui/work/followthrough-20261106-fc33-source-audit01/native-streams-v2\",\"refs\":[{\"path\":\"crates/trillionnium-owner-open-tool-bridge/src/lib.rs\",\"sha\":\"e05725a620c72b4e5c904fb01a309c87284c8578\",\"text\":\"//! Owner-open call-registry to direct process-runtime bridge.\\n//!\\n//! One strict codec-authored request is bound to one scoped call ID. Exactly\\n//! one caller may spawn it, cancellation reaches the owned process group, PID\\n//! and terminal observations are recorded, and runtime events remain available\\n//! to the embedding Host. The bridge adds no plan, risk, approval, Authority,\\n//! typed ADB or command-allowlist semantics.\\n\\nuse std::error::Error;\\nuse std::fmt::{Display, Formatter};\\nuse std::os::unix::ffi::OsStrExt;\\nuse std::panic::{AssertUnwindSafe, catch_unwind};\\nuse std::path::Path;\\nuse std::sync::Arc;\\nuse std::sync::atomic::{AtomicBool, Ordering};\\nuse std::time::{Duration, Instant};\\n\\nuse sha2::{Digest, Sha256};\\nuse trillionnium_owner_open_call_registry::{\\n    BeginDisposition, CallKey, CallRegistry, CallRequest, CallSnapshot, RegistryError, SpawnClaim,\\n    TerminalRecord,\\n};\\nuse trillionnium_owner_open_runtime::{\\n    AdbExecRequest, CancellationToken as RuntimeCancellationToken, ExecutionEvent,\\n    ExecutionEventKind, ExecutionTerminal, MechanicalLimits, PtySize, ShellExecRequest,\\n    ShellInvocation, StreamKind, TerminalKind, ToolKind, execute_adb, execute_adb_pty,\\n    execute_shell, execute_shell_pty,\\n};\\n\\n#[derive(Debug)]\\npub enum BridgeError {\\n    InvalidRequest(String),\\n    ClaimedDigestMismatch { claimed: String, computed: String },\\n    Registry(RegistryError),\\n    RegistryObservation(RegistryError),\\n    EventSinkFailed(String),\\n    EventSinkPanicked,\\n    RuntimeRejected(String),\\n}\\n\\nimpl Display for BridgeError {\\n    fn fmt(&self, formatter: &mut Formatter<'_>) -> std::fmt::Result {\\n        match self {\\n            Self::InvalidRequest(message) => {\\n                write!(formatter, \\\"invalid owner-open tool bridge request: {message}\\\")\\n            }\\n            Self::ClaimedDigestMismatch { claimed, computed } => write!(\\n                formatter,\\n                \\\"claimed owner-open request digest {claimed} does not match computed {computed}\\\",\\n            ),\\n            Self::Registry(error) => write!(formatter, \\\"owner-open call registry failed: {error}\\\"),\\n            Self::RegistryObservation(error) => write!(\\n                formatter,\\n                \\\"owner-open runtime completed with a registry observation failure: {error}\\\",\\n            ),\\n            Self::EventSinkFailed(message) => {\\n                write!(formatter, \\\"owner-open tool event sink failed: {message}\\\")\\n            }\\n            Self::EventSinkPanicked => formatter.write_str(\\n                \\\"owner-open tool event sink panicked; the process group was cancelled and the registry was closed\\\",\\n            ),\\n            Self::RuntimeRejected(message) => write!(\\n                formatter,\\n                \\\"owner-open process runtime rejected a preflighted request: {message}\\\",\\n            ),\\n        }\\n    }\\n}\\n\\nimpl Error for BridgeError {\\n    fn source(&self) -> Option<&(dyn Error + 'static)> {\\n        match self {\\n            Self::Registry(error) | Self::RegistryObservation(error) => Some(error),\\n            _ => None,\\n        }\\n    }\\n}\\n\\nimpl From<RegistryError> for BridgeError {\\n    fn from(error: RegistryError) -> Self {\\n        Self::Registry(error)\\n    }\\n}\\n\\npub type Result<T> = std::result::Result<T, BridgeError>;\\n\\n#[derive(Debug, Clone)]\\npub enum DirectToolRequest {\\n    Shell(ShellExecRequest),\\n    Adb(AdbExecRequest),\\n}\\n\\nimpl DirectToolRequest {\\n    #[must_use]\\n    pub const fn tool_name(&self) -> &'static str {\\n        match self {\\n            Self::Shell(_) => \\\"shell.exec\\\",\\n            Self::Adb(_) => \\\"adb.exec\\\",\\n        }\\n    }\\n\\n    #[must_use]\\n    const fn tool_kind(&self) -> ToolKind {\\n        match self {\\n            Self::Shell(_) => ToolKind::ShellExec,\\n            Self::Adb(_) => ToolKind::AdbExec,\\n        }\\n    }\\n}\\n\\n/// A call bound to exact canonical request bytes authored by the owner-open\\n/// codec layer. The bridge recomputes the digest before registry admission.\\n#[derive(Debug, Clone)]\\npub struct BoundToolCall {\\n    pub key: CallKey,\\n    pub binding_fingerprint: String,\\n    pub target_id: Option<String>,\\n    pub canonical_request: Vec<u8>,\\n    pub request_sha256: String,\\n    pub request: DirectToolRequest,\\n    /// Optional foreground PTY transport. `None` retains the historical\\n    /// separate stdout/stderr pipe behavior; the option is mechanical and is\\n    /// included in the canonical request bytes by the codec layer.\\n    pub pty: Option<PtySize>,\\n}\\n\\nimpl BoundToolCall {\\n    pub fn new(\\n        key: CallKey,\\n        binding_fingerprint: impl Into<String>,\\n        target_id: Option<String>,\\n        canonical_request: Vec<u8>,\\n        request: DirectToolRequest,\\n    ) -> Result<Self> {\\n        Self::new_with_pty(\\n            key,\\n            binding_fingerprint,\\n            target_id,\\n            canonical_request,\\n            request,\\n            None,\\n        )\\n    }\\n\\n    /// Build a call whose transport mode is bound at construction time.\\n    /// PTY-enabled calls must carry a matching normalized `pty` member in the\\n    /// canonical JSON preimage; this prevents a caller from reusing one digest\\n    /// while changing the actual process wiring.\\n    pub fn new_with_pty(\\n        key: CallKey,\\n        binding_fingerprint: impl Into<String>,\\n        target_id: Option<String>,\\n        canonical_request: Vec<u8>,\\n        request: DirectToolRequest,\\n        pty: Option<PtySize>,\\n    ) -> Result<Self> {\\n        if canonical_request.is_empty() {\\n            return Err(invalid(\\\"canonical request bytes must not be empty\\\"));\\n        }\\n        let request_sha256 = sha256_hex(&canonical_request);\\n        let value = Self {\\n            key,\\n            binding_fingerprint: binding_fingerprint.into(),\\n            target_id,\\n            canonical_request,\\n            request_sha256,\\n            request,\\n            pty,\\n        };\\n        value.validate()?;\\n        value.validate_canonical_pty()?;\\n        Ok(value)\\n    }\\n\\n    /// Attach an owner-selected PTY transport to this already-canonicalized\\n    /// call. The canonical bytes must contain the same PTY option; this method\\n    /// only carries the decoded mechanical form to the process bridge.\\n    pub fn with_pty(mut self, pty: Option<PtySize>) -> Result<Self> {\\n        if let Some(size) = pty\\n            && (size.rows == 0 || size.cols == 0)\\n        {\\n            return Err(invalid(\\\"PTY rows and cols must be non-zero\\\"));\\n        }\\n        self.pty = pty;\\n        self.validate()?;\\n        self.validate_canonical_pty()?;\\n        Ok(self)\\n    }\\n\\n    pub fn with_claimed_digest(\\n        key: CallKey,\\n        binding_fingerprint: impl Into<String>,\\n        target_id: Option<String>,\\n        canonical_request: Vec<u8>,\\n        claimed_request_sha256: impl Into<String>,\\n        request: DirectToolRequest,\\n    ) -> Result<Self> {\\n        Self::with_claimed_digest_and_pty(\\n            key,\\n            binding_fingerprint,\\n            target_id,\\n            canonical_request,\\n            claimed_request_sha256,\\n            request,\\n            None,\\n        )\\n    }\\n\\n    pub fn with_claimed_digest_and_pty(\\n        key: CallKey,\\n        binding_fingerprint: impl Into<String>,\\n        target_id: Option<String>,\\n        canonical_request: Vec<u8>,\\n        claimed_request_sha256: impl Into<String>,\\n        request: DirectToolRequest,\\n        pty: Option<PtySize>,\\n    ) -> Result<Self> {\\n        let claimed = claimed_request_sha256.into();\\n        require_sha256(&claimed, \\\"claimed_request_sha256\\\")?;\\n        let value = Self::new_with_pty(\\n            key,\\n            binding_fingerprint,\\n            target_id,\\n            canonical_request,\\n            request,\\n            pty,\\n        )?;\\n        if value.request_sha256 != claimed {\\n            return Err(BridgeError::ClaimedDigestMismatch {\\n                claimed,\\n                computed: value.request_sha256,\\n            });\\n        }\\n        Ok(value)\\n    }\\n\\n    fn validate(&self) -> Result<()> {\\n        require_sha256(&self.binding_fingerprint, \\\"binding_fingerprint\\\")?;\\n        require_sha256(&self.request_sha256, \\\"request_sha256\\\")?;\\n        if self.canonical_request.len() > 1024 * 1024 {\\n            return Err(invalid(\\\"canonical request exceeds the bridge byte bound\\\"));\\n        }\\n        if self\\n            .target_id\\n            .as_ref()\\n            .is_some_and(|value| value.len() > 4_096 || value.as_bytes().contains(&0))\\n        {\\n            return Err(invalid(\\\"target_id exceeds its mechanical bound\\\"));\\n        }\\n        if self\\n            .pty\\n            .is_some_and(|size| size.rows == 0 || size.cols == 0)\\n        {\\n            return Err(invalid(\\\"PTY rows and cols must be non-zero\\\"));\\n        }\\n        Ok(())\\n    }\\n\\n    fn registry_request(&self) -> CallRequest {\\n        CallRequest::new(\\n            self.request_sha256.clone(),\\n            self.binding_fingerprint.clone(),\\n            self.request.tool_name(),\\n            self.target_id.clone(),\\n        )\\n    }\\n\\n    fn validate_canonical_pty(&self) -> Result<()> {\\n        let value: serde_json::Value = match serde_json::from_slice(&self.canonical_request) {\\n            Ok(value) => value,\\n            Err(error) if self.pty.is_some() => {\\n                return Err(invalid(format!(\\n                    \\\"PTY-enabled canonical request is not JSON: {error}\\\"\\n                )));\\n            }\\n            // Non-PTY callers may carry codec-owned canonical bytes whose\\n            // shape is validated by the upstream codec.  Preserve that\\n            // boundary while still enforcing every parseable PTY member.\\n            Err(_) => return Ok(()),\\n        };\\n        let Some(pty) = value.as_object().and_then(|object| object.get(\\\"pty\\\")) else {\\n            if self.pty.is_some() {\\n                return Err(invalid(\\\"PTY-enabled canonical request omits pty\\\"));\\n            }\\n            return Ok(());\\n        };\\n        let (enabled, rows, cols) = match pty {\\n            serde_json::Value::Bool(enabled) => (*enabled, 24, 80),\\n            serde_json::Value::Object(object) => {\\n                let enabled = match object.get(\\\"enabled\\\") {\\n                    None => true,\\n                    Some(serde_json::Value::Bool(value)) => *value,\\n                    Some(_) => return Err(invalid(\\\"canonical pty.enabled is not boolean\\\")),\\n                };\\n                let rows = canonical_pty_dimension(object.get(\\\"rows\\\"), \\\"rows\\\", 24)?;\\n                let cols = canonical_pty_dimension(object.get(\\\"cols\\\"), \\\"cols\\\", 80)?;\\n                (enabled, rows, cols)\\n            }\\n            _ => return Err(invalid(\\\"canonical pty must be boolean or object\\\")),\\n        };\\n        match (self.pty, enabled) {\\n            (Some(expected), true) if rows == expected.rows && cols == expected.cols => Ok(()),\\n            (Some(_), _) => Err(invalid(\\n                \\\"PTY transport does not match the canonical request dimensions\\\",\\n            )),\\n            (None, false) => Ok(()),\\n            (None, true) => Err(invalid(\\n                \\\"canonical request enables PTY but the bridge has no PTY transport\\\",\\n            )),\\n        }\\n    }\\n}\\n\\n#[derive(Debug, Clone)]\\npub struct BridgeLimits {\\n    pub runtime: MechanicalLimits,\\n    pub cancellation_poll: Duration,\\n}\\n\\nimpl Default for BridgeLimits {\\n    fn default() -> Self {\\n        Self {\\n            runtime: MechanicalLimits::default(),\\n            cancellation_poll: Duration::from_millis(5),\\n        }\\n    }\\n}\\n\\nimpl BridgeLimits {\\n    pub fn validate(&self) -> Result<()> {\\n        self.runtime\\n            .validate()\\n            .map_err(|error| invalid(error.to_string()))?;\\n        if self.cancellation_poll.is_zero() || self.cancellation_poll > Duration::from_secs(1) {\\n            return Err(invalid(\\n                \\\"cancellation poll must be non-zero and at most one second\\\",\\n            ));\\n        }\\n        Ok(())\\n    }\\n\\n    /// Return the runtime limits after applying the bridge's cancellation\\n    /// responsiveness bound.\\n    ///\\n    /// `MechanicalLimits::poll_interval` is the process-runtime wait between\\n    /// cancellation checks.  Keep the caller's runtime setting when it is\\n    /// already more responsive, but never let it exceed the bridge-level\\n    /// cancellation bound.  The returned value is owned so the borrowed\\n    /// [`BridgeLimits`] remains immutable for the duration of a call.\\n    fn effective_runtime(&self) -> MechanicalLimits {\\n        let mut runtime = self.runtime.clone();\\n        runtime.poll_interval = runtime.poll_interval.min(self.cancellation_poll);\\n        runtime\\n    }\\n}\\n\\nfn canonical_pty_dimension(\\n    value: Option<&serde_json::Value>,\\n    label: &str,\\n    default: u16,\\n) -> Result<u16> {\\n    let Some(value) = value else {\\n        return Ok(default);\\n    };\\n    let Some(raw) = value.as_u64() else {\\n        return Err(invalid(format!(\\\"canonical pty.{label} is not an integer\\\")));\\n    };\\n    let value = u16::try_from(raw)\\n        .map_err(|_| invalid(format!(\\\"canonical pty.{label} is outside the u16 bound\\\")))?;\\n    if value == 0 {\\n        return Err(invalid(format!(\\\"canonical pty.{label} is zero\\\")));\\n    }\\n    Ok(value)\\n}\\n\\n#[derive(Debug, Clone)]\\npub enum DispatchResult {\\n    Executed {\\n        generation: u64,\\n        terminal: ExecutionTerminal,\\n        observation_sha256: String,\\n        snapshot: CallSnapshot,\\n    },\\n    Existing(CallSnapshot),\\n    Inhibited(CallSnapshot),\\n}\\n\\n#[derive(Debug)]\\npub struct DirectToolBridge {\\n    registry: Arc<CallRegistry>,\\n}\\n\\nimpl DirectToolBridge {\\n    #[must_use]\\n    pub fn new(registry: Arc<CallRegistry>) -> Self {\\n        Self { registry }\\n    }\\n\\n    #[must_use]\\n    pub fn registry(&self) -> &Arc<CallRegistry> {\\n        &self.registry\\n    }\\n\\n    pub fn execute(\\n        &self,\\n        call: BoundToolCall,\\n        limits: &BridgeLimits,\\n        mut event_sink: impl FnMut(ExecutionEvent),\\n    ) -> Result<DispatchResult> {\\n        self.execute_fallible(call, limits, move |event| {\\n            event_sink(event);\\n            Ok::<(), String>(())\\n        })\\n    }\\n\\n    /// Execute one direct call while guaranteeing registry terminal closure for\\n    /// every locally observed bridge/runtime/sink failure after spawn claim.\\n    pub fn execute_fallible<E>(\\n        &self,\\n        call: BoundToolCall,\\n        limits: &BridgeLimits,\\n        event_sink: impl FnMut(ExecutionEvent) -> std::result::Result<(), E>,\\n    ) -> Result<DispatchResult>\\n    where\\n        E: Display,\\n    {\\n        self.execute_fallible_with_external_flags(call, limits, [], event_sink)\\n    }\\n\\n    /// Execute one direct call while observing additional caller-owned\\n    /// cancellation flags.  The flags are linked directly into the runtime\\n    /// token; no per-call forwarding/polling thread is created.  Each flag is\\n    /// expected to belong to this call's enclosing scope (normally one turn),\\n    /// never to a process-global cancellation source.\\n    pub fn execute_fallible_with_external_flags<E, I>(\\n        &self,\\n        call: BoundToolCall,\\n        limits: &BridgeLimits,\\n        external_flags: I,\\n        event_sink: impl FnMut(ExecutionEvent) -> std::result::Result<(), E>,\\n    ) -> Result<DispatchResult>\\n    where\\n        E: Display,\\n        I: IntoIterator<Item = Arc<AtomicBool>>,\\n    {\\n        self.execute_fallible_with_deadline(call, limits, external_flags, None, event_sink)\\n    }\\n\\n    /// Preserve the caller's absolute deadline through admission and process\\n    /// execution. It is execution context, not part of the requested effect.\\n    pub fn execute_fallible_with_deadline<E, I>(\\n        &self,\\n        call: BoundToolCall,\\n        limits: &BridgeLimits,\\n        external_flags: I,\\n        deadline: Option<Instant>,\\n        mut event_sink: impl FnMut(ExecutionEvent) -> std::result::Result<(), E>,\\n    ) -> Result<DispatchResult>\\n    where\\n        E: Display,\\n        I: IntoIterator<Item = Arc<AtomicBool>>,\\n    {\\n        limits.validate()?;\\n        call.validate()?;\\n        let runtime_limits = limits.effective_runtime();\\n        validate_runtime_request(&call.request, call.pty, &runtime_limits)?;\\n        // Materialize the caller-owned flags once.  Besides avoiding a\\n        // second iterator traversal, this lets us publish an already-set\\n        // enclosing cancellation into the registry before spawn admission.\\n        // Without that step an already-cancelled turn could still win the\\n        // claim race and appear uncancelled in registry history.\\n        let external_flags = external_flags.into_iter().collect::<Vec<_>>();\\n        let registry_request = call.registry_request();\\n        let begin = self\\n            .registry\\n            .begin(call.key.clone(), registry_request.clone())?;\\n        let began_new = begin.disposition == BeginDisposition::New;\\n        if external_flags\\n            .iter()\\n            .any(|flag| flag.load(Ordering::SeqCst))\\n            && !matches!(\\n                begin.snapshot.state,\\n                trillionnium_owner_open_call_registry::EffectiveState::Terminal { .. }\\n            )\\n        {\\n            self.registry.request_cancel(&call.key)?;\\n        }\\n        let (generation, cancellation) = match self\\n            .registry\\n            .claim_spawn(&call.key, &call.request_sha256)\\n        {\\n            Err(error) => {\\n                // A fresh `begin` leaves an Accepted marker until the spawn\\n                // generation is claimed.  If claim fails before that boundary\\n                // (for example, generation exhaustion), remove only the exact\\n                // untouched entry.  If another caller raced the lifecycle, or\\n                // this was an Existing acceptance, fence Accepted state so a\\n                // retry cannot turn a local failure into a redispatch.\\n                let rollback = if began_new {\\n                    self.registry.rollback_accept(&call.key, &registry_request)\\n                } else {\\n                    Ok(false)\\n                };\\n                if !matches!(rollback, Ok(true) | Ok(false)) || !began_new {\\n                    let _ = self.registry.inhibit_spawn(&call.key);\\n                }\\n                return Err(BridgeError::Registry(error));\\n            }\\n            Ok(claim) => match claim {\\n                SpawnClaim::Granted {\\n                    generation,\\n                    cancellation,\\n                    ..\\n                } => (generation, cancellation),\\n                SpawnClaim::Existing(snapshot) => return Ok(DispatchResult::Existing(snapshot)),\\n                SpawnClaim::Inhibited(snapshot) => return Ok(DispatchResult::Inhibited(snapshot)),\\n            },\\n        };\\n\\n        // Close the small race between the pre-claim check and claim_spawn.\\n        // The runtime token will also observe this flag, while this registry\\n        // mutation preserves causal cancellation history for the call.\\n        if external_flags\\n            .iter()\\n            .any(|flag| flag.load(Ordering::SeqCst))\\n        {\\n            self.registry.request_cancel(&call.key)?;\\n        }\\n\\n        // The registry signal is the authoritative per-call cancellation\\n        // source.  Enclosing flags (such as a turn cancellation) are observed\\n        // alongside it by the runtime token, so cancellation remains targeted\\n        // without a forwarding monitor thread.\\n        let runtime_cancellation = RuntimeCancellationToken::from_shared_flags(\\n            std::iter::once(cancellation.shared_flag()).chain(external_flags),\\n        )\\n        .with_deadline(deadline);\\n\\n        let mut digest = ObservationDigest::new(\\n            &call.key.call_id,\\n            call.request.tool_name(),\\n            call.target_id.as_deref(),\\n            generation,\\n        );\\n        let mut registry_observation_error = None::<RegistryError>;\\n        let mut sink_failure = None::<SinkFailure>;\\n        let mut observation_sequence_exhausted = false;\\n        let sink_cancellation = runtime_cancellation.clone();\\n        let key = call.key.clone();\\n        let registry = Arc::clone(&self.registry);\\n        let mut observe = |event: ExecutionEvent| {\\n            // The ordinal is part of the authenticated observation stream.\\n            // If it cannot advance, stop accepting events and cancel the\\n            // owned process rather than hashing a duplicate MAX ordinal.\\n            if digest.update(&event).is_err() {\\n                observation_sequence_exhausted = true;\\n                sink_cancellation.cancel();\\n                return;\\n            }\\n            if let ExecutionEventKind::Started { pid } = &event.kind\\n                && let Err(error) = registry.record_pid(&key, generation, *pid)\\n                && registry_observation_error.is_none()\\n            {\\n                registry_observation_error = Some(error);\\n            }\\n            if sink_failure.is_none() {\\n                match catch_unwind(AssertUnwindSafe(|| event_sink(event.clone()))) {\\n                    Ok(Ok(())) => {}\\n                    Ok(Err(error)) => {\\n                        sink_failure = Some(SinkFailure::Failed(error.to_string()));\\n                        sink_cancellation.cancel();\\n                    }\\n                    Err(_) => {\\n                        sink_failure = Some(SinkFailure::Panicked);\\n                        sink_cancellation.cancel();\\n                    }\\n                }\\n            }\\n        };\\n\\n        let runtime_result = match (call.request.clone(), call.pty) {\\n            (DirectToolRequest::Shell(request), Some(size)) => execute_shell_pty(\\n                request,\\n                size,\\n                &runtime_limits,\\n                &runtime_cancellation,\\n                &mut observe,\\n            ),\\n            (DirectToolRequest::Adb(request), Some(size)) => execute_adb_pty(\\n                request,\\n                size,\\n                &runtime_limits,\\n                &runtime_cancellation,\\n                &mut observe,\\n            ),\\n            (DirectToolRequest::Shell(request), None) => execute_shell(\\n                request,\\n                &runtime_limits,\\n                &runtime_cancellation,\\n                &mut observe,\\n            ),\\n            (DirectToolRequest::Adb(request), None) => execute_adb(\\n                request,\\n                &runtime_limits,\\n                &runtime_cancellation,\\n                &mut observe,\\n            ),\\n        };\\n\\n        let (terminal, runtime_rejection) = match runtime_result {\\n            Ok(terminal) => (terminal, None),\\n            Err(error) => {\\n                let message = error.to_string();\\n                let terminal = synthetic_terminal(\\n                    TerminalKind::IoError,\\n                    format!(\\\"preflight_runtime_drift: {message}\\\"),\\n                );\\n                emit_synthetic_terminal(&call, &terminal, &mut observe);\\n                (terminal, Some(message))\\n            }\\n        };\\n\\n        // A sink-triggered cancellation, the registry signal, or an enclosing\\n        // turn flag may have fired while the process was running.  Reflect it\\n        // in the call registry before recording the terminal so snapshots and\\n        // history carry the same causality as the runtime result.\\n        let cancellation_observed = runtime_cancellation.is_cancelled();\\n        let observation_sha256 = digest.finish();\\n        if cancellation_observed {\\n            self.registry.request_cancel(&call.key)?;\\n        }\\n        self.registry.complete(\\n            &call.key,\\n            generation,\\n            terminal_record(&terminal, observation_sha256.clone())?,\\n        )?;\\n        let snapshot = self.registry.snapshot(&call.key)?;\\n\\n        if let Some(error) = registry_observation_error {\\n            return Err(BridgeError::RegistryObservation(error));\\n        }\\n        if observation_sequence_exhausted {\\n            return Err(invalid(\\\"observation sequence exhausted\\\"));\\n        }\\n        if let Some(failure) = sink_failure {\\n            return Err(match failure {\\n                SinkFailure::Failed(message) => BridgeError::EventSinkFailed(message),\\n                SinkFailure::Panicked => BridgeError::EventSinkPanicked,\\n            });\\n        }\\n        if let Some(message) = runtime_rejection {\\n            return Err(BridgeError::RuntimeRejected(message));\\n        }\\n\\n        Ok(DispatchResult::Executed {\\n            generation,\\n            terminal,\\n            observation_sha256,\\n            snapshot,\\n        })\\n    }\\n}\\n\\n#[derive(Debug)]\\nenum SinkFailure {\\n    Failed(String),\\n    Panicked,\\n}\\n\\n#[derive(Debug)]\\nstruct ObservationDigest {\\n    hasher: Option<Sha256>,\\n    next_ordinal: u64,\\n}\\n\\nimpl ObservationDigest {\\n    fn new(call_id: &str, tool: &str, target_id: Option<&str>, generation: u64) -> Self {\\n        let mut hasher = Sha256::new();\\n        field(\\n            &mut hasher,\\n            b\\\"schema\\\",\\n            b\\\"trillionnium.owner-open.local-observation.v1\\\",\\n        );\\n        field(&mut hasher, b\\\"call_id\\\", call_id.as_bytes());\\n        field(&mut hasher, b\\\"tool\\\", tool.as_bytes());\\n        field(\\n            &mut hasher,\\n            b\\\"target_id\\\",\\n            target_id.unwrap_or_default().as_bytes(),\\n        );\\n        field(&mut hasher, b\\\"spawn_generation\\\", &generation.to_be_bytes());\\n        Self {\\n            hasher: Some(hasher),\\n            next_ordinal: 0,\\n        }\\n    }\\n\\n    fn update(&mut self, event: &ExecutionEvent) -> std::result::Result<(), ()> {\\n        let Some(hasher) = self.hasher.as_mut() else {\\n            return Err(());\\n        };\\n        let next_ordinal = self.next_ordinal.checked_add(1).ok_or(())?;\\n        field(hasher, b\\\"event_ordinal\\\", &self.next_ordinal.to_be_bytes());\\n        self.next_ordinal = next_ordinal;\\n        match &event.kind {\\n            ExecutionEventKind::Accepted => field(hasher, b\\\"kind\\\", b\\\"accepted\\\"),\\n            ExecutionEventKind::Started { pid } => {\\n                field(hasher, b\\\"kind\\\", b\\\"started\\\");\\n                field(hasher, b\\\"pid\\\", &pid.to_be_bytes());\\n            }\\n            ExecutionEventKind::Output { stream, bytes } => {\\n                field(hasher, b\\\"kind\\\", b\\\"output\\\");\\n                field(\\n                    hasher,\\n                    b\\\"stream\\\",\\n                    match stream {\\n                        StreamKind::Stdout => b\\\"stdout\\\",\\n                        StreamKind::Stderr => b\\\"stderr\\\",\\n                        StreamKind::Pty => b\\\"pty\\\",\\n                    },\\n                );\\n                field(hasher, b\\\"bytes\\\", bytes);\\n            }\\n            ExecutionEventKind::Terminal(terminal) => {\\n                field(hasher, b\\\"kind\\\", b\\\"terminal\\\");\\n                field(hasher, b\\\"terminal_kind\\\", terminal.kind.as_str().as_bytes());\\n                field(\\n                    hasher,\\n                    b\\\"exit_code\\\",\\n                    &terminal.exit_code.unwrap_or(i32::MIN).to_be_bytes(),\\n                );\\n                field(\\n                    hasher,\\n                    b\\\"signal\\\",\\n                    &terminal.signal.unwrap_or(i32::MIN).to_be_bytes(),\\n                );\\n                field(\\n                    hasher,\\n                    b\\\"stdout_bytes\\\",\\n                    &terminal.stdout_bytes.to_be_bytes(),\\n                );\\n                field(\\n                    hasher,\\n                    b\\\"stderr_bytes\\\",\\n                    &terminal.stderr_bytes.to_be_bytes(),\\n                );\\n                field(\\n                    hasher,\\n                    b\\\"output_truncated\\\",\\n                    &[u8::from(terminal.output_truncated)],\\n                );\\n                field(hasher, b\\\"elapsed_ms\\\", &terminal.elapsed_ms.to_be_bytes());\\n                field(\\n                    hasher,\\n                    b\\\"error\\\",\\n                    terminal.error.as_deref().unwrap_or_default().as_bytes(),\\n                );\\n            }\\n        }\\n        Ok(())\\n    }\\n\\n    fn finish(&mut self) -> String {\\n        let hasher = self\\n            .hasher\\n            .take()\\n            .expect(\\\"observation digest is finalized exactly once\\\");\\n        hex_lower(&hasher.finalize())\\n    }\\n}\\n\\nfn emit_synthetic_terminal(\\n    call: &BoundToolCall,\\n    terminal: &ExecutionTerminal,\\n    observe: &mut dyn FnMut(ExecutionEvent),\\n) {\\n    observe(ExecutionEvent {\\n        call_id: call.key.call_id.clone(),\\n        target_id: call.target_id.clone(),\\n        tool: call.request.tool_kind(),\\n        seq: 0,\\n        elapsed_ms: 0,\\n        kind: ExecutionEventKind::Accepted,\\n    });\\n    observe(ExecutionEvent {\\n        call_id: call.key.call_id.clone(),\\n        target_id: call.target_id.clone(),\\n        tool: call.request.tool_kind(),\\n        seq: 1,\\n        elapsed_ms: terminal.elapsed_ms,\\n        kind: ExecutionEventKind::Terminal(terminal.clone()),\\n    });\\n}\\n\\nfn synthetic_terminal(kind: TerminalKind, error: String) -> ExecutionTerminal {\\n    ExecutionTerminal {\\n        kind,\\n        exit_code: None,\\n        signal: None,\\n        stdout_bytes: 0,\\n        stderr_bytes: 0,\\n        output_truncated: false,\\n        elapsed_ms: 0,\\n        error: Some(error),\\n    }\\n}\\n\\nfn terminal_record(\\n    terminal: &ExecutionTerminal,\\n    observation_sha256: String,\\n) -> Result<TerminalRecord> {\\n    require_sha256(&observation_sha256, \\\"observation_sha256\\\")?;\\n    Ok(TerminalRecord::new(\\n        terminal.kind.as_str(),\\n        terminal.exit_code,\\n        terminal.signal,\\n        observation_sha256,\\n        terminal.stdout_bytes,\\n        terminal.stderr_bytes,\\n    ))\\n}\\n\\nfn validate_runtime_request(\\n    request: &DirectToolRequest,\\n    pty: Option<PtySize>,\\n    limits: &MechanicalLimits,\\n) -> Result<()> {\\n    limits\\n        .validate()\\n        .map_err(|error| invalid(error.to_string()))?;\\n    match request {\\n        DirectToolRequest::Shell(request) => {\\n            validate_common(\\n                &request.call_id,\\n                request.target_id.as_deref(),\\n                request.cwd.as_deref(),\\n                &request.env,\\n                &request.stdin,\\n                limits,\\n            )?;\\n            match &request.invocation {\\n                ShellInvocation::Command(command) => {\\n                    validate_text(\\n                        command,\\n                        \\\"shell command\\\",\\n                        limits.max_total_argument_bytes,\\n                        false,\\n                    )?;\\n                    validate_path(\\n                        &request.shell_executable,\\n                        \\\"shell executable\\\",\\n                        limits.max_cwd_bytes,\\n                        false,\\n                    )?;\\n                }\\n                ShellInvocation::Argv(argv) => validate_argv(argv, \\\"shell argv\\\", limits)?,\\n            }\\n        }\\n        DirectToolRequest::Adb(request) => {\\n            validate_common(\\n                &request.call_id,\\n                request.target_id.as_deref(),\\n                request.cwd.as_deref(),\\n                &request.env,\\n                &request.stdin,\\n                limits,\\n            )?;\\n            validate_argv(&request.argv, \\\"adb argv\\\", limits)?;\\n            validate_path(\\n                &request.adb_executable,\\n                \\\"adb executable\\\",\\n                limits.max_cwd_bytes,\\n                true,\\n            )?;\\n        }\\n    }\\n    if pty.is_some_and(|size| size.rows == 0 || size.cols == 0) {\\n        return Err(invalid(\\\"PTY rows and cols must be non-zero\\\"));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_common(\\n    call_id: &str,\\n    target_id: Option<&str>,\\n    cwd: Option<&Path>,\\n    environment: &std::collections::BTreeMap<String, Option<String>>,\\n    stdin: &[u8],\\n    limits: &MechanicalLimits,\\n) -> Result<()> {\\n    if call_id.is_empty()\\n        || call_id.len() > limits.max_call_id_bytes\\n        || !call_id\\n            .bytes()\\n            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':'))\\n    {\\n        return Err(invalid(\\\"call_id is empty, oversized, or malformed\\\"));\\n    }\\n    if let Some(target_id) = target_id {\\n        validate_text(target_id, \\\"target_id\\\", limits.max_target_id_bytes, false)?;\\n    }\\n    if let Some(cwd) = cwd {\\n        validate_path(cwd, \\\"cwd\\\", limits.max_cwd_bytes, false)?;\\n    }\\n    if stdin.len() > limits.max_stdin_bytes {\\n        return Err(invalid(\\\"stdin exceeds the configured byte bound\\\"));\\n    }\\n    if environment.len() > limits.max_environment_items {\\n        return Err(invalid(\\\"environment delta has too many entries\\\"));\\n    }\\n    let mut total = 0usize;\\n    for (key, value) in environment {\\n        if key.is_empty() || key.contains('=') || key.as_bytes().contains(&0) {\\n            return Err(invalid(\\\"environment key is empty or malformed\\\"));\\n        }\\n        total = total\\n            .checked_add(key.len())\\n            .ok_or_else(|| invalid(\\\"environment byte count overflow\\\"))?;\\n        if let Some(value) = value {\\n            if value.as_bytes().contains(&0) {\\n                return Err(invalid(\\\"environment value contains NUL\\\"));\\n            }\\n            total = total\\n                .checked_add(value.len())\\n                .ok_or_else(|| invalid(\\\"environment byte count overflow\\\"))?;\\n        }\\n    }\\n    if total > limits.max_environment_bytes {\\n        return Err(invalid(\\n            \\\"environment delta exceeds the configured byte bound\\\",\\n        ));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_argv(argv: &[String], label: &str, limits: &MechanicalLimits) -> Result<()> {\\n    if argv.is_empty() {\\n        return Err(invalid(format!(\\\"{label} must not be empty\\\")));\\n    }\\n    if argv.len() > limits.max_argv_items {\\n        return Err(invalid(format!(\\\"{label} has too many elements\\\")));\\n    }\\n    let mut total = 0usize;\\n    for argument in argv {\\n        validate_text(argument, label, limits.max_argument_bytes, true)?;\\n        total = total\\n            .checked_add(argument.len())\\n            .ok_or_else(|| invalid(format!(\\\"{label} byte count overflow\\\")))?;\\n    }\\n    if total > limits.max_total_argument_bytes {\\n        return Err(invalid(format!(\\\"{label} exceeds the total byte bound\\\")));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_text(value: &str, label: &str, maximum: usize, allow_empty: bool) -> Result<()> {\\n    if (!allow_empty && value.is_empty()) || value.len() > maximum || value.as_bytes().contains(&0)\\n    {\\n        return Err(invalid(format!(\\n            \\\"{label} is empty, oversized, or contains NUL\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_path(path: &Path, label: &str, maximum: usize, allow_empty: bool) -> Result<()> {\\n    let bytes = path.as_os_str().as_bytes();\\n    if (!allow_empty && bytes.is_empty()) || bytes.len() > maximum || bytes.contains(&0) {\\n        return Err(invalid(format!(\\n            \\\"{label} is empty, oversized, or contains NUL\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn sha256_hex(value: &[u8]) -> String {\\n    hex_lower(&Sha256::digest(value))\\n}\\n\\nfn field(hasher: &mut Sha256, name: &[u8], value: &[u8]) {\\n    hasher.update((name.len() as u64).to_be_bytes());\\n    hasher.update(name);\\n    hasher.update((value.len() as u64).to_be_bytes());\\n    hasher.update(value);\\n}\\n\\nfn hex_lower(value: &[u8]) -> String {\\n    use std::fmt::Write as _;\\n\\n    let mut encoded = String::with_capacity(value.len() * 2);\\n    for byte in value {\\n        write!(&mut encoded, \\\"{byte:02x}\\\").expect(\\\"writing to String cannot fail\\\");\\n    }\\n    encoded\\n}\\n\\nfn require_sha256(value: &str, label: &str) -> Result<()> {\\n    if value.len() != 64\\n        || !value\\n            .bytes()\\n            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))\\n    {\\n        return Err(invalid(format!(\\\"{label} must be a lowercase SHA-256\\\")));\\n    }\\n    Ok(())\\n}\\n\\nfn invalid(message: impl Into<String>) -> BridgeError {\\n    BridgeError::InvalidRequest(message.into())\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    #[test]\\n    fn cancellation_poll_caps_runtime_wait_without_widening_a_faster_setting() {\\n        let mut limits = BridgeLimits::default();\\n        limits.runtime.poll_interval = Duration::from_secs(1);\\n        limits.cancellation_poll = Duration::from_millis(2);\\n        assert_eq!(\\n            limits.effective_runtime().poll_interval,\\n            Duration::from_millis(2)\\n        );\\n\\n        limits.runtime.poll_interval = Duration::from_millis(1);\\n        assert_eq!(\\n            limits.effective_runtime().poll_interval,\\n            Duration::from_millis(1)\\n        );\\n    }\\n\\n    #[test]\\n    fn observation_digest_rejects_ordinal_overflow() {\\n        let mut digest = ObservationDigest::new(\\\"call\\\", \\\"shell.exec\\\", None, 1);\\n        digest.next_ordinal = u64::MAX;\\n        let event = ExecutionEvent {\\n            call_id: \\\"call\\\".to_string(),\\n            target_id: None,\\n            tool: ToolKind::ShellExec,\\n            seq: 0,\\n            elapsed_ms: 0,\\n            kind: ExecutionEventKind::Accepted,\\n        };\\n\\n        assert!(digest.update(&event).is_err());\\n        assert_eq!(digest.next_ordinal, u64::MAX);\\n        assert!(digest.update(&event).is_err());\\n    }\\n}\\n\"},{\"path\":\"crates/trillionnium-owner-open-call-registry/src/lib.rs\",\"sha\":\"39af96d8704cdc7885150041f2b6fd6aefc16c2f\",\"text\":\"//! Concurrent owner-open call registry.\\n//!\\n//! The registry is a mechanism-only in-memory state machine. It binds one call\\n//! ID to one exact request inside one turn scope, grants at most one spawn\\n//! generation, carries cancellation, records disconnect uncertainty and accepts\\n//! a late terminal result. It does not interpret command meaning, approve a\\n//! tool, retry an effect or confer execution authority.\\n\\nuse std::collections::{HashMap, VecDeque};\\nuse std::error::Error;\\nuse std::fmt::{Display, Formatter};\\nuse std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};\\nuse std::sync::{Arc, Mutex, MutexGuard};\\n\\n// Registry state is partitioned by a versioned, deterministic hash.  The\\n// count is deliberately fixed for this state schema: changing it changes the\\n// ownership of existing keys and therefore requires a migration, rather than\\n// silently rehashing a live registry.\\nconst REGISTRY_SHARD_COUNT: usize = 64;\\nconst REGISTRY_SHARD_HASH_VERSION: u8 = 1;\\nconst FNV_OFFSET_BASIS: u64 = 0xcbf29ce484222325;\\nconst FNV_PRIME: u64 = 0x00000100000001b3;\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub enum RegistryError {\\n    InvalidRequest(String),\\n    NotFound,\\n    CallIdConflict,\\n    RequestDigestMismatch,\\n    InvalidTransition(&'static str),\\n    SpawnGenerationMismatch,\\n    PidConflict,\\n    TerminalConflict,\\n    CapacityExhausted,\\n    GenerationExhausted,\\n    StatePoisoned,\\n}\\n\\nimpl Display for RegistryError {\\n    fn fmt(&self, formatter: &mut Formatter<'_>) -> std::fmt::Result {\\n        match self {\\n            Self::InvalidRequest(message) => {\\n                write!(\\n                    formatter,\\n                    \\\"invalid owner-open call registry request: {message}\\\"\\n                )\\n            }\\n            Self::NotFound => formatter.write_str(\\\"owner-open call is not registered\\\"),\\n            Self::CallIdConflict => formatter\\n                .write_str(\\\"owner-open call_id is already bound to different request bytes\\\"),\\n            Self::RequestDigestMismatch => formatter\\n                .write_str(\\\"owner-open call request digest does not match the registered call\\\"),\\n            Self::InvalidTransition(message) => {\\n                write!(formatter, \\\"invalid owner-open call transition: {message}\\\")\\n            }\\n            Self::SpawnGenerationMismatch => formatter\\n                .write_str(\\\"owner-open spawn generation does not match the registered call\\\"),\\n            Self::PidConflict => {\\n                formatter.write_str(\\\"owner-open call already records a different process identity\\\")\\n            }\\n            Self::TerminalConflict => formatter\\n                .write_str(\\\"owner-open call already records a different terminal observation\\\"),\\n            Self::CapacityExhausted => {\\n                formatter.write_str(\\\"owner-open call registry capacity is exhausted\\\")\\n            }\\n            Self::GenerationExhausted => {\\n                formatter.write_str(\\\"owner-open spawn generation is exhausted\\\")\\n            }\\n            Self::StatePoisoned => formatter.write_str(\\\"owner-open call registry lock is poisoned\\\"),\\n        }\\n    }\\n}\\n\\nimpl Error for RegistryError {}\\n\\npub type Result<T> = std::result::Result<T, RegistryError>;\\n\\n/// Hard upper bounds for caller-provided registry limits.\\n///\\n/// `RegistryLimits` is part of the local configuration surface, so checking\\n/// only for zero is not enough: a malformed configuration could otherwise\\n/// make an attacker-controlled admission path reserve an effectively\\n/// unbounded number of entries or retain an unbounded event history.  The\\n/// defaults remain deliberately below these ceilings; deployments may lower\\n/// them, but never raise them past the schema-level bound.\\npub const MAX_REGISTRY_ENTRIES: usize = 1_048_576;\\npub const MAX_HISTORY_PER_CALL: usize = 16_384;\\npub const MAX_ID_BYTES: usize = 4_096;\\npub const MAX_TOOL_BYTES: usize = 64 * 1024;\\npub const MAX_TARGET_BYTES: usize = 1_048_576;\\n\\n/// Bound the total number of retained history slots implied by a registry\\n/// configuration.  Histories are allocated lazily, but this product still\\n/// provides a useful worst-case memory fence for a configuration review.\\npub const MAX_HISTORY_SLOTS: usize = 16 * 1024 * 1024;\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub struct RegistryLimits {\\n    pub max_entries: usize,\\n    pub max_history_per_call: usize,\\n    pub max_id_bytes: usize,\\n    pub max_tool_bytes: usize,\\n    pub max_target_bytes: usize,\\n}\\n\\nimpl Default for RegistryLimits {\\n    fn default() -> Self {\\n        Self {\\n            max_entries: 4_096,\\n            max_history_per_call: 64,\\n            max_id_bytes: 256,\\n            max_tool_bytes: 256,\\n            max_target_bytes: 4_096,\\n        }\\n    }\\n}\\n\\nimpl RegistryLimits {\\n    pub fn validate(&self) -> Result<()> {\\n        if self.max_entries == 0\\n            || self.max_history_per_call == 0\\n            || self.max_id_bytes == 0\\n            || self.max_tool_bytes == 0\\n            || self.max_target_bytes == 0\\n        {\\n            return Err(invalid(\\\"registry limits must be non-zero\\\"));\\n        }\\n        if self.max_entries > MAX_REGISTRY_ENTRIES\\n            || self.max_history_per_call > MAX_HISTORY_PER_CALL\\n            || self.max_id_bytes > MAX_ID_BYTES\\n            || self.max_tool_bytes > MAX_TOOL_BYTES\\n            || self.max_target_bytes > MAX_TARGET_BYTES\\n        {\\n            return Err(invalid(format!(\\n                \\\"registry limits exceed hard bounds (entries <= {MAX_REGISTRY_ENTRIES}, history <= {MAX_HISTORY_PER_CALL}, id <= {MAX_ID_BYTES}, tool <= {MAX_TOOL_BYTES}, target <= {MAX_TARGET_BYTES})\\\"\\n            )));\\n        }\\n        if self\\n            .max_entries\\n            .checked_mul(self.max_history_per_call)\\n            .is_none_or(|slots| slots > MAX_HISTORY_SLOTS)\\n        {\\n            return Err(invalid(format!(\\n                \\\"registry entry/history product exceeds hard bound {MAX_HISTORY_SLOTS}\\\"\\n            )));\\n        }\\n        Ok(())\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq, Hash)]\\npub struct TurnScope {\\n    pub session_id: String,\\n    pub profile_id: String,\\n    pub task_id: String,\\n    pub turn_id: String,\\n    pub turn_stream_id: String,\\n}\\n\\nimpl TurnScope {\\n    pub fn new(\\n        session_id: impl Into<String>,\\n        profile_id: impl Into<String>,\\n        task_id: impl Into<String>,\\n        turn_id: impl Into<String>,\\n        turn_stream_id: impl Into<String>,\\n    ) -> Self {\\n        Self {\\n            session_id: session_id.into(),\\n            profile_id: profile_id.into(),\\n            task_id: task_id.into(),\\n            turn_id: turn_id.into(),\\n            turn_stream_id: turn_stream_id.into(),\\n        }\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq, Hash)]\\npub struct CallKey {\\n    pub scope: TurnScope,\\n    pub call_id: String,\\n}\\n\\nimpl CallKey {\\n    pub fn new(scope: TurnScope, call_id: impl Into<String>) -> Self {\\n        Self {\\n            scope,\\n            call_id: call_id.into(),\\n        }\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub struct CallRequest {\\n    pub request_sha256: String,\\n    pub binding_fingerprint: String,\\n    pub tool: String,\\n    pub target_id: Option<String>,\\n}\\n\\nimpl CallRequest {\\n    pub fn new(\\n        request_sha256: impl Into<String>,\\n        binding_fingerprint: impl Into<String>,\\n        tool: impl Into<String>,\\n        target_id: Option<String>,\\n    ) -> Self {\\n        Self {\\n            request_sha256: request_sha256.into(),\\n            binding_fingerprint: binding_fingerprint.into(),\\n            tool: tool.into(),\\n            target_id,\\n        }\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub struct TerminalRecord {\\n    pub terminal_kind: String,\\n    pub exit_code: Option<i32>,\\n    pub signal: Option<i32>,\\n    pub observation_sha256: String,\\n    pub stdout_bytes: u64,\\n    pub stderr_bytes: u64,\\n}\\n\\nimpl TerminalRecord {\\n    pub fn new(\\n        terminal_kind: impl Into<String>,\\n        exit_code: Option<i32>,\\n        signal: Option<i32>,\\n        observation_sha256: impl Into<String>,\\n        stdout_bytes: u64,\\n        stderr_bytes: u64,\\n    ) -> Self {\\n        Self {\\n            terminal_kind: terminal_kind.into(),\\n            exit_code,\\n            signal,\\n            observation_sha256: observation_sha256.into(),\\n            stdout_bytes,\\n            stderr_bytes,\\n        }\\n    }\\n}\\n\\n#[derive(Debug, Clone)]\\npub struct CancellationSignal(Arc<AtomicBool>);\\n\\nimpl CancellationSignal {\\n    /// Return the per-call cancellation flag for a lower-level runtime that\\n    /// can observe linked scopes directly.  The flag is never shared across\\n    /// registry entries unless an enclosing caller explicitly supplies it.\\n    #[must_use]\\n    pub fn shared_flag(&self) -> Arc<AtomicBool> {\\n        Arc::clone(&self.0)\\n    }\\n\\n    #[must_use]\\n    pub fn is_cancelled(&self) -> bool {\\n        self.0.load(Ordering::SeqCst)\\n    }\\n\\n    /// Returns true only for the first cancellation request.\\n    pub fn cancel(&self) -> bool {\\n        !self.0.swap(true, Ordering::SeqCst)\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub enum CallEventKind {\\n    Accepted,\\n    /// The accepted call was fenced before spawn after a local failure that\\n    /// could not prove the entry was still untouched.  This is deliberately\\n    /// distinct from `ConnectionLost`: the transport may still be healthy,\\n    /// but the call is no longer eligible for a spawn claim.\\n    SpawnInhibited,\\n    SpawnClaimed {\\n        generation: u64,\\n    },\\n    PidObserved {\\n        generation: u64,\\n        pid: u32,\\n    },\\n    CancelRequested,\\n    ConnectionLost,\\n    ConnectionAttached,\\n    TerminalRecorded {\\n        generation: u64,\\n        terminal: TerminalRecord,\\n    },\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub struct CallEvent {\\n    pub seq: u64,\\n    pub kind: CallEventKind,\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub enum EffectiveState {\\n    Accepted,\\n    CancelledBeforeSpawn,\\n    Started {\\n        generation: u64,\\n        pid: Option<u32>,\\n    },\\n    ProvenNotStartedAfterDisconnect,\\n    UnknownAfterDisconnect {\\n        generation: u64,\\n        pid: Option<u32>,\\n    },\\n    Terminal {\\n        generation: u64,\\n        terminal: TerminalRecord,\\n    },\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub struct CallSnapshot {\\n    pub key: CallKey,\\n    pub request: CallRequest,\\n    pub state: EffectiveState,\\n    pub cancellation_requested: bool,\\n    pub connection_lost: bool,\\n    pub earliest_history_seq: u64,\\n    pub next_event_seq: u64,\\n}\\n\\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\\npub enum BeginDisposition {\\n    New,\\n    Existing,\\n}\\n\\n#[derive(Debug, Clone)]\\npub struct BeginResult {\\n    pub disposition: BeginDisposition,\\n    pub snapshot: CallSnapshot,\\n    pub cancellation: CancellationSignal,\\n}\\n\\n#[derive(Debug, Clone)]\\npub enum SpawnClaim {\\n    Granted {\\n        generation: u64,\\n        cancellation: CancellationSignal,\\n        snapshot: CallSnapshot,\\n    },\\n    Existing(CallSnapshot),\\n    Inhibited(CallSnapshot),\\n}\\n\\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\\npub enum MutationOutcome {\\n    Applied,\\n    Idempotent,\\n}\\n\\n#[derive(Debug, Clone)]\\nenum DispatchState {\\n    Accepted {\\n        spawn_inhibited: bool,\\n    },\\n    Started {\\n        generation: u64,\\n        pid: Option<u32>,\\n    },\\n    Terminal {\\n        generation: u64,\\n        terminal: TerminalRecord,\\n    },\\n}\\n\\n#[derive(Debug, Clone)]\\nstruct Entry {\\n    key: CallKey,\\n    request: CallRequest,\\n    dispatch: DispatchState,\\n    connection_lost: bool,\\n    cancellation: CancellationSignal,\\n    history: VecDeque<CallEvent>,\\n    next_event_seq: u64,\\n}\\n\\nimpl Entry {\\n    fn effective_state(&self) -> EffectiveState {\\n        match &self.dispatch {\\n            DispatchState::Accepted { spawn_inhibited } => {\\n                if self.cancellation.is_cancelled() {\\n                    EffectiveState::CancelledBeforeSpawn\\n                } else if *spawn_inhibited || self.connection_lost {\\n                    EffectiveState::ProvenNotStartedAfterDisconnect\\n                } else {\\n                    EffectiveState::Accepted\\n                }\\n            }\\n            DispatchState::Started { generation, pid } => {\\n                if self.connection_lost {\\n                    EffectiveState::UnknownAfterDisconnect {\\n                        generation: *generation,\\n                        pid: *pid,\\n                    }\\n                } else {\\n                    EffectiveState::Started {\\n                        generation: *generation,\\n                        pid: *pid,\\n                    }\\n                }\\n            }\\n            DispatchState::Terminal {\\n                generation,\\n                terminal,\\n            } => EffectiveState::Terminal {\\n                generation: *generation,\\n                terminal: terminal.clone(),\\n            },\\n        }\\n    }\\n\\n    fn snapshot(&self) -> CallSnapshot {\\n        CallSnapshot {\\n            key: self.key.clone(),\\n            request: self.request.clone(),\\n            state: self.effective_state(),\\n            cancellation_requested: self.cancellation.is_cancelled(),\\n            connection_lost: self.connection_lost,\\n            earliest_history_seq: self\\n                .history\\n                .front()\\n                .map_or(self.next_event_seq, |event| event.seq),\\n            next_event_seq: self.next_event_seq,\\n        }\\n    }\\n\\n    fn push_event(&mut self, kind: CallEventKind, max_history: usize) {\\n        let event = CallEvent {\\n            seq: self.next_event_seq,\\n            kind,\\n        };\\n        self.next_event_seq = self.next_event_seq.saturating_add(1);\\n        if self.history.len() == max_history {\\n            self.history.pop_front();\\n        }\\n        self.history.push_back(event);\\n    }\\n}\\n\\n#[derive(Debug)]\\nstruct ShardState {\\n    entries: HashMap<CallKey, Entry>,\\n}\\n\\n#[derive(Debug)]\\npub struct CallRegistry {\\n    limits: RegistryLimits,\\n    shards: Vec<Mutex<ShardState>>,\\n    entry_count: AtomicUsize,\\n    next_spawn_generation: AtomicU64,\\n    state_poisoned: AtomicBool,\\n}\\n\\nimpl CallRegistry {\\n    pub fn new(limits: RegistryLimits) -> Result<Self> {\\n        limits.validate()?;\\n        Ok(Self {\\n            limits,\\n            shards: (0..REGISTRY_SHARD_COUNT)\\n                .map(|_| {\\n                    Mutex::new(ShardState {\\n                        entries: HashMap::new(),\\n                    })\\n                })\\n                .collect(),\\n            entry_count: AtomicUsize::new(0),\\n            next_spawn_generation: AtomicU64::new(1),\\n            state_poisoned: AtomicBool::new(false),\\n        })\\n    }\\n\\n    pub fn begin(&self, key: CallKey, request: CallRequest) -> Result<BeginResult> {\\n        self.ensure_healthy()?;\\n        self.validate_key(&key)?;\\n        self.validate_request(&request)?;\\n        let mut state = self.lock_shard(&key)?;\\n        if let Some(entry) = state.entries.get(&key) {\\n            if entry.request != request {\\n                return Err(RegistryError::CallIdConflict);\\n            }\\n            return Ok(BeginResult {\\n                disposition: BeginDisposition::Existing,\\n                snapshot: entry.snapshot(),\\n                cancellation: entry.cancellation.clone(),\\n            });\\n        }\\n        self.reserve_entry()?;\\n        let cancellation = CancellationSignal(Arc::new(AtomicBool::new(false)));\\n        let mut entry = Entry {\\n            key: key.clone(),\\n            request,\\n            dispatch: DispatchState::Accepted {\\n                spawn_inhibited: false,\\n            },\\n            connection_lost: false,\\n            cancellation: cancellation.clone(),\\n            history: VecDeque::new(),\\n            next_event_seq: 0,\\n        };\\n        entry.push_event(CallEventKind::Accepted, self.limits.max_history_per_call);\\n        let snapshot = entry.snapshot();\\n        let previous = state.entries.insert(key, entry);\\n        debug_assert!(previous.is_none(), \\\"key was checked under its shard lock\\\");\\n        Ok(BeginResult {\\n            disposition: BeginDisposition::New,\\n            snapshot,\\n            cancellation,\\n        })\\n    }\\n\\n    /// Roll back an acceptance that has not crossed the spawn boundary.\\n    ///\\n    /// This is used when a caller reserves a fresh key and a subsequent\\n    /// pre-spawn registry step fails.  The exact request and every mutable\\n    /// pre-start field are checked while holding the key shard, so a\\n    /// concurrent lifecycle transition can never cause a live or claimed\\n    /// entry to be removed accidentally.  `Ok(false)` means the key was\\n    /// already absent; a present but changed entry is an explicit transition\\n    /// error and must be fenced by the caller instead of being retried.\\n    pub fn rollback_accept(&self, key: &CallKey, request: &CallRequest) -> Result<bool> {\\n        self.ensure_healthy()?;\\n        let mut state = self.lock_shard(key)?;\\n        let Some(entry) = state.entries.get(key) else {\\n            return Ok(false);\\n        };\\n        if entry.request != *request {\\n            return Err(RegistryError::CallIdConflict);\\n        }\\n        let rollbackable = matches!(\\n            entry.dispatch,\\n            DispatchState::Accepted {\\n                spawn_inhibited: false\\n            }\\n        ) && !entry.connection_lost\\n            && !entry.cancellation.is_cancelled()\\n            && entry.history.len() == 1\\n            && matches!(\\n                entry.history.front().map(|event| &event.kind),\\n                Some(CallEventKind::Accepted)\\n            );\\n        if !rollbackable {\\n            return Err(RegistryError::InvalidTransition(\\n                \\\"only an untouched accepted call can be rolled back\\\",\\n            ));\\n        }\\n        let removed = state.entries.remove(key);\\n        debug_assert!(removed.is_some());\\n        self.release_entry();\\n        Ok(true)\\n    }\\n\\n    /// Fence an accepted call against any future spawn claim.\\n    ///\\n    /// Unlike `mark_connection_lost`, this records no transport assertion.\\n    /// It is the fail-closed fallback when a local pre-spawn failure races a\\n    /// lifecycle transition and exact rollback is no longer provable.  The\\n    /// effective state intentionally remains the existing conservative\\n    /// `ProvenNotStartedAfterDisconnect` no-start barrier for compatibility;\\n    /// the history event identifies the actual cause.\\n    pub fn inhibit_spawn(&self, key: &CallKey) -> Result<CallSnapshot> {\\n        self.ensure_healthy()?;\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        if let DispatchState::Accepted { spawn_inhibited } = &mut entry.dispatch\\n            && !*spawn_inhibited\\n        {\\n            *spawn_inhibited = true;\\n            entry.push_event(\\n                CallEventKind::SpawnInhibited,\\n                self.limits.max_history_per_call,\\n            );\\n        }\\n        Ok(entry.snapshot())\\n    }\\n\\n    pub fn claim_spawn(&self, key: &CallKey, request_sha256: &str) -> Result<SpawnClaim> {\\n        self.ensure_healthy()?;\\n        require_sha256(request_sha256, \\\"request_sha256\\\")?;\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get(key).ok_or(RegistryError::NotFound)?;\\n        if entry.request.request_sha256 != request_sha256 {\\n            return Err(RegistryError::RequestDigestMismatch);\\n        }\\n        match &entry.dispatch {\\n            DispatchState::Accepted { spawn_inhibited }\\n                if *spawn_inhibited || entry.cancellation.is_cancelled() =>\\n            {\\n                return Ok(SpawnClaim::Inhibited(entry.snapshot()));\\n            }\\n            DispatchState::Started { .. } | DispatchState::Terminal { .. } => {\\n                return Ok(SpawnClaim::Existing(entry.snapshot()));\\n            }\\n            DispatchState::Accepted { .. } => {}\\n        }\\n\\n        let generation = self.allocate_generation()?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        entry.dispatch = DispatchState::Started {\\n            generation,\\n            pid: None,\\n        };\\n        entry.push_event(\\n            CallEventKind::SpawnClaimed { generation },\\n            self.limits.max_history_per_call,\\n        );\\n        Ok(SpawnClaim::Granted {\\n            generation,\\n            cancellation: entry.cancellation.clone(),\\n            snapshot: entry.snapshot(),\\n        })\\n    }\\n\\n    pub fn record_pid(&self, key: &CallKey, generation: u64, pid: u32) -> Result<MutationOutcome> {\\n        self.ensure_healthy()?;\\n        if pid == 0 {\\n            return Err(invalid(\\\"pid must be non-zero\\\"));\\n        }\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        match &mut entry.dispatch {\\n            DispatchState::Started {\\n                generation: expected,\\n                pid: observed,\\n            } if *expected == generation => match observed {\\n                Some(existing) if *existing == pid => Ok(MutationOutcome::Idempotent),\\n                Some(_) => Err(RegistryError::PidConflict),\\n                None => {\\n                    *observed = Some(pid);\\n                    entry.push_event(\\n                        CallEventKind::PidObserved { generation, pid },\\n                        self.limits.max_history_per_call,\\n                    );\\n                    Ok(MutationOutcome::Applied)\\n                }\\n            },\\n            DispatchState::Started { .. } | DispatchState::Terminal { .. } => {\\n                Err(RegistryError::SpawnGenerationMismatch)\\n            }\\n            DispatchState::Accepted { .. } => Err(RegistryError::InvalidTransition(\\n                \\\"cannot record a pid before spawn is claimed\\\",\\n            )),\\n        }\\n    }\\n\\n    pub fn request_cancel(&self, key: &CallKey) -> Result<CallSnapshot> {\\n        self.ensure_healthy()?;\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        if entry.cancellation.cancel() {\\n            entry.push_event(\\n                CallEventKind::CancelRequested,\\n                self.limits.max_history_per_call,\\n            );\\n        }\\n        Ok(entry.snapshot())\\n    }\\n\\n    pub fn mark_connection_lost(&self, key: &CallKey) -> Result<CallSnapshot> {\\n        self.ensure_healthy()?;\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        if !entry.connection_lost {\\n            entry.connection_lost = true;\\n            if let DispatchState::Accepted { spawn_inhibited } = &mut entry.dispatch {\\n                *spawn_inhibited = true;\\n            }\\n            entry.push_event(\\n                CallEventKind::ConnectionLost,\\n                self.limits.max_history_per_call,\\n            );\\n        }\\n        Ok(entry.snapshot())\\n    }\\n\\n    pub fn mark_connection_attached(&self, key: &CallKey) -> Result<CallSnapshot> {\\n        self.ensure_healthy()?;\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        if entry.connection_lost {\\n            entry.connection_lost = false;\\n            entry.push_event(\\n                CallEventKind::ConnectionAttached,\\n                self.limits.max_history_per_call,\\n            );\\n        }\\n        Ok(entry.snapshot())\\n    }\\n\\n    pub fn complete(\\n        &self,\\n        key: &CallKey,\\n        generation: u64,\\n        terminal: TerminalRecord,\\n    ) -> Result<MutationOutcome> {\\n        self.ensure_healthy()?;\\n        self.validate_terminal(&terminal)?;\\n        let mut state = self.lock_shard(key)?;\\n        let entry = state.entries.get_mut(key).ok_or(RegistryError::NotFound)?;\\n        match &entry.dispatch {\\n            DispatchState::Started {\\n                generation: expected,\\n                ..\\n            } if *expected == generation => {}\\n            DispatchState::Started { .. } => {\\n                return Err(RegistryError::SpawnGenerationMismatch);\\n            }\\n            DispatchState::Terminal {\\n                generation: expected,\\n                terminal: existing,\\n            } if *expected == generation && *existing == terminal => {\\n                return Ok(MutationOutcome::Idempotent);\\n            }\\n            DispatchState::Terminal { .. } => return Err(RegistryError::TerminalConflict),\\n            DispatchState::Accepted { .. } => {\\n                return Err(RegistryError::InvalidTransition(\\n                    \\\"cannot complete a call before spawn is claimed\\\",\\n                ));\\n            }\\n        }\\n        entry.dispatch = DispatchState::Terminal {\\n            generation,\\n            terminal: terminal.clone(),\\n        };\\n        entry.push_event(\\n            CallEventKind::TerminalRecorded {\\n                generation,\\n                terminal,\\n            },\\n            self.limits.max_history_per_call,\\n        );\\n        Ok(MutationOutcome::Applied)\\n    }\\n\\n    pub fn snapshot(&self, key: &CallKey) -> Result<CallSnapshot> {\\n        self.ensure_healthy()?;\\n        let state = self.lock_shard(key)?;\\n        state\\n            .entries\\n            .get(key)\\n            .map(Entry::snapshot)\\n            .ok_or(RegistryError::NotFound)\\n    }\\n\\n    pub fn history_from(&self, key: &CallKey, inclusive_seq: u64) -> Result<Vec<CallEvent>> {\\n        self.ensure_healthy()?;\\n        let state = self.lock_shard(key)?;\\n        let entry = state.entries.get(key).ok_or(RegistryError::NotFound)?;\\n        Ok(entry\\n            .history\\n            .iter()\\n            .filter(|event| event.seq >= inclusive_seq)\\n            .cloned()\\n            .collect())\\n    }\\n\\n    pub fn remove_terminal(&self, key: &CallKey) -> Result<bool> {\\n        self.ensure_healthy()?;\\n        let mut state = self.lock_shard(key)?;\\n        let terminal = state\\n            .entries\\n            .get(key)\\n            .is_some_and(|entry| matches!(entry.dispatch, DispatchState::Terminal { .. }));\\n        if terminal {\\n            let removed = state.entries.remove(key);\\n            debug_assert!(removed.is_some());\\n            self.release_entry();\\n        }\\n        Ok(terminal)\\n    }\\n\\n    pub fn len(&self) -> Result<usize> {\\n        self.ensure_healthy()?;\\n        Ok(self.entry_count.load(Ordering::Acquire))\\n    }\\n\\n    pub fn is_empty(&self) -> Result<bool> {\\n        self.ensure_healthy()?;\\n        Ok(self.entry_count.load(Ordering::Acquire) == 0)\\n    }\\n\\n    /// Number of independent state shards used by this registry.\\n    ///\\n    /// This is exposed for diagnostics and benchmark metadata; it is not a\\n    /// caller-selectable policy knob because changing the count requires a\\n    /// state migration.\\n    #[must_use]\\n    pub fn shard_count(&self) -> usize {\\n        self.shards.len()\\n    }\\n\\n    fn shard_index(&self, key: &CallKey) -> usize {\\n        stable_shard_index(\\n            b\\\"owner-open-call-registry\\\",\\n            &[\\n                &key.scope.session_id,\\n                &key.scope.profile_id,\\n                &key.scope.task_id,\\n                &key.scope.turn_id,\\n                &key.scope.turn_stream_id,\\n                &key.call_id,\\n            ],\\n        )\\n    }\\n\\n    fn lock_shard(&self, key: &CallKey) -> Result<MutexGuard<'_, ShardState>> {\\n        self.shards[self.shard_index(key)].lock().map_err(|_| {\\n            self.state_poisoned.store(true, Ordering::Release);\\n            RegistryError::StatePoisoned\\n        })\\n    }\\n\\n    fn ensure_healthy(&self) -> Result<()> {\\n        if self.state_poisoned.load(Ordering::Acquire) {\\n            return Err(RegistryError::StatePoisoned);\\n        }\\n        // A shard can be poisoned by code that held its mutex directly (for\\n        // example, a diagnostic or a future maintenance operation) before a\\n        // registry method gets a chance to call `lock_shard`.  Inspect the\\n        // mutex poison bits as well as the fast-path latch so aggregate\\n        // observations such as `len` and `is_empty` fail closed immediately.\\n        let shard_poisoned = self.shards.iter().any(Mutex::is_poisoned);\\n        if shard_poisoned {\\n            self.state_poisoned.store(true, Ordering::Release);\\n        }\\n        if self.state_poisoned.load(Ordering::Acquire) {\\n            Err(RegistryError::StatePoisoned)\\n        } else {\\n            Ok(())\\n        }\\n    }\\n\\n    fn reserve_entry(&self) -> Result<()> {\\n        let mut current = self.entry_count.load(Ordering::Acquire);\\n        loop {\\n            if current >= self.limits.max_entries {\\n                return Err(RegistryError::CapacityExhausted);\\n            }\\n            let next = current\\n                .checked_add(1)\\n                .ok_or(RegistryError::CapacityExhausted)?;\\n            match self.entry_count.compare_exchange_weak(\\n                current,\\n                next,\\n                Ordering::AcqRel,\\n                Ordering::Acquire,\\n            ) {\\n                Ok(_) => return Ok(()),\\n                Err(observed) => current = observed,\\n            }\\n        }\\n    }\\n\\n    fn release_entry(&self) {\\n        let previous = self.entry_count.fetch_sub(1, Ordering::AcqRel);\\n        debug_assert!(previous > 0, \\\"call registry entry count underflow\\\");\\n    }\\n\\n    fn allocate_generation(&self) -> Result<u64> {\\n        let mut current = self.next_spawn_generation.load(Ordering::Acquire);\\n        loop {\\n            if current == 0 || current == u64::MAX {\\n                return Err(RegistryError::GenerationExhausted);\\n            }\\n            match self.next_spawn_generation.compare_exchange_weak(\\n                current,\\n                current + 1,\\n                Ordering::AcqRel,\\n                Ordering::Acquire,\\n            ) {\\n                Ok(_) => return Ok(current),\\n                Err(observed) => current = observed,\\n            }\\n        }\\n    }\\n\\n    fn validate_key(&self, key: &CallKey) -> Result<()> {\\n        for (label, value) in [\\n            (\\\"session_id\\\", key.scope.session_id.as_str()),\\n            (\\\"profile_id\\\", key.scope.profile_id.as_str()),\\n            (\\\"task_id\\\", key.scope.task_id.as_str()),\\n            (\\\"turn_id\\\", key.scope.turn_id.as_str()),\\n            (\\\"turn_stream_id\\\", key.scope.turn_stream_id.as_str()),\\n            (\\\"call_id\\\", key.call_id.as_str()),\\n        ] {\\n            require_id(value, label, self.limits.max_id_bytes)?;\\n        }\\n        Ok(())\\n    }\\n\\n    fn validate_request(&self, request: &CallRequest) -> Result<()> {\\n        require_sha256(&request.request_sha256, \\\"request_sha256\\\")?;\\n        require_sha256(&request.binding_fingerprint, \\\"binding_fingerprint\\\")?;\\n        require_text(&request.tool, \\\"tool\\\", self.limits.max_tool_bytes, false)?;\\n        if let Some(target_id) = &request.target_id {\\n            require_text(target_id, \\\"target_id\\\", self.limits.max_target_bytes, true)?;\\n        }\\n        Ok(())\\n    }\\n\\n    fn validate_terminal(&self, terminal: &TerminalRecord) -> Result<()> {\\n        require_text(&terminal.terminal_kind, \\\"terminal_kind\\\", 128, false)?;\\n        require_sha256(&terminal.observation_sha256, \\\"observation_sha256\\\")?;\\n        if terminal\\n            .signal\\n            .is_some_and(|signal| !(1..=128).contains(&signal))\\n        {\\n            return Err(invalid(\\\"terminal signal is outside the supported range\\\"));\\n        }\\n        if terminal.exit_code.is_some() && terminal.signal.is_some() {\\n            return Err(invalid(\\\"terminal cannot contain both exit code and signal\\\"));\\n        }\\n        Ok(())\\n    }\\n}\\n\\nimpl Default for CallRegistry {\\n    fn default() -> Self {\\n        Self::new(RegistryLimits::default()).expect(\\\"default call registry limits are valid\\\")\\n    }\\n}\\n\\nfn require_id(value: &str, label: &str, maximum: usize) -> Result<()> {\\n    if value.is_empty()\\n        || value.len() > maximum\\n        || !value\\n            .bytes()\\n            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':'))\\n    {\\n        return Err(invalid(format!(\\\"{label} is empty, oversized or malformed\\\")));\\n    }\\n    Ok(())\\n}\\n\\nfn require_sha256(value: &str, label: &str) -> Result<()> {\\n    if value.len() != 64\\n        || !value\\n            .bytes()\\n            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))\\n    {\\n        return Err(invalid(format!(\\\"{label} must be a lowercase SHA-256\\\")));\\n    }\\n    Ok(())\\n}\\n\\nfn require_text(value: &str, label: &str, maximum: usize, allow_empty: bool) -> Result<()> {\\n    if (!allow_empty && value.is_empty())\\n        || value.len() > maximum\\n        || value.as_bytes().contains(&0)\\n        || value.chars().any(char::is_control)\\n    {\\n        return Err(invalid(format!(\\\"{label} is empty, oversized or malformed\\\")));\\n    }\\n    Ok(())\\n}\\n\\nfn invalid(message: impl Into<String>) -> RegistryError {\\n    RegistryError::InvalidRequest(message.into())\\n}\\n\\n/// Return a stable shard for a sequence of length-delimited fields.\\n///\\n/// This is intentionally a small non-cryptographic hash: shard selection is\\n/// an implementation detail, not an authorization decision.  The explicit\\n/// version and shard count are part of the preimage so a future layout change\\n/// cannot silently reinterpret persisted or in-flight state.\\nfn stable_shard_index(domain: &[u8], fields: &[&str]) -> usize {\\n    let mut hash = FNV_OFFSET_BASIS;\\n    fn feed(hash: &mut u64, bytes: &[u8]) {\\n        for byte in bytes {\\n            *hash ^= u64::from(*byte);\\n            *hash = hash.wrapping_mul(FNV_PRIME);\\n        }\\n    }\\n    fn feed_len(hash: &mut u64, length: usize) {\\n        feed(hash, &(length as u64).to_be_bytes());\\n    }\\n\\n    feed(&mut hash, &[REGISTRY_SHARD_HASH_VERSION]);\\n    feed_len(&mut hash, REGISTRY_SHARD_COUNT);\\n    feed_len(&mut hash, domain.len());\\n    feed(&mut hash, domain);\\n    for field in fields {\\n        feed_len(&mut hash, field.len());\\n        feed(&mut hash, field.as_bytes());\\n    }\\n    (hash % REGISTRY_SHARD_COUNT as u64) as usize\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    fn scope() -> TurnScope {\\n        TurnScope::new(\\\"session-1\\\", \\\"owner-open\\\", \\\"task-1\\\", \\\"turn-1\\\", \\\"stream-1\\\")\\n    }\\n\\n    fn key(call_id: &str) -> CallKey {\\n        CallKey::new(scope(), call_id)\\n    }\\n\\n    fn request(seed: char) -> CallRequest {\\n        CallRequest::new(\\n            seed.to_string().repeat(64),\\n            \\\"b\\\".repeat(64),\\n            \\\"shell.exec\\\",\\n            Some(\\\"rootlinux\\\".to_string()),\\n        )\\n    }\\n\\n    fn terminal(seed: char) -> TerminalRecord {\\n        TerminalRecord::new(\\\"exited\\\", Some(0), None, seed.to_string().repeat(64), 3, 4)\\n    }\\n\\n    #[test]\\n    fn begin_is_idempotent_for_exact_request_and_conflicts_on_drift() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-1\\\");\\n        let first = registry.begin(call.clone(), request('a')).unwrap();\\n        assert_eq!(first.disposition, BeginDisposition::New);\\n        assert_eq!(first.snapshot.state, EffectiveState::Accepted);\\n        let again = registry.begin(call.clone(), request('a')).unwrap();\\n        assert_eq!(again.disposition, BeginDisposition::Existing);\\n        assert_eq!(again.snapshot.next_event_seq, 1);\\n        assert_eq!(\\n            registry.begin(call, request('c')).unwrap_err(),\\n            RegistryError::CallIdConflict\\n        );\\n    }\\n\\n    #[test]\\n    fn configured_limits_cannot_escape_schema_hard_bounds() {\\n        let oversized = [\\n            RegistryLimits {\\n                max_entries: MAX_REGISTRY_ENTRIES + 1,\\n                ..RegistryLimits::default()\\n            },\\n            RegistryLimits {\\n                max_history_per_call: MAX_HISTORY_PER_CALL + 1,\\n                ..RegistryLimits::default()\\n            },\\n            RegistryLimits {\\n                max_id_bytes: MAX_ID_BYTES + 1,\\n                ..RegistryLimits::default()\\n            },\\n            RegistryLimits {\\n                max_tool_bytes: MAX_TOOL_BYTES + 1,\\n                ..RegistryLimits::default()\\n            },\\n            RegistryLimits {\\n                max_target_bytes: MAX_TARGET_BYTES + 1,\\n                ..RegistryLimits::default()\\n            },\\n        ];\\n        for limits in oversized {\\n            assert!(\\n                CallRegistry::new(limits).is_err(),\\n                \\\"configured call-registry limit exceeded its hard bound\\\"\\n            );\\n        }\\n        assert!(\\n            CallRegistry::new(RegistryLimits {\\n                max_entries: MAX_REGISTRY_ENTRIES,\\n                max_history_per_call: MAX_HISTORY_SLOTS / MAX_REGISTRY_ENTRIES + 1,\\n                ..RegistryLimits::default()\\n            })\\n            .is_err(),\\n            \\\"entry/history product must remain bounded\\\"\\n        );\\n        assert!(\\n            CallRegistry::new(RegistryLimits {\\n                max_entries: MAX_HISTORY_SLOTS / 64,\\n                max_history_per_call: 64,\\n                ..RegistryLimits::default()\\n            })\\n            .is_ok()\\n        );\\n    }\\n\\n    #[test]\\n    fn poisoned_shard_fails_closed_for_observation_and_admission() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-poisoned\\\");\\n        let shard_index = registry.shard_index(&call);\\n        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {\\n            let _guard = registry.shards[shard_index].lock().unwrap();\\n            panic!(\\\"intentional shard poison for regression test\\\");\\n        }));\\n\\n        assert_eq!(registry.len(), Err(RegistryError::StatePoisoned));\\n        assert_eq!(registry.is_empty(), Err(RegistryError::StatePoisoned));\\n        assert_eq!(\\n            registry.begin(call, request('p')).unwrap_err(),\\n            RegistryError::StatePoisoned\\n        );\\n    }\\n\\n    #[test]\\n    fn untouched_acceptance_can_be_rolled_back_and_failed_cleanup_is_fenced() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-rollback\\\");\\n        let request = request('a');\\n        registry.begin(call.clone(), request.clone()).unwrap();\\n        assert!(registry.rollback_accept(&call, &request).unwrap());\\n        assert_eq!(\\n            registry.snapshot(&call).unwrap_err(),\\n            RegistryError::NotFound\\n        );\\n        assert!(registry.is_empty().unwrap());\\n\\n        registry.begin(call.clone(), request.clone()).unwrap();\\n        let inhibited = registry.inhibit_spawn(&call).unwrap();\\n        assert_eq!(\\n            inhibited.state,\\n            EffectiveState::ProvenNotStartedAfterDisconnect\\n        );\\n        assert_eq!(\\n            registry.rollback_accept(&call, &request).unwrap_err(),\\n            RegistryError::InvalidTransition(\\\"only an untouched accepted call can be rolled back\\\")\\n        );\\n        assert!(matches!(\\n            registry\\n                .claim_spawn(&call, &request.request_sha256)\\n                .unwrap(),\\n            SpawnClaim::Inhibited(_)\\n        ));\\n        assert!(matches!(\\n            registry.history_from(&call, 0).unwrap().as_slice(),\\n            [\\n                CallEvent {\\n                    kind: CallEventKind::Accepted,\\n                    ..\\n                },\\n                CallEvent {\\n                    kind: CallEventKind::SpawnInhibited,\\n                    ..\\n                }\\n            ]\\n        ));\\n    }\\n\\n    #[test]\\n    fn generation_failure_leaves_an_entry_rollbackable_before_spawn() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-generation-exhausted\\\");\\n        let request = request('b');\\n        registry.begin(call.clone(), request.clone()).unwrap();\\n        registry\\n            .next_spawn_generation\\n            .store(u64::MAX, Ordering::Release);\\n        assert_eq!(\\n            registry\\n                .claim_spawn(&call, &request.request_sha256)\\n                .unwrap_err(),\\n            RegistryError::GenerationExhausted\\n        );\\n        assert!(registry.rollback_accept(&call, &request).unwrap());\\n        assert!(registry.is_empty().unwrap());\\n    }\\n\\n    #[test]\\n    fn disconnect_before_spawn_permanently_inhibits_the_call() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-not-started\\\");\\n        registry.begin(call.clone(), request('a')).unwrap();\\n        let lost = registry.mark_connection_lost(&call).unwrap();\\n        assert_eq!(lost.state, EffectiveState::ProvenNotStartedAfterDisconnect);\\n        let attached = registry.mark_connection_attached(&call).unwrap();\\n        assert_eq!(\\n            attached.state,\\n            EffectiveState::ProvenNotStartedAfterDisconnect\\n        );\\n        match registry.claim_spawn(&call, &\\\"a\\\".repeat(64)).unwrap() {\\n            SpawnClaim::Inhibited(snapshot) => assert_eq!(\\n                snapshot.state,\\n                EffectiveState::ProvenNotStartedAfterDisconnect\\n            ),\\n            other => panic!(\\\"unexpected spawn claim: {other:?}\\\"),\\n        }\\n    }\\n\\n    #[test]\\n    fn disconnect_after_spawn_is_unknown_until_late_terminal_arrives() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-unknown\\\");\\n        registry.begin(call.clone(), request('a')).unwrap();\\n        let generation = match registry.claim_spawn(&call, &\\\"a\\\".repeat(64)).unwrap() {\\n            SpawnClaim::Granted { generation, .. } => generation,\\n            other => panic!(\\\"unexpected spawn claim: {other:?}\\\"),\\n        };\\n        registry.record_pid(&call, generation, 42).unwrap();\\n        let lost = registry.mark_connection_lost(&call).unwrap();\\n        assert_eq!(\\n            lost.state,\\n            EffectiveState::UnknownAfterDisconnect {\\n                generation,\\n                pid: Some(42)\\n            }\\n        );\\n        registry.complete(&call, generation, terminal('d')).unwrap();\\n        assert_eq!(\\n            registry.snapshot(&call).unwrap().state,\\n            EffectiveState::Terminal {\\n                generation,\\n                terminal: terminal('d')\\n            }\\n        );\\n    }\\n\\n    #[test]\\n    fn cancellation_signal_is_shared_and_event_is_idempotent() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-cancel\\\");\\n        let begin = registry.begin(call.clone(), request('a')).unwrap();\\n        assert!(!begin.cancellation.is_cancelled());\\n        let first = registry.request_cancel(&call).unwrap();\\n        assert!(first.cancellation_requested);\\n        assert!(begin.cancellation.is_cancelled());\\n        let second = registry.request_cancel(&call).unwrap();\\n        assert_eq!(first.next_event_seq, second.next_event_seq);\\n        assert_eq!(\\n            registry\\n                .history_from(&call, 0)\\n                .unwrap()\\n                .iter()\\n                .filter(|event| matches!(event.kind, CallEventKind::CancelRequested))\\n                .count(),\\n            1\\n        );\\n    }\\n\\n    #[test]\\n    fn terminal_is_exactly_once_and_exact_duplicate_is_idempotent() {\\n        let registry = CallRegistry::default();\\n        let call = key(\\\"call-terminal\\\");\\n        registry.begin(call.clone(), request('a')).unwrap();\\n        let generation = match registry.claim_spawn(&call, &\\\"a\\\".repeat(64)).unwrap() {\\n            SpawnClaim::Granted { generation, .. } => generation,\\n            other => panic!(\\\"unexpected spawn claim: {other:?}\\\"),\\n        };\\n        assert_eq!(\\n            registry.complete(&call, generation, terminal('d')).unwrap(),\\n            MutationOutcome::Applied\\n        );\\n        assert_eq!(\\n            registry.complete(&call, generation, terminal('d')).unwrap(),\\n            MutationOutcome::Idempotent\\n        );\\n        assert_eq!(\\n            registry\\n                .complete(&call, generation, terminal('e'))\\n                .unwrap_err(),\\n            RegistryError::TerminalConflict\\n        );\\n    }\\n\\n    #[test]\\n    fn history_is_bounded_with_an_explicit_earliest_cursor() {\\n        let registry = CallRegistry::new(RegistryLimits {\\n            max_history_per_call: 3,\\n            ..RegistryLimits::default()\\n        })\\n        .unwrap();\\n        let call = key(\\\"call-history\\\");\\n        registry.begin(call.clone(), request('a')).unwrap();\\n        registry.request_cancel(&call).unwrap();\\n        registry.mark_connection_lost(&call).unwrap();\\n        registry.mark_connection_attached(&call).unwrap();\\n        let snapshot = registry.snapshot(&call).unwrap();\\n        assert_eq!(snapshot.earliest_history_seq, 1);\\n        assert_eq!(snapshot.next_event_seq, 4);\\n        assert_eq!(\\n            registry\\n                .history_from(&call, 0)\\n                .unwrap()\\n                .iter()\\n                .map(|event| event.seq)\\n                .collect::<Vec<_>>(),\\n            vec![1, 2, 3]\\n        );\\n    }\\n\\n    #[test]\\n    fn terminal_cleanup_is_explicit_and_only_removes_terminal_calls() {\\n        let registry = CallRegistry::default();\\n        let active = key(\\\"call-active\\\");\\n        registry.begin(active.clone(), request('a')).unwrap();\\n        assert!(!registry.remove_terminal(&active).unwrap());\\n        let finished = key(\\\"call-finished\\\");\\n        registry.begin(finished.clone(), request('c')).unwrap();\\n        let generation = match registry.claim_spawn(&finished, &\\\"c\\\".repeat(64)).unwrap() {\\n            SpawnClaim::Granted { generation, .. } => generation,\\n            other => panic!(\\\"unexpected spawn claim: {other:?}\\\"),\\n        };\\n        registry\\n            .complete(&finished, generation, terminal('d'))\\n            .unwrap();\\n        assert!(registry.remove_terminal(&finished).unwrap());\\n        assert_eq!(registry.len().unwrap(), 1);\\n    }\\n\\n    #[test]\\n    fn shard_mapping_is_versioned_and_stable() {\\n        let registry = CallRegistry::default();\\n        // Keep one golden vector so a future hash/count change cannot silently\\n        // move live keys without an explicit schema migration.\\n        assert_eq!(\\n            registry.shard_index(&key(\\\"call-1\\\")),\\n            42,\\n            \\\"registry shard hash vector changed\\\"\\n        );\\n        let another_instance = CallRegistry::default();\\n        assert_eq!(\\n            registry.shard_index(&key(\\\"call-1\\\")),\\n            another_instance.shard_index(&key(\\\"call-1\\\"))\\n        );\\n    }\\n\\n    #[test]\\n    fn shard_mapping_has_bounded_collision_pressure_for_typical_keys() {\\n        let registry = CallRegistry::default();\\n        let mut occupied = std::collections::HashSet::new();\\n        for index in 0..4_096 {\\n            occupied.insert(registry.shard_index(&key(&format!(\\\"call-distribution-{index}\\\"))));\\n        }\\n        assert!(\\n            occupied.len() >= REGISTRY_SHARD_COUNT / 2,\\n            \\\"deterministic shard hash is unexpectedly concentrated: {occupied:?}\\\"\\n        );\\n    }\\n\\n    #[test]\\n    fn an_independent_shard_progresses_while_one_shard_is_held() {\\n        use std::sync::mpsc::sync_channel;\\n        use std::time::Duration;\\n\\n        let registry = Arc::new(CallRegistry::default());\\n        let blocked = key(\\\"call-blocked-shard\\\");\\n        let blocked_index = registry.shard_index(&blocked);\\n        let independent = (0..10_000)\\n            .map(|index| key(&format!(\\\"call-independent-{index}\\\")))\\n            .find(|candidate| registry.shard_index(candidate) != blocked_index)\\n            .expect(\\\"fixed shard count must provide an independent key\\\");\\n\\n        let guard = registry.shards[blocked_index]\\n            .lock()\\n            .expect(\\\"blocked shard lock\\\");\\n        let worker_registry = Arc::clone(&registry);\\n        let (sender, receiver) = sync_channel(1);\\n        let worker = std::thread::spawn(move || {\\n            let result = worker_registry.begin(independent, request('c'));\\n            sender.send(result).expect(\\\"send independent result\\\");\\n        });\\n        let result = receiver.recv_timeout(Duration::from_secs(1));\\n        drop(guard);\\n        let result = result\\n            .expect(\\\"an unrelated key must not wait on another shard\\\")\\n            .expect(\\\"independent begin must succeed\\\");\\n        worker.join().expect(\\\"independent shard worker\\\");\\n        assert_eq!(result.disposition, BeginDisposition::New);\\n    }\\n\\n    #[test]\\n    fn concurrent_admission_never_exceeds_global_capacity() {\\n        use std::sync::{Arc, Barrier};\\n\\n        const LIMIT: usize = 8;\\n        const THREADS: usize = 64;\\n        let registry = Arc::new(\\n            CallRegistry::new(RegistryLimits {\\n                max_entries: LIMIT,\\n                ..RegistryLimits::default()\\n            })\\n            .expect(\\\"valid limits\\\"),\\n        );\\n        let barrier = Arc::new(Barrier::new(THREADS));\\n        let workers = (0..THREADS)\\n            .map(|index| {\\n                let registry = Arc::clone(&registry);\\n                let barrier = Arc::clone(&barrier);\\n                std::thread::spawn(move || {\\n                    barrier.wait();\\n                    registry.begin(key(&format!(\\\"call-capacity-{index}\\\")), request('d'))\\n                })\\n            })\\n            .collect::<Vec<_>>();\\n        let results = workers\\n            .into_iter()\\n            .map(|worker| worker.join().expect(\\\"capacity worker\\\"))\\n            .collect::<Vec<_>>();\\n        assert_eq!(\\n            results.iter().filter(|result| result.is_ok()).count(),\\n            LIMIT\\n        );\\n        assert_eq!(registry.len().unwrap(), LIMIT);\\n    }\\n}\\n\"},{\"path\":\"crates/trillionnium-owner-open-provider-jsonl/src/lib.rs\",\"sha\":\"7739fd8cbc673c5f27da1967788c2c45faa2b9b9\",\"text\":\"//! Bounded duplex JSONL adapter for an external owner-open provider process.\\n//!\\n//! The provider owns semantic reasoning. This adapter owns only process\\n//! lifecycle, strict JSONL framing, correlation, tool callback transport and\\n//! truthful terminal reporting. It never adds plan, risk, approval, target\\n//! substitution, command rewriting or a typed ADB subcommand table.\\n\\nmod process;\\nmod protocol;\\nmod strict_json;\\n\\nuse std::collections::BTreeMap;\\nuse std::env;\\nuse std::io::Write;\\nuse std::os::fd::AsRawFd;\\nuse std::os::unix::ffi::OsStrExt;\\nuse std::os::unix::process::CommandExt;\\nuse std::path::{Path, PathBuf};\\nuse std::process::{Command, Stdio};\\nuse std::sync::atomic::{AtomicBool, Ordering};\\nuse std::sync::mpsc::sync_channel;\\nuse std::sync::{Arc, Mutex};\\nuse std::time::{Duration, Instant};\\n\\nuse serde::Serialize;\\nuse serde_json::{Value, json};\\nuse thiserror::Error;\\nuse trillionnium_owner_open_runtime::EnvironmentDelta;\\nuse trillionnium_owner_open_turn_loop::{\\n    ProviderEvent, ProviderHost, ProviderTerminal, ProviderTerminalStatus, SameTurnProvider,\\n    TurnRequest,\\n};\\n\\nuse process::{\\n    ProviderChildGuard, ProviderOutput, allow_natural_exit_grace, capture_process_identity,\\n    join_provider_workers_bounded, spawn_stderr_reader, spawn_stdout_reader,\\n};\\nuse protocol::{\\n    decode_bound_tool_call, encode_tool_error, encode_tool_outcome, handle_provider_event,\\n    optional_string, required_string, validate_envelope,\\n};\\n\\npub const PROVIDER_PROTOCOL: &str = \\\"trillionnium.owner-open.provider-jsonl.v1\\\";\\n/// Schema ceilings for provider process liveness and resident buffering.\\n/// Deployments may lower these values, but a malformed provider profile cannot\\n/// request an unbounded line, queue, output retention or wait interval.\\npub const MAX_JSONL_PROVIDER_TIMEOUT: Duration = Duration::from_secs(24 * 60 * 60);\\npub const MAX_JSONL_PROVIDER_POLL_INTERVAL: Duration = Duration::from_secs(1);\\npub const MAX_JSONL_PROVIDER_TERMINATE_GRACE: Duration = Duration::from_secs(60);\\npub const MAX_JSONL_PROVIDER_LINE_BYTES: usize = 64 * 1024 * 1024;\\npub const MAX_JSONL_PROVIDER_STDOUT_BYTES: usize = 256 * 1024 * 1024;\\npub const MAX_JSONL_PROVIDER_EVENT_COUNT: usize = 1_048_576;\\npub const MAX_JSONL_PROVIDER_STDERR_BYTES: usize = 16 * 1024 * 1024;\\npub const MAX_JSONL_PROVIDER_OUTPUT_QUEUE_DEPTH: usize = 4_096;\\n/// Worst-case bytes queued as complete stdout lines before the provider loop\\n/// drains them. Two reader-side allocations remain finite under this ceiling.\\npub const MAX_JSONL_PROVIDER_QUEUE_BYTES: usize = 2 * 1024 * 1024 * 1024;\\nconst PROVIDER_OUTPUT_DRAIN_GRACE_MINIMUM: Duration = Duration::from_secs(2);\\n// Provider callbacks are mechanism-only, but a child that stops reading its\\n// stdin must not be able to wedge the Host loop in `Write::write_all`.  Keep\\n// each outbound JSONL frame on one finite deadline; the surrounding turn\\n// timeout remains the higher-level semantic bound.\\nconst PROVIDER_WRITE_TIMEOUT: Duration = Duration::from_secs(2);\\n// Provider credentials and host-local state are not implicit request input.\\n// Preserve only the mechanical runtime settings needed to resolve the\\n// configured executable and ordinary shell/ADB tools; all other values must\\n// be supplied through the validated provider environment delta.\\nconst PROVIDER_INHERITED_ENV_ALLOWLIST: &[&str] = &[\\n    \\\"PATH\\\",\\n    \\\"HOME\\\",\\n    \\\"CODEX_HOME\\\",\\n    \\\"LANG\\\",\\n    \\\"LC_ALL\\\",\\n    \\\"TERM\\\",\\n    \\\"NO_COLOR\\\",\\n    \\\"ADB_SERVER_SOCKET\\\",\\n    \\\"SSL_CERT_FILE\\\",\\n    \\\"SSL_CERT_DIR\\\",\\n    \\\"HTTP_PROXY\\\",\\n    \\\"HTTPS_PROXY\\\",\\n    \\\"ALL_PROXY\\\",\\n    \\\"NO_PROXY\\\",\\n    \\\"http_proxy\\\",\\n    \\\"https_proxy\\\",\\n    \\\"all_proxy\\\",\\n    \\\"no_proxy\\\",\\n];\\n#[derive(Debug, Error)]\\npub enum JsonlProviderError {\\n    #[error(\\\"invalid owner-open provider configuration: {0}\\\")]\\n    InvalidConfiguration(String),\\n    #[error(\\\"cannot spawn owner-open provider: {0}\\\")]\\n    Spawn(String),\\n    #[error(\\\"owner-open provider I/O failed: {0}\\\")]\\n    Io(String),\\n    #[error(\\\"owner-open provider protocol failed: {0}\\\")]\\n    Protocol(String),\\n    #[error(\\\"owner-open provider exceeded its turn deadline\\\")]\\n    TimedOut,\\n    #[error(\\\"owner-open provider exited before a terminal frame: {0}\\\")]\\n    Interrupted(String),\\n    #[error(\\\"owner-open provider cleanup failed: {0}\\\")]\\n    Cleanup(String),\\n}\\n\\npub type Result<T> = std::result::Result<T, JsonlProviderError>;\\n\\n#[derive(Debug, Clone)]\\npub struct JsonlProviderConfig {\\n    pub executable: PathBuf,\\n    pub args: Vec<String>,\\n    pub shell_executable: PathBuf,\\n    pub adb_executable: PathBuf,\\n    /// Owner-store generation captured for the provider turn.  `None` means\\n    /// that this source adapter has no durable generation source; the\\n    /// canonical request still records JSON `null` rather than silently\\n    /// inventing a generation value.\\n    pub config_generation: Option<Value>,\\n    pub cwd: Option<PathBuf>,\\n    pub env: EnvironmentDelta,\\n    pub timeout: Duration,\\n    pub poll_interval: Duration,\\n    pub terminate_grace: Duration,\\n    pub max_line_bytes: usize,\\n    pub max_stdout_bytes: usize,\\n    pub max_event_count: usize,\\n    pub max_stderr_bytes: usize,\\n    pub output_queue_depth: usize,\\n}\\n\\nimpl JsonlProviderConfig {\\n    pub fn validate(&self) -> Result<()> {\\n        validate_os_value(&self.executable, \\\"provider executable\\\", 16 * 1024)?;\\n        validate_os_value(&self.shell_executable, \\\"shell executable\\\", 16 * 1024)?;\\n        validate_os_value(&self.adb_executable, \\\"adb executable\\\", 16 * 1024)?;\\n        if let Some(cwd) = &self.cwd {\\n            validate_os_value(cwd, \\\"provider cwd\\\", 16 * 1024)?;\\n        }\\n        if self.args.len() > 4096 {\\n            return Err(invalid_config(\\\"provider argv has too many elements\\\"));\\n        }\\n        let mut total = 0usize;\\n        for argument in &self.args {\\n            if argument.len() > 64 * 1024 || argument.as_bytes().contains(&0) {\\n                return Err(invalid_config(\\n                    \\\"provider argument exceeds its bound or contains NUL\\\",\\n                ));\\n            }\\n            total = total\\n                .checked_add(argument.len())\\n                .ok_or_else(|| invalid_config(\\\"provider argv byte count overflow\\\"))?;\\n        }\\n        if total > 1024 * 1024 {\\n            return Err(invalid_config(\\\"provider argv exceeds one MiB\\\"));\\n        }\\n        if self.timeout.is_zero()\\n            || self.poll_interval.is_zero()\\n            || self.terminate_grace.is_zero()\\n            || self.max_line_bytes == 0\\n            || self.max_event_count == 0\\n            || self.max_stderr_bytes == 0\\n            || self.output_queue_depth == 0\\n        {\\n            return Err(invalid_config(\\n                \\\"provider duration/count/byte limits are invalid\\\",\\n            ));\\n        }\\n        for (name, value, maximum) in [\\n            (\\\"timeout\\\", self.timeout, MAX_JSONL_PROVIDER_TIMEOUT),\\n            (\\n                \\\"poll_interval\\\",\\n                self.poll_interval,\\n                MAX_JSONL_PROVIDER_POLL_INTERVAL,\\n            ),\\n            (\\n                \\\"terminate_grace\\\",\\n                self.terminate_grace,\\n                MAX_JSONL_PROVIDER_TERMINATE_GRACE,\\n            ),\\n        ] {\\n            if value > maximum {\\n                return Err(invalid_config(format!(\\n                    \\\"provider {name} exceeds hard bound {maximum:?}\\\"\\n                )));\\n            }\\n        }\\n        for (name, value, maximum) in [\\n            (\\n                \\\"max_line_bytes\\\",\\n                self.max_line_bytes,\\n                MAX_JSONL_PROVIDER_LINE_BYTES,\\n            ),\\n            (\\n                \\\"max_stdout_bytes\\\",\\n                self.max_stdout_bytes,\\n                MAX_JSONL_PROVIDER_STDOUT_BYTES,\\n            ),\\n            (\\n                \\\"max_event_count\\\",\\n                self.max_event_count,\\n                MAX_JSONL_PROVIDER_EVENT_COUNT,\\n            ),\\n            (\\n                \\\"max_stderr_bytes\\\",\\n                self.max_stderr_bytes,\\n                MAX_JSONL_PROVIDER_STDERR_BYTES,\\n            ),\\n            (\\n                \\\"output_queue_depth\\\",\\n                self.output_queue_depth,\\n                MAX_JSONL_PROVIDER_OUTPUT_QUEUE_DEPTH,\\n            ),\\n        ] {\\n            if value > maximum {\\n                return Err(invalid_config(format!(\\n                    \\\"provider {name} exceeds hard bound {maximum}\\\"\\n                )));\\n            }\\n        }\\n        if self.max_stdout_bytes < self.max_line_bytes {\\n            return Err(invalid_config(\\n                \\\"provider duration/count/byte limits are invalid\\\",\\n            ));\\n        }\\n        let queued_bytes = self\\n            .max_line_bytes\\n            .checked_mul(self.output_queue_depth)\\n            .ok_or_else(|| invalid_config(\\\"provider output queue byte bound overflow\\\"))?;\\n        if queued_bytes > MAX_JSONL_PROVIDER_QUEUE_BYTES {\\n            return Err(invalid_config(format!(\\n                \\\"provider max_line_bytes * output_queue_depth exceeds hard bound {MAX_JSONL_PROVIDER_QUEUE_BYTES}\\\"\\n            )));\\n        }\\n        validate_environment(&self.env)?;\\n        if let Some(generation) = &self.config_generation {\\n            validate_config_generation(generation)?;\\n        }\\n        Ok(())\\n    }\\n}\\n\\nimpl Default for JsonlProviderConfig {\\n    fn default() -> Self {\\n        Self {\\n            executable: PathBuf::from(\\\"codex\\\"),\\n            args: Vec::new(),\\n            shell_executable: PathBuf::from(\\\"/bin/sh\\\"),\\n            adb_executable: PathBuf::from(\\\"adb\\\"),\\n            config_generation: None,\\n            cwd: None,\\n            env: BTreeMap::new(),\\n            timeout: Duration::from_secs(300),\\n            poll_interval: Duration::from_millis(20),\\n            terminate_grace: Duration::from_millis(250),\\n            // A bounded tool.result may contain 16 MiB of runtime output in\\n            // base64 plus lifecycle metadata. Incremental result frames remain\\n            // a later optimization; this first protocol keeps one finite line.\\n            max_line_bytes: 32 * 1024 * 1024,\\n            max_stdout_bytes: 64 * 1024 * 1024,\\n            max_event_count: 4096,\\n            max_stderr_bytes: 1024 * 1024,\\n            output_queue_depth: 64,\\n        }\\n    }\\n}\\n\\n#[derive(Debug, Clone)]\\npub struct JsonlProvider {\\n    config: JsonlProviderConfig,\\n}\\n\\nimpl JsonlProvider {\\n    pub fn new(config: JsonlProviderConfig) -> Result<Self> {\\n        config.validate()?;\\n        Ok(Self { config })\\n    }\\n\\n    #[must_use]\\n    pub fn config(&self) -> &JsonlProviderConfig {\\n        &self.config\\n    }\\n\\n    fn run_session(\\n        &self,\\n        request: &TurnRequest,\\n        host: &mut ProviderHost<'_>,\\n    ) -> Result<ProviderTerminal> {\\n        self.config.validate()?;\\n        let started = Instant::now();\\n        let deadline = started\\n            .checked_add(self.config.timeout)\\n            .ok_or_else(|| invalid_config(\\\"provider deadline cannot be represented\\\"))?;\\n        let mut command = Command::new(&self.config.executable);\\n        command.env_clear();\\n        for &key in PROVIDER_INHERITED_ENV_ALLOWLIST {\\n            if let Some(value) = env::var_os(key) {\\n                command.env(key, value);\\n            }\\n        }\\n        command\\n            .args(&self.config.args)\\n            .stdin(Stdio::piped())\\n            .stdout(Stdio::piped())\\n            .stderr(Stdio::piped());\\n        if let Some(cwd) = &self.config.cwd {\\n            command.current_dir(cwd);\\n        }\\n        for (key, value) in &self.config.env {\\n            match value {\\n                Some(value) => {\\n                    command.env(key, value);\\n                }\\n                None => {\\n                    command.env_remove(key);\\n                }\\n            }\\n        }\\n        let parent_pid = unsafe { libc::getpid() };\\n        let spawn_cancellation = host.cancellation();\\n        unsafe {\\n            command.pre_exec(move || {\\n                if spawn_cancellation.is_cancelled() {\\n                    return Err(std::io::Error::from_raw_os_error(libc::ECANCELED));\\n                }\\n                if Instant::now() >= deadline {\\n                    return Err(std::io::Error::from_raw_os_error(libc::ETIMEDOUT));\\n                }\\n                if libc::setpgid(0, 0) != 0 {\\n                    return Err(std::io::Error::last_os_error());\\n                }\\n                #[cfg(any(target_os = \\\"linux\\\", target_os = \\\"android\\\"))]\\n                {\\n                    if libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGKILL) != 0 {\\n                        return Err(std::io::Error::last_os_error());\\n                    }\\n                    if libc::getppid() != parent_pid {\\n                        return Err(std::io::Error::from_raw_os_error(libc::ECHILD));\\n                    }\\n                }\\n                Ok(())\\n            });\\n        }\\n\\n        if host.is_cancelled() {\\n            return Ok(ProviderTerminal::cancelled(\\n                \\\"turn cancelled before provider spawn\\\",\\n            ));\\n        }\\n        if Instant::now() >= deadline {\\n            return Err(JsonlProviderError::TimedOut);\\n        }\\n        let child = match command.spawn() {\\n            Ok(child) => child,\\n            Err(error) if error.raw_os_error() == Some(libc::ETIMEDOUT) => {\\n                return Err(JsonlProviderError::TimedOut);\\n            }\\n            Err(error) if error.raw_os_error() == Some(libc::ECANCELED) => {\\n                return Ok(ProviderTerminal::cancelled(\\n                    \\\"turn cancelled before provider exec\\\",\\n                ));\\n            }\\n            Err(error) => return Err(JsonlProviderError::Spawn(error.to_string())),\\n        };\\n        // Install the guard before touching any child-owned pipe.  Every\\n        // operation below can fail (including OS thread creation), and a bare\\n        // `Child` would otherwise leave the provider process/group alive on\\n        // those early-return paths.\\n        let mut child = ProviderChildGuard::new(child, self.config.terminate_grace);\\n        // Bind the kernel-observed process generation before touching any\\n        // child-owned descriptor.  If the leader exits during this tiny\\n        // window, the guard's exact Child handle performs bounded cleanup and\\n        // no raw PID/PGID signal is attempted.\\n        let identity = capture_process_identity(child.id()).map_err(|error| {\\n            JsonlProviderError::Io(format!(\\n                \\\"failed to capture provider process identity: {error}\\\"\\n            ))\\n        })?;\\n        child.bind_identity(identity);\\n        let mut provider_stdin = child\\n            .stdin\\n            .take()\\n            .ok_or_else(|| JsonlProviderError::Io(\\\"provider stdin was not piped\\\".to_string()))?;\\n        let provider_stdout = child\\n            .stdout\\n            .take()\\n            .ok_or_else(|| JsonlProviderError::Io(\\\"provider stdout was not piped\\\".to_string()))?;\\n        let provider_stderr = child\\n            .stderr\\n            .take()\\n            .ok_or_else(|| JsonlProviderError::Io(\\\"provider stderr was not piped\\\".to_string()))?;\\n\\n        let (sender, receiver) = sync_channel(self.config.output_queue_depth);\\n        let stdout_thread = spawn_stdout_reader(\\n            provider_stdout,\\n            self.config.max_line_bytes,\\n            self.config.max_stdout_bytes,\\n            sender,\\n        )\\n        .map_err(|error| JsonlProviderError::Io(error.to_string()))?;\\n        let stderr_capture = Arc::new(Mutex::new(Vec::new()));\\n        let stderr_overflow = Arc::new(AtomicBool::new(false));\\n        let stderr_thread = spawn_stderr_reader(\\n            provider_stderr,\\n            self.config.max_stderr_bytes,\\n            Arc::clone(&stderr_capture),\\n            Arc::clone(&stderr_overflow),\\n        )\\n        .map_err(|error| JsonlProviderError::Io(error.to_string()))?;\\n\\n        let result = (|| {\\n            let mut outbound_seq = 0_u64;\\n            let mut inbound_seq = 0_u64;\\n            write_json_line(\\n                &mut provider_stdin,\\n                &json!({\\n                    \\\"protocol\\\": PROVIDER_PROTOCOL,\\n                    \\\"kind\\\": \\\"turn.start\\\",\\n                    \\\"seq\\\": outbound_seq,\\n                    \\\"turn\\\": {\\n                        \\\"session_id\\\": &request.session_id,\\n                        \\\"profile_id\\\": &request.profile_id,\\n                        \\\"task_id\\\": &request.task_id,\\n                        \\\"turn_id\\\": &request.turn_id,\\n                        \\\"turn_stream_id\\\": &request.turn_stream_id,\\n                        \\\"user_input\\\": &request.user_input\\n                    }\\n                }),\\n                self.config.max_line_bytes,\\n                Some(deadline),\\n            )?;\\n            outbound_seq = outbound_seq.saturating_add(1);\\n\\n            let mut terminal = None;\\n            let mut event_count = 0usize;\\n            let mut cancellation_sent = false;\\n            let mut cancellation_deadline = None::<Instant>;\\n            let mut observed_exit = None::<(String, Instant)>;\\n            while terminal.is_none() {\\n                if Instant::now() >= deadline {\\n                    return Err(JsonlProviderError::TimedOut);\\n                }\\n                if host.is_cancelled() && !cancellation_sent {\\n                    write_json_line(\\n                        &mut provider_stdin,\\n                        &json!({\\n                            \\\"protocol\\\": PROVIDER_PROTOCOL,\\n                            \\\"kind\\\": \\\"turn.cancel\\\",\\n                            \\\"seq\\\": outbound_seq,\\n                            \\\"turn\\\": {\\n                                \\\"session_id\\\": &request.session_id,\\n                                \\\"profile_id\\\": &request.profile_id,\\n                                \\\"task_id\\\": &request.task_id,\\n                                \\\"turn_id\\\": &request.turn_id,\\n                                \\\"turn_stream_id\\\": &request.turn_stream_id\\n                            }\\n                        }),\\n                        self.config.max_line_bytes,\\n                        Some(deadline),\\n                    )?;\\n                    outbound_seq = outbound_seq.saturating_add(1);\\n                    cancellation_sent = true;\\n                    cancellation_deadline = Instant::now().checked_add(self.config.terminate_grace);\\n                }\\n                if cancellation_deadline.is_some_and(|deadline| Instant::now() >= deadline) {\\n                    terminal = Some(ProviderTerminal::cancelled(\\n                        \\\"provider cancellation grace expired; its process group was terminated\\\",\\n                    ));\\n                    continue;\\n                }\\n\\n                match receiver.recv_timeout(\\n                    self.config\\n                        .poll_interval\\n                        .min(deadline.saturating_duration_since(Instant::now())),\\n                ) {\\n                    Ok(ProviderOutput::Line(raw)) => {\\n                        if Instant::now() >= deadline {\\n                            return Err(JsonlProviderError::TimedOut);\\n                        }\\n                        event_count = event_count.saturating_add(1);\\n                        if event_count > self.config.max_event_count {\\n                            return Err(JsonlProviderError::Protocol(\\n                                \\\"provider event count exceeds its bound\\\".to_string(),\\n                            ));\\n                        }\\n                        let value = strict_json::decode_object(&raw)\\n                            .map_err(JsonlProviderError::Protocol)?;\\n                        validate_envelope(&value, inbound_seq)?;\\n                        inbound_seq = inbound_seq.saturating_add(1);\\n                        match required_string(&value, \\\"kind\\\")? {\\n                            \\\"provider.event\\\" => handle_provider_event(&value, host)?,\\n                            \\\"tool.call\\\" => {\\n                                let call_id = value\\n                                    .get(\\\"call\\\")\\n                                    .and_then(Value::as_object)\\n                                    .and_then(|call| call.get(\\\"call_id\\\"))\\n                                    .and_then(Value::as_str)\\n                                    .unwrap_or(\\\"unknown-call\\\")\\n                                    .to_string();\\n                                let response =\\n                                    match decode_bound_tool_call(&value, request, &self.config) {\\n                                        Ok(call) => match host\\n                                            .invoke_tool_with_deadline(call, Some(deadline))\\n                                        {\\n                                            Ok(outcome) => {\\n                                                encode_tool_outcome(outbound_seq, &call_id, outcome)\\n                                            }\\n                                            Err(error) => encode_tool_error(\\n                                                outbound_seq,\\n                                                &call_id,\\n                                                \\\"host_error\\\",\\n                                                &error.to_string(),\\n                                            ),\\n                                        },\\n                                        Err(error) => encode_tool_error(\\n                                            outbound_seq,\\n                                            &call_id,\\n                                            \\\"invalid_request\\\",\\n                                            &error.to_string(),\\n                                        ),\\n                                    };\\n                                if Instant::now() >= deadline {\\n                                    return Err(JsonlProviderError::TimedOut);\\n                                }\\n                                write_json_line(\\n                                    &mut provider_stdin,\\n                                    &response,\\n                                    self.config.max_line_bytes,\\n                                    Some(deadline),\\n                                )?;\\n                                outbound_seq = outbound_seq.saturating_add(1);\\n                            }\\n                            \\\"turn.complete\\\" => {\\n                                terminal = Some(ProviderTerminal {\\n                                    status: ProviderTerminalStatus::Completed,\\n                                    summary: optional_string(&value, \\\"summary\\\")?\\n                                        .map(str::to_string),\\n                                    error: None,\\n                                });\\n                            }\\n                            \\\"turn.cancelled\\\" => {\\n                                terminal = Some(ProviderTerminal {\\n                                    status: ProviderTerminalStatus::Cancelled,\\n                                    summary: optional_string(&value, \\\"summary\\\")?\\n                                        .map(str::to_string),\\n                                    error: None,\\n                                });\\n                            }\\n                            \\\"turn.fail\\\" => {\\n                                return Err(JsonlProviderError::Interrupted(\\n                                    required_string(&value, \\\"error\\\")?.to_string(),\\n                                ));\\n                            }\\n                            other => {\\n                                host.emit(ProviderEvent::Opaque {\\n                                    kind: other.to_string(),\\n                                    payload: String::from_utf8(raw).map_err(|error| {\\n                                        JsonlProviderError::Protocol(error.to_string())\\n                                    })?,\\n                                })\\n                                .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?;\\n                            }\\n                        }\\n                    }\\n                    Ok(ProviderOutput::Eof) => {\\n                        if cancellation_sent {\\n                            terminal = Some(ProviderTerminal::cancelled(\\n                                \\\"provider exited after turn cancellation\\\",\\n                            ));\\n                            continue;\\n                        }\\n                        let status = match observed_exit.as_ref() {\\n                            Some((status, _)) => status.clone(),\\n                            None => format!(\\n                                \\\"{:?}\\\",\\n                                child\\n                                    .try_wait()\\n                                    .map_err(|error| JsonlProviderError::Io(error.to_string()))?\\n                            ),\\n                        };\\n                        return Err(JsonlProviderError::Interrupted(format!(\\n                            \\\"EOF before turn terminal; status={status}\\\"\\n                        )));\\n                    }\\n                    Ok(ProviderOutput::Error(error)) => {\\n                        return Err(JsonlProviderError::Protocol(error));\\n                    }\\n                    Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {\\n                        if observed_exit.is_none()\\n                            && let Some(status) = child\\n                                .try_wait()\\n                                .map_err(|error| JsonlProviderError::Io(error.to_string()))?\\n                        {\\n                            // Child exit and stdout delivery are observed by different\\n                            // threads. Exit must never overtake an already-read terminal\\n                            // line; wait for the ordered reader outcome (Line then Eof).\\n                            observed_exit = Some((status.to_string(), Instant::now()));\\n                        }\\n                        if let Some((status, observed_at)) = observed_exit.as_ref()\\n                            && observed_at.elapsed()\\n                                >= self\\n                                    .config\\n                                    .terminate_grace\\n                                    .max(PROVIDER_OUTPUT_DRAIN_GRACE_MINIMUM)\\n                        {\\n                            if cancellation_sent {\\n                                terminal = Some(ProviderTerminal::cancelled(format!(\\n                                    \\\"provider exited after cancellation: {status}\\\"\\n                                )));\\n                            } else {\\n                                return Err(JsonlProviderError::Interrupted(format!(\\n                                    \\\"provider exited and stdout did not deliver a turn terminal within the drain grace: {status}\\\"\\n                                )));\\n                            }\\n                        }\\n                    }\\n                    Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {\\n                        if cancellation_sent {\\n                            terminal = Some(ProviderTerminal::cancelled(\\n                                \\\"provider output closed after turn cancellation\\\",\\n                            ));\\n                        } else {\\n                            return Err(JsonlProviderError::Interrupted(\\n                                \\\"provider stdout reader disconnected\\\".to_string(),\\n                            ));\\n                        }\\n                    }\\n                }\\n            }\\n            terminal.ok_or_else(|| {\\n                JsonlProviderError::Interrupted(\\\"provider produced no terminal\\\".to_string())\\n            })\\n        })();\\n\\n        drop(provider_stdin);\\n        let natural_exit_wait = if result\\n            .as_ref()\\n            .is_ok_and(|terminal| terminal.status == ProviderTerminalStatus::Completed)\\n        {\\n            // A valid terminal frame may be read before the provider leader has\\n            // completed its ordinary exit. Do not manufacture a SIGTERM failure.\\n            allow_natural_exit_grace(&mut child, self.config.terminate_grace)\\n                .map_err(JsonlProviderError::Cleanup)\\n        } else {\\n            Ok(())\\n        };\\n        let cleanup = child.finish().map_err(JsonlProviderError::Cleanup);\\n        drop(receiver);\\n        let worker_errors = join_provider_workers_bounded(vec![stdout_thread, stderr_thread]);\\n        let stderr = stderr_capture\\n            .lock()\\n            .map_err(|_| JsonlProviderError::Cleanup(\\\"stderr capture was poisoned\\\".to_string()))?\\n            .clone();\\n\\n        // Preserve the first protocol/tool/provider error. Cleanup exists to\\n        // close the process tree, not to rewrite the semantic observation.\\n        let terminal = result?;\\n        natural_exit_wait?;\\n        if !worker_errors.is_empty() {\\n            return Err(JsonlProviderError::Cleanup(worker_errors.join(\\\"; \\\")));\\n        }\\n        let status = cleanup?;\\n        if stderr_overflow.load(Ordering::SeqCst) {\\n            return Err(JsonlProviderError::Protocol(format!(\\n                \\\"provider stderr exceeded its bound; prefix={}\\\",\\n                String::from_utf8_lossy(&stderr)\\n            )));\\n        }\\n        if !status.success() && terminal.status != ProviderTerminalStatus::Cancelled {\\n            return Err(JsonlProviderError::Interrupted(format!(\\n                \\\"provider exited unsuccessfully: {status}; stderr={}\\\",\\n                String::from_utf8_lossy(&stderr)\\n            )));\\n        }\\n        Ok(terminal)\\n    }\\n}\\n\\nimpl SameTurnProvider for JsonlProvider {\\n    fn run_turn(\\n        &mut self,\\n        request: &TurnRequest,\\n        host: &mut ProviderHost<'_>,\\n    ) -> std::result::Result<ProviderTerminal, String> {\\n        self.run_session(request, host)\\n            .map_err(|error| error.to_string())\\n    }\\n}\\n\\nfn write_json_line<W: Write + AsRawFd>(\\n    writer: &mut W,\\n    value: &impl Serialize,\\n    maximum: usize,\\n    turn_deadline: Option<Instant>,\\n) -> Result<()> {\\n    let encoded =\\n        serde_json::to_vec(value).map_err(|error| JsonlProviderError::Io(error.to_string()))?;\\n    // `max_line_bytes` bounds the complete JSONL frame, including its\\n    // newline delimiter.  Check with a subtraction rather than `len() + 1`\\n    // so a caller-provided maximum cannot wrap on an oversized value.\\n    if encoded.is_empty() || maximum == 0 || encoded.len() >= maximum {\\n        return Err(JsonlProviderError::Io(\\n            \\\"provider outbound JSONL record exceeds its bound\\\".to_string(),\\n        ));\\n    }\\n    let mut framed = encoded;\\n    framed.push(b'\\\\n');\\n    let io_deadline = Instant::now() + PROVIDER_WRITE_TIMEOUT;\\n    let deadline = turn_deadline.map_or(io_deadline, |turn| turn.min(io_deadline));\\n    let result = write_nonblocking(writer, &framed, deadline);\\n    if turn_deadline.is_some_and(|turn| Instant::now() >= turn) {\\n        return Err(JsonlProviderError::TimedOut);\\n    }\\n    result\\n}\\n\\n/// Write one provider frame without an unbounded blocking syscall.  The\\n/// descriptor's original flags are restored before returning so a caller that\\n/// reuses the handle observes the same ownership semantics.  `ChildStdin` is\\n/// intentionally the only production writer, but keeping the helper generic\\n/// makes the invariant directly testable with an ordinary pipe.\\nfn write_nonblocking<W: Write + AsRawFd>(\\n    writer: &mut W,\\n    bytes: &[u8],\\n    deadline: Instant,\\n) -> Result<()> {\\n    let fd = writer.as_raw_fd();\\n    let original_flags = unsafe { libc::fcntl(fd, libc::F_GETFL) };\\n    if original_flags < 0 {\\n        return Err(JsonlProviderError::Io(\\n            std::io::Error::last_os_error().to_string(),\\n        ));\\n    }\\n    if unsafe { libc::fcntl(fd, libc::F_SETFL, original_flags | libc::O_NONBLOCK) } < 0 {\\n        return Err(JsonlProviderError::Io(\\n            std::io::Error::last_os_error().to_string(),\\n        ));\\n    }\\n\\n    let write_result = write_nonblocking_loop(writer, fd, bytes, deadline);\\n    let restore_result = unsafe { libc::fcntl(fd, libc::F_SETFL, original_flags) };\\n    if restore_result < 0 {\\n        let restore_error = std::io::Error::last_os_error();\\n        return match write_result {\\n            Ok(()) => Err(JsonlProviderError::Io(format!(\\n                \\\"failed to restore provider stdin descriptor flags: {restore_error}\\\"\\n            ))),\\n            Err(error) => Err(JsonlProviderError::Io(format!(\\n                \\\"{error}; failed to restore provider stdin descriptor flags: {restore_error}\\\"\\n            ))),\\n        };\\n    }\\n    write_result\\n}\\n\\nfn write_nonblocking_loop<W: Write>(\\n    writer: &mut W,\\n    fd: i32,\\n    bytes: &[u8],\\n    deadline: Instant,\\n) -> Result<()> {\\n    let mut offset = 0usize;\\n    while offset < bytes.len() {\\n        if Instant::now() >= deadline {\\n            return Err(JsonlProviderError::Io(\\n                \\\"provider stdin write timed out\\\".to_string(),\\n            ));\\n        }\\n        match writer.write(&bytes[offset..]) {\\n            Ok(0) => {\\n                return Err(JsonlProviderError::Io(\\n                    \\\"provider stdin write returned zero bytes\\\".to_string(),\\n                ));\\n            }\\n            Ok(written) if written <= bytes.len() - offset => {\\n                offset += written;\\n            }\\n            Ok(_) => {\\n                return Err(JsonlProviderError::Io(\\n                    \\\"provider stdin writer reported more bytes than requested\\\".to_string(),\\n                ));\\n            }\\n            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,\\n            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {}\\n            Err(error) => return Err(JsonlProviderError::Io(error.to_string())),\\n        }\\n        if offset >= bytes.len() {\\n            break;\\n        }\\n        let remaining = deadline.saturating_duration_since(Instant::now());\\n        if remaining.is_zero() {\\n            return Err(JsonlProviderError::Io(\\n                \\\"provider stdin write timed out while the child was not reading\\\".to_string(),\\n            ));\\n        }\\n        let timeout_ms = remaining.as_millis().clamp(1, i32::MAX as u128) as libc::c_int;\\n        let mut poll_fd = libc::pollfd {\\n            fd,\\n            events: libc::POLLOUT,\\n            revents: 0,\\n        };\\n        let polled = unsafe { libc::poll(&mut poll_fd, 1, timeout_ms) };\\n        if polled < 0 {\\n            let error = std::io::Error::last_os_error();\\n            if error.raw_os_error() == Some(libc::EINTR) {\\n                continue;\\n            }\\n            return Err(JsonlProviderError::Io(error.to_string()));\\n        }\\n        if polled == 0 {\\n            // poll uses whole milliseconds. Its timeout may expire just\\n            // before the absolute deadline because of truncation (or the\\n            // i32 cap); recheck the monotonic clock in the loop before\\n            // classifying this as an I/O or turn timeout.\\n            continue;\\n        }\\n        if poll_fd.revents & (libc::POLLNVAL | libc::POLLERR | libc::POLLHUP) != 0 {\\n            return Err(JsonlProviderError::Io(\\n                \\\"provider stdin descriptor became unavailable while writing\\\".to_string(),\\n            ));\\n        }\\n    }\\n    Ok(())\\n}\\n\\nfn validate_os_value(path: &Path, label: &str, maximum: usize) -> Result<()> {\\n    let bytes = path.as_os_str().as_bytes();\\n    if bytes.is_empty() || bytes.len() > maximum || bytes.contains(&0) {\\n        return Err(invalid_config(format!(\\n            \\\"{label} is empty, oversized or contains NUL\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_environment(environment: &EnvironmentDelta) -> Result<()> {\\n    if environment.len() > 4096 {\\n        return Err(invalid_config(\\\"provider environment has too many entries\\\"));\\n    }\\n    let mut total = 0usize;\\n    for (key, value) in environment {\\n        if key.is_empty() || key.contains('=') || key.as_bytes().contains(&0) {\\n            return Err(invalid_config(\\\"provider environment key is invalid\\\"));\\n        }\\n        total = total.saturating_add(key.len());\\n        if let Some(value) = value {\\n            if value.as_bytes().contains(&0) {\\n                return Err(invalid_config(\\\"provider environment value contains NUL\\\"));\\n            }\\n            total = total.saturating_add(value.len());\\n        }\\n    }\\n    if total > 1024 * 1024 {\\n        return Err(invalid_config(\\\"provider environment exceeds one MiB\\\"));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_config_generation(value: &Value) -> Result<()> {\\n    match value {\\n        Value::Null => Ok(()),\\n        Value::Number(number) if number.as_i64().is_some() || number.as_u64().is_some() => Ok(()),\\n        Value::String(value) if !value.as_bytes().contains(&0) => Ok(()),\\n        _ => Err(invalid_config(\\n            \\\"provider config_generation must be an integer, string or null\\\",\\n        )),\\n    }\\n}\\n\\nfn invalid_config(message: impl Into<String>) -> JsonlProviderError {\\n    JsonlProviderError::InvalidConfiguration(message.into())\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use std::fs::File;\\n    use std::os::fd::FromRawFd;\\n    use std::time::Instant;\\n\\n    use super::*;\\n\\n    #[test]\\n    fn provider_stdin_write_is_bounded_when_the_child_stops_reading() {\\n        let mut descriptors = [0_i32; 2];\\n        assert_eq!(unsafe { libc::pipe(descriptors.as_mut_ptr()) }, 0);\\n        // Keep the read end open but deliberately do not drain it.  Once the\\n        // kernel pipe fills, the bounded writer must return instead of\\n        // blocking the provider turn forever.\\n        let _reader = unsafe { File::from_raw_fd(descriptors[0]) };\\n        let mut writer = unsafe { File::from_raw_fd(descriptors[1]) };\\n        let original_flags = unsafe { libc::fcntl(writer.as_raw_fd(), libc::F_GETFL) };\\n        assert!(original_flags >= 0);\\n        let payload = vec![b'x'; 2 * 1024 * 1024];\\n        let started = Instant::now();\\n        let deadline = started + Duration::from_millis(25);\\n        let error = write_nonblocking(&mut writer, &payload, deadline)\\n            .expect_err(\\\"a stalled pipe must hit the finite write deadline\\\");\\n        assert!(error.to_string().contains(\\\"timed out\\\"));\\n        assert!(Instant::now() >= deadline);\\n        assert!(started.elapsed() < Duration::from_secs(1));\\n        let restored_flags = unsafe { libc::fcntl(writer.as_raw_fd(), libc::F_GETFL) };\\n        assert_eq!(restored_flags, original_flags);\\n    }\\n\\n    #[test]\\n    fn provider_outbound_bound_includes_the_jsonl_delimiter() {\\n        let mut descriptors = [0_i32; 2];\\n        assert_eq!(unsafe { libc::pipe(descriptors.as_mut_ptr()) }, 0);\\n        let _reader = unsafe { File::from_raw_fd(descriptors[0]) };\\n        let mut writer = unsafe { File::from_raw_fd(descriptors[1]) };\\n        let value = json!({\\\"kind\\\": \\\"turn.complete\\\"});\\n        let encoded = serde_json::to_vec(&value).unwrap();\\n        write_json_line(&mut writer, &value, encoded.len() + 1, None)\\n            .expect(\\\"the exact framed length must fit\\\");\\n        let error = write_json_line(&mut writer, &value, encoded.len(), None)\\n            .expect_err(\\\"the delimiter must count against the frame bound\\\");\\n        assert!(error.to_string().contains(\\\"exceeds its bound\\\"));\\n    }\\n\\n    #[test]\\n    fn default_provider_resource_bounds_validate() {\\n        JsonlProviderConfig::default()\\n            .validate()\\n            .expect(\\\"default provider configuration is valid\\\");\\n    }\\n\\n    #[test]\\n    fn provider_resource_schema_ceilings_fail_closed() {\\n        macro_rules! assert_oversized {\\n            ($field:ident, $maximum:ident) => {{\\n                let mut config = JsonlProviderConfig::default();\\n                config.$field = $maximum + 1;\\n                let error = config\\n                    .validate()\\n                    .expect_err(\\\"oversized provider bound must fail closed\\\");\\n                assert!(\\n                    error.to_string().contains(stringify!($field)),\\n                    \\\"unexpected error for {}: {error}\\\",\\n                    stringify!($field)\\n                );\\n            }};\\n        }\\n\\n        assert_oversized!(max_line_bytes, MAX_JSONL_PROVIDER_LINE_BYTES);\\n        assert_oversized!(max_stdout_bytes, MAX_JSONL_PROVIDER_STDOUT_BYTES);\\n        assert_oversized!(max_event_count, MAX_JSONL_PROVIDER_EVENT_COUNT);\\n        assert_oversized!(max_stderr_bytes, MAX_JSONL_PROVIDER_STDERR_BYTES);\\n        assert_oversized!(output_queue_depth, MAX_JSONL_PROVIDER_OUTPUT_QUEUE_DEPTH);\\n\\n        let config = JsonlProviderConfig {\\n            timeout: MAX_JSONL_PROVIDER_TIMEOUT + Duration::from_nanos(1),\\n            ..JsonlProviderConfig::default()\\n        };\\n        assert!(\\n            config\\n                .validate()\\n                .unwrap_err()\\n                .to_string()\\n                .contains(\\\"timeout\\\")\\n        );\\n        let config = JsonlProviderConfig {\\n            poll_interval: MAX_JSONL_PROVIDER_POLL_INTERVAL + Duration::from_nanos(1),\\n            ..JsonlProviderConfig::default()\\n        };\\n        assert!(\\n            config\\n                .validate()\\n                .unwrap_err()\\n                .to_string()\\n                .contains(\\\"poll_interval\\\")\\n        );\\n        let config = JsonlProviderConfig {\\n            terminate_grace: MAX_JSONL_PROVIDER_TERMINATE_GRACE + Duration::from_nanos(1),\\n            ..JsonlProviderConfig::default()\\n        };\\n        assert!(\\n            config\\n                .validate()\\n                .unwrap_err()\\n                .to_string()\\n                .contains(\\\"terminate_grace\\\")\\n        );\\n\\n        let config = JsonlProviderConfig {\\n            max_line_bytes: MAX_JSONL_PROVIDER_LINE_BYTES,\\n            max_stdout_bytes: MAX_JSONL_PROVIDER_STDOUT_BYTES,\\n            output_queue_depth: MAX_JSONL_PROVIDER_QUEUE_BYTES\\n                .checked_div(MAX_JSONL_PROVIDER_LINE_BYTES)\\n                .and_then(|depth| depth.checked_add(1))\\n                .expect(\\\"provider queue test arithmetic fits\\\"),\\n            ..JsonlProviderConfig::default()\\n        };\\n        let error = config\\n            .validate()\\n            .expect_err(\\\"provider queue product must fail closed\\\");\\n        assert!(error.to_string().contains(\\\"output_queue_depth\\\"));\\n    }\\n}\\n\"},{\"path\":\"crates/trillionnium-owner-open-types/src/lib.rs\",\"sha\":\"ce1f8e76ae87135322d6f85b57ba17d1541addc4\",\"text\":\"//! Mechanism-only codec and validation types for the owner-open Direct Agent Host.\\n//!\\n//! This crate is deliberately isolated from the legacy plan, Authority,\\n//! capability-lease, privilege-broker and typed shell/ADB closures. Validation\\n//! is limited to framing, correlation shape, byte representation and finite\\n//! resource bounds. It must not classify commands, inject targets, require\\n//! semantic approval or rewrite tool arguments.\\n\\nmod generated;\\n\\npub use generated::*;\\n\\nuse std::collections::BTreeMap;\\n\\nuse serde::de::{self, MapAccess, SeqAccess, Visitor};\\nuse serde::{Deserialize, Deserializer, Serialize};\\nuse serde_json::Value;\\nuse thiserror::Error;\\n\\npub const PROTOCOL: &str = \\\"trillionnium.agent.turn.v1\\\";\\npub const PROTOCOL_VERSION: u32 = 1;\\n\\npub const FRAME_HELLO: &str = \\\"hello\\\";\\npub const FRAME_HELLO_ACK: &str = \\\"hello.ack\\\";\\npub const FRAME_TURN_START: &str = \\\"turn.start\\\";\\npub const FRAME_TURN_ACCEPTED: &str = \\\"turn.accepted\\\";\\npub const FRAME_TURN_CANCEL: &str = \\\"turn.cancel\\\";\\npub const FRAME_TURN_END: &str = \\\"turn.end\\\";\\npub const FRAME_TOOL_CALL: &str = \\\"tool.call\\\";\\npub const FRAME_TOOL_ACCEPTED: &str = \\\"tool.accepted\\\";\\npub const FRAME_TOOL_STARTED: &str = \\\"tool.started\\\";\\npub const FRAME_TOOL_STDOUT: &str = \\\"tool.stdout\\\";\\npub const FRAME_TOOL_STDERR: &str = \\\"tool.stderr\\\";\\npub const FRAME_TOOL_PTY: &str = \\\"tool.pty\\\";\\npub const FRAME_TOOL_RESULT: &str = \\\"tool.result\\\";\\npub const FRAME_TOOL_CANCEL: &str = \\\"tool.cancel\\\";\\npub const FRAME_STREAM_WINDOW_UPDATE: &str = \\\"stream.window_update\\\";\\npub const FRAME_STREAM_PAUSE: &str = \\\"stream.pause\\\";\\npub const FRAME_STREAM_RESUME: &str = \\\"stream.resume\\\";\\n\\n/// Schema ceilings for parser and process-facing wire limits. These are\\n/// liveness constraints, not semantic permissions. An owner profile may select\\n/// smaller finite values, but cannot use a malformed profile to request\\n/// effectively unbounded frame, argument or environment storage.\\npub const MAX_CODEC_FRAME_BYTES: usize = 16 * 1024 * 1024;\\npub const MAX_CODEC_LABEL_BYTES: usize = 64 * 1024;\\npub const MAX_CODEC_ID_BYTES: usize = 4 * 1024;\\npub const MAX_CODEC_USER_INPUT_BYTES: usize = 16 * 1024 * 1024;\\npub const MAX_CODEC_COMMAND_BYTES: usize = 4 * 1024 * 1024;\\npub const MAX_CODEC_ARGV_ITEMS: usize = 65_536;\\npub const MAX_CODEC_ARGUMENT_BYTES: usize = 1024 * 1024;\\npub const MAX_CODEC_TOTAL_ARGV_BYTES: usize = 16 * 1024 * 1024;\\npub const MAX_CODEC_ENV_ITEMS: usize = 65_536;\\npub const MAX_CODEC_ENV_KEY_BYTES: usize = 16 * 1024;\\npub const MAX_CODEC_ENV_VALUE_BYTES: usize = 1024 * 1024;\\npub const MAX_CODEC_TOTAL_ENV_BYTES: usize = 16 * 1024 * 1024;\\npub const MAX_CODEC_TIMEOUT_MS: i64 = 24 * 60 * 60 * 1000;\\n\\n#[derive(Debug, Clone, PartialEq, Eq)]\\npub struct MechanicalLimits {\\n    pub max_frame_bytes: usize,\\n    pub max_label_bytes: usize,\\n    pub max_id_bytes: usize,\\n    pub max_user_input_bytes: usize,\\n    pub max_command_bytes: usize,\\n    pub max_argv_items: usize,\\n    pub max_argument_bytes: usize,\\n    pub max_total_argv_bytes: usize,\\n    pub max_env_items: usize,\\n    pub max_env_key_bytes: usize,\\n    pub max_env_value_bytes: usize,\\n}\\n\\nimpl Default for MechanicalLimits {\\n    fn default() -> Self {\\n        Self {\\n            max_frame_bytes: 1024 * 1024,\\n            max_label_bytes: 256,\\n            max_id_bytes: 256,\\n            max_user_input_bytes: 1024 * 1024,\\n            max_command_bytes: 256 * 1024,\\n            max_argv_items: 4096,\\n            max_argument_bytes: 64 * 1024,\\n            max_total_argv_bytes: 1024 * 1024,\\n            max_env_items: 4096,\\n            max_env_key_bytes: 4096,\\n            max_env_value_bytes: 64 * 1024,\\n        }\\n    }\\n}\\n\\nimpl MechanicalLimits {\\n    pub fn validate(&self) -> Result<()> {\\n        if self.max_frame_bytes == 0\\n            || self.max_label_bytes == 0\\n            || self.max_id_bytes == 0\\n            || self.max_user_input_bytes == 0\\n            || self.max_command_bytes == 0\\n            || self.max_argv_items == 0\\n            || self.max_argument_bytes == 0\\n            || self.max_total_argv_bytes == 0\\n            || self.max_env_items == 0\\n            || self.max_env_key_bytes == 0\\n            || self.max_env_value_bytes == 0\\n        {\\n            return Err(invalid(\\\"mechanical limits must be non-zero\\\"));\\n        }\\n        for (name, value, maximum) in [\\n            (\\n                \\\"max_frame_bytes\\\",\\n                self.max_frame_bytes,\\n                MAX_CODEC_FRAME_BYTES,\\n            ),\\n            (\\n                \\\"max_label_bytes\\\",\\n                self.max_label_bytes,\\n                MAX_CODEC_LABEL_BYTES,\\n            ),\\n            (\\\"max_id_bytes\\\", self.max_id_bytes, MAX_CODEC_ID_BYTES),\\n            (\\n                \\\"max_user_input_bytes\\\",\\n                self.max_user_input_bytes,\\n                MAX_CODEC_USER_INPUT_BYTES,\\n            ),\\n            (\\n                \\\"max_command_bytes\\\",\\n                self.max_command_bytes,\\n                MAX_CODEC_COMMAND_BYTES,\\n            ),\\n            (\\\"max_argv_items\\\", self.max_argv_items, MAX_CODEC_ARGV_ITEMS),\\n            (\\n                \\\"max_argument_bytes\\\",\\n                self.max_argument_bytes,\\n                MAX_CODEC_ARGUMENT_BYTES,\\n            ),\\n            (\\n                \\\"max_total_argv_bytes\\\",\\n                self.max_total_argv_bytes,\\n                MAX_CODEC_TOTAL_ARGV_BYTES,\\n            ),\\n            (\\\"max_env_items\\\", self.max_env_items, MAX_CODEC_ENV_ITEMS),\\n            (\\n                \\\"max_env_key_bytes\\\",\\n                self.max_env_key_bytes,\\n                MAX_CODEC_ENV_KEY_BYTES,\\n            ),\\n            (\\n                \\\"max_env_value_bytes\\\",\\n                self.max_env_value_bytes,\\n                MAX_CODEC_ENV_VALUE_BYTES,\\n            ),\\n        ] {\\n            if value > maximum {\\n                return Err(invalid(format!(\\\"{name} exceeds hard bound {maximum}\\\")));\\n            }\\n        }\\n        if self.max_argument_bytes > self.max_total_argv_bytes {\\n            return Err(invalid(\\n                \\\"max_argument_bytes cannot exceed max_total_argv_bytes\\\",\\n            ));\\n        }\\n        Ok(())\\n    }\\n}\\n\\n#[derive(Debug, Error, Clone, PartialEq, Eq)]\\npub enum ProtocolError {\\n    #[error(\\\"frame_boundary: {0}\\\")]\\n    FrameBoundary(&'static str),\\n    #[error(\\\"invalid_json: {0}\\\")]\\n    InvalidJson(String),\\n    #[error(\\\"invalid_frame: {0}\\\")]\\n    InvalidFrame(String),\\n}\\n\\npub type Result<T> = std::result::Result<T, ProtocolError>;\\n\\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\\npub struct RunTurnFrame {\\n    pub kind: String,\\n    pub seq: u64,\\n    pub payload: Value,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub direction: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub client_seq: Option<u64>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub host_seq: Option<u64>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub frame_sha256: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub event_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub connection_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub stream_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub turn_stream_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub session_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub profile_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub task_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub turn_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub call_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub job_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub tool: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub target: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub target_id: Option<String>,\\n    #[serde(default, flatten)]\\n    pub extensions: BTreeMap<String, Value>,\\n}\\n\\nimpl RunTurnFrame {\\n    pub fn decode(encoded: &[u8], limits: &MechanicalLimits) -> Result<Self> {\\n        decode_strict_frame(encoded, limits)\\n    }\\n\\n    pub fn validate_mechanical(&self, limits: &MechanicalLimits) -> Result<()> {\\n        limits.validate()?;\\n        validate_label(\\\"kind\\\", &self.kind, limits.max_label_bytes)?;\\n        if !self.payload.is_object() {\\n            return Err(invalid(\\\"payload must be a JSON object\\\"));\\n        }\\n        if let Some(direction) = self.direction.as_deref()\\n            && !matches!(direction, \\\"client_to_host\\\" | \\\"host_to_client\\\")\\n        {\\n            return Err(invalid(\\\"direction is not a supported transport role\\\"));\\n        }\\n        validate_optional_digest(\\\"frame_sha256\\\", self.frame_sha256.as_deref())?;\\n        for (name, value) in [\\n            (\\\"event_id\\\", self.event_id.as_deref()),\\n            (\\\"connection_id\\\", self.connection_id.as_deref()),\\n            (\\\"stream_id\\\", self.stream_id.as_deref()),\\n            (\\\"turn_stream_id\\\", self.turn_stream_id.as_deref()),\\n            (\\\"session_id\\\", self.session_id.as_deref()),\\n            (\\\"profile_id\\\", self.profile_id.as_deref()),\\n            (\\\"task_id\\\", self.task_id.as_deref()),\\n            (\\\"turn_id\\\", self.turn_id.as_deref()),\\n            (\\\"call_id\\\", self.call_id.as_deref()),\\n            (\\\"job_id\\\", self.job_id.as_deref()),\\n        ] {\\n            if let Some(value) = value {\\n                validate_id(name, value, limits.max_id_bytes)?;\\n            }\\n        }\\n        for (name, value) in [\\n            (\\\"tool\\\", self.tool.as_deref()),\\n            (\\\"target\\\", self.target.as_deref()),\\n            (\\\"target_id\\\", self.target_id.as_deref()),\\n        ] {\\n            if let Some(value) = value {\\n                validate_label(name, value, limits.max_label_bytes)?;\\n            }\\n        }\\n        validate_alias_pair(\\n            \\\"stream_id\\\",\\n            self.stream_id.as_deref(),\\n            \\\"turn_stream_id\\\",\\n            self.turn_stream_id.as_deref(),\\n        )?;\\n        validate_alias_pair(\\n            \\\"target\\\",\\n            self.target.as_deref(),\\n            \\\"target_id\\\",\\n            self.target_id.as_deref(),\\n        )?;\\n        Ok(())\\n    }\\n\\n    pub fn turn_request(&self, limits: &MechanicalLimits) -> Result<RunTurnRequest> {\\n        self.validate_mechanical(limits)?;\\n        if self.kind != FRAME_TURN_START {\\n            return Err(invalid(\\\"frame kind is not turn.start\\\"));\\n        }\\n        let request: RunTurnRequest = serde_json::from_value(self.payload.clone())\\n            .map_err(|error| invalid(format!(\\\"invalid turn.start payload: {error}\\\")))?;\\n        request.validate_mechanical(limits)?;\\n        validate_mirrored_id(\\n            \\\"session_id\\\",\\n            self.session_id.as_deref(),\\n            &request.session_id,\\n        )?;\\n        validate_mirrored_id(\\\"task_id\\\", self.task_id.as_deref(), &request.task_id)?;\\n        validate_mirrored_id(\\\"turn_id\\\", self.turn_id.as_deref(), &request.turn_id)?;\\n        if let Some(profile_id) = self.profile_id.as_deref()\\n            && profile_id != request.effective_profile_id()\\n        {\\n            return Err(invalid(\\n                \\\"envelope profile_id conflicts with payload profile_id\\\",\\n            ));\\n        }\\n        Ok(request)\\n    }\\n\\n    pub fn turn_cancel(&self, limits: &MechanicalLimits) -> Result<TurnCancelRequest> {\\n        self.validate_mechanical(limits)?;\\n        if self.kind != FRAME_TURN_CANCEL {\\n            return Err(invalid(\\\"frame kind is not turn.cancel\\\"));\\n        }\\n        let request: TurnCancelRequest = serde_json::from_value(self.payload.clone())\\n            .map_err(|error| invalid(format!(\\\"invalid turn.cancel payload: {error}\\\")))?;\\n        request.validate_mechanical(limits)?;\\n        validate_mirrored_id(\\n            \\\"session_id\\\",\\n            self.session_id.as_deref(),\\n            &request.session_id,\\n        )?;\\n        validate_mirrored_id(\\\"turn_id\\\", self.turn_id.as_deref(), &request.turn_id)?;\\n        validate_optional_alias(\\n            \\\"profile_id\\\",\\n            self.profile_id.as_deref(),\\n            request.profile_id.as_deref(),\\n        )?;\\n        validate_optional_alias(\\n            \\\"task_id\\\",\\n            self.task_id.as_deref(),\\n            request.task_id.as_deref(),\\n        )?;\\n        validate_alias_pair(\\n            \\\"turn_stream_id\\\",\\n            self.turn_stream_id.as_deref().or(self.stream_id.as_deref()),\\n            \\\"payload.turn_stream_id\\\",\\n            request.turn_stream_id.as_deref(),\\n        )?;\\n        Ok(request)\\n    }\\n\\n    pub fn tool_call(&self, limits: &MechanicalLimits) -> Result<ToolCall> {\\n        self.validate_mechanical(limits)?;\\n        if self.kind != FRAME_TOOL_CALL {\\n            return Err(invalid(\\\"frame kind is not tool.call\\\"));\\n        }\\n        let call: ToolCall = serde_json::from_value(self.payload.clone())\\n            .map_err(|error| invalid(format!(\\\"invalid tool.call payload: {error}\\\")))?;\\n        call.validate_mechanical(limits)?;\\n        validate_mirrored_id(\\\"call_id\\\", self.call_id.as_deref(), &call.call_id)?;\\n        validate_mirrored_id(\\\"tool\\\", self.tool.as_deref(), &call.tool)?;\\n        Ok(call)\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\\npub struct RunTurnRequest {\\n    pub protocol: String,\\n    pub protocol_version: Value,\\n    pub session_id: String,\\n    pub task_id: String,\\n    pub turn_id: String,\\n    pub user_input: String,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub profile_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub context_ref: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub config_generation: Option<Value>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub client_request_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub server_request_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub turn_request_sha256: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub resume_cursor: Option<Value>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub resume_token: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub prior_connection_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub parent_turn_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub continuation_of: Option<String>,\\n    #[serde(default, flatten)]\\n    pub extensions: BTreeMap<String, Value>,\\n}\\n\\nimpl RunTurnRequest {\\n    pub fn validate_mechanical(&self, limits: &MechanicalLimits) -> Result<()> {\\n        limits.validate()?;\\n        if self.protocol != PROTOCOL {\\n            return Err(invalid(\\\"unsupported turn protocol\\\"));\\n        }\\n        validate_protocol_version(&self.protocol_version)?;\\n        validate_id(\\\"session_id\\\", &self.session_id, limits.max_id_bytes)?;\\n        validate_id(\\\"task_id\\\", &self.task_id, limits.max_id_bytes)?;\\n        validate_id(\\\"turn_id\\\", &self.turn_id, limits.max_id_bytes)?;\\n        if self.user_input.len() > limits.max_user_input_bytes {\\n            return Err(invalid(\\\"user_input exceeds the configured byte bound\\\"));\\n        }\\n        if self.user_input.contains('\\\\0') {\\n            return Err(invalid(\\\"user_input contains NUL\\\"));\\n        }\\n        for (name, value) in [\\n            (\\\"profile_id\\\", self.profile_id.as_deref()),\\n            (\\\"context_ref\\\", self.context_ref.as_deref()),\\n            (\\\"client_request_id\\\", self.client_request_id.as_deref()),\\n            (\\\"server_request_id\\\", self.server_request_id.as_deref()),\\n            (\\\"resume_token\\\", self.resume_token.as_deref()),\\n            (\\\"prior_connection_id\\\", self.prior_connection_id.as_deref()),\\n            (\\\"parent_turn_id\\\", self.parent_turn_id.as_deref()),\\n            (\\\"continuation_of\\\", self.continuation_of.as_deref()),\\n        ] {\\n            if let Some(value) = value {\\n                validate_id(name, value, limits.max_id_bytes)?;\\n            }\\n        }\\n        validate_optional_digest(\\\"turn_request_sha256\\\", self.turn_request_sha256.as_deref())?;\\n        validate_alias_pair(\\n            \\\"parent_turn_id\\\",\\n            self.parent_turn_id.as_deref(),\\n            \\\"continuation_of\\\",\\n            self.continuation_of.as_deref(),\\n        )?;\\n        validate_resume_pair(self.resume_cursor.as_ref(), self.resume_token.as_deref())?;\\n        if self.prior_connection_id.is_some()\\n            && self.resume_cursor.is_none()\\n            && self.resume_token.is_none()\\n        {\\n            return Err(invalid(\\n                \\\"prior_connection_id requires exactly one resume cursor or token\\\",\\n            ));\\n        }\\n        Ok(())\\n    }\\n\\n    pub fn effective_profile_id(&self) -> &str {\\n        self.profile_id.as_deref().unwrap_or(DEFAULT_PROFILE_ID)\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\\npub struct TurnCancelRequest {\\n    pub session_id: String,\\n    pub turn_id: String,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub profile_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub task_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub turn_stream_id: Option<String>,\\n    #[serde(default, flatten)]\\n    pub extensions: BTreeMap<String, Value>,\\n}\\n\\nimpl TurnCancelRequest {\\n    pub fn validate_mechanical(&self, limits: &MechanicalLimits) -> Result<()> {\\n        limits.validate()?;\\n        validate_id(\\\"session_id\\\", &self.session_id, limits.max_id_bytes)?;\\n        validate_id(\\\"turn_id\\\", &self.turn_id, limits.max_id_bytes)?;\\n        for (name, value) in [\\n            (\\\"profile_id\\\", self.profile_id.as_deref()),\\n            (\\\"task_id\\\", self.task_id.as_deref()),\\n            (\\\"turn_stream_id\\\", self.turn_stream_id.as_deref()),\\n        ] {\\n            if let Some(value) = value {\\n                validate_id(name, value, limits.max_id_bytes)?;\\n            }\\n        }\\n        Ok(())\\n    }\\n}\\n\\n#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\\npub struct ToolCall {\\n    pub call_id: String,\\n    pub tool: String,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub session_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub profile_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub task_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub turn_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub turn_stream_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub request_sha256: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub binding_fingerprint: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub target: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub target_id: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub mode: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub config_generation: Option<Value>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub command: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub argv: Option<Vec<String>>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub cwd: Option<String>,\\n    #[serde(default, skip_serializing_if = \\\"BTreeMap::is_empty\\\")]\\n    pub env: BTreeMap<String, Option<String>>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub stdin: Option<Value>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub timeout_ms: Option<i64>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub pty: Option<Value>,\\n    #[serde(default, skip_serializing_if = \\\"Option::is_none\\\")]\\n    pub stream: Option<bool>,\\n    #[serde(default, flatten)]\\n    pub extensions: BTreeMap<String, Value>,\\n}\\n\\nimpl ToolCall {\\n    pub fn validate_mechanical(&self, limits: &MechanicalLimits) -> Result<()> {\\n        limits.validate()?;\\n        validate_id(\\\"call_id\\\", &self.call_id, limits.max_id_bytes)?;\\n        validate_label(\\\"tool\\\", &self.tool, limits.max_label_bytes)?;\\n        for (name, value) in [\\n            (\\\"session_id\\\", self.session_id.as_deref()),\\n            (\\\"profile_id\\\", self.profile_id.as_deref()),\\n            (\\\"task_id\\\", self.task_id.as_deref()),\\n            (\\\"turn_id\\\", self.turn_id.as_deref()),\\n            (\\\"turn_stream_id\\\", self.turn_stream_id.as_deref()),\\n        ] {\\n            if let Some(value) = value {\\n                validate_id(name, value, limits.max_id_bytes)?;\\n            }\\n        }\\n        validate_optional_digest(\\\"request_sha256\\\", self.request_sha256.as_deref())?;\\n        validate_optional_digest(\\\"binding_fingerprint\\\", self.binding_fingerprint.as_deref())?;\\n        for (name, value) in [\\n            (\\\"target\\\", self.target.as_deref()),\\n            (\\\"target_id\\\", self.target_id.as_deref()),\\n            (\\\"mode\\\", self.mode.as_deref()),\\n        ] {\\n            if let Some(value) = value {\\n                validate_label(name, value, limits.max_label_bytes)?;\\n            }\\n        }\\n        validate_alias_pair(\\n            \\\"target\\\",\\n            self.target.as_deref(),\\n            \\\"target_id\\\",\\n            self.target_id.as_deref(),\\n        )?;\\n        if let Some(timeout_ms) = self.timeout_ms {\\n            if timeout_ms < 0 {\\n                return Err(invalid(\\\"timeout_ms must be nonnegative\\\"));\\n            }\\n            if timeout_ms > MAX_CODEC_TIMEOUT_MS {\\n                return Err(invalid(format!(\\n                    \\\"timeout_ms exceeds hard bound {MAX_CODEC_TIMEOUT_MS}\\\"\\n                )));\\n            }\\n        }\\n        if let Some(cwd) = self.cwd.as_deref()\\n            && cwd.contains('\\\\0')\\n        {\\n            return Err(invalid(\\\"cwd contains NUL\\\"));\\n        }\\n        validate_env(&self.env, limits)?;\\n        if let Some(command) = self.command.as_deref() {\\n            validate_command(command, limits)?;\\n        }\\n        if let Some(argv) = self.argv.as_deref() {\\n            validate_argv(argv, limits)?;\\n        }\\n        Ok(())\\n    }\\n\\n    /// Validate only the wire shape for `shell.exec`. No allowlist, target\\n    /// substitution, risk class or approval decision is performed.\\n    pub fn validate_shell_exec(&self, limits: &MechanicalLimits) -> Result<()> {\\n        self.validate_mechanical(limits)?;\\n        if self.tool != \\\"shell.exec\\\" {\\n            return Err(invalid(\\\"shell.exec codec requires tool=shell.exec\\\"));\\n        }\\n        match (&self.command, &self.argv) {\\n            (Some(_), None) | (None, Some(_)) => Ok(()),\\n            (None, None) => Err(invalid(\\\"shell.exec requires command or argv\\\")),\\n            (Some(_), Some(_)) => Err(invalid(\\n                \\\"shell.exec command and argv are mutually exclusive\\\",\\n            )),\\n        }\\n    }\\n\\n    /// Validate only the wire shape for `adb.exec`. Unknown and future ADB\\n    /// subcommands stay valid, and no serial/host/port/privilege is injected.\\n    pub fn validate_adb_exec(&self, limits: &MechanicalLimits) -> Result<()> {\\n        self.validate_mechanical(limits)?;\\n        if self.tool != \\\"adb.exec\\\" {\\n            return Err(invalid(\\\"adb.exec codec requires tool=adb.exec\\\"));\\n        }\\n        if self.command.is_some() {\\n            return Err(invalid(\\\"adb.exec accepts argv, not command\\\"));\\n        }\\n        if self.argv.is_none() {\\n            return Err(invalid(\\\"adb.exec requires argv\\\"));\\n        }\\n        Ok(())\\n    }\\n}\\n\\n/// Decode one bounded JSON value while rejecting duplicate members at every\\n/// nesting level.  Callers that need to preserve an outer correlation\\n/// envelope after frame-level validation fails can inspect this value before\\n/// deserializing the semantic `RunTurnFrame`.\\npub fn decode_strict_value(encoded: &[u8], limits: &MechanicalLimits) -> Result<Value> {\\n    limits.validate()?;\\n    if encoded.is_empty() {\\n        return Err(ProtocolError::FrameBoundary(\\\"frame is empty\\\"));\\n    }\\n    if encoded.len() > limits.max_frame_bytes {\\n        return Err(ProtocolError::FrameBoundary(\\n            \\\"frame exceeds the configured byte bound\\\",\\n        ));\\n    }\\n    let mut deserializer = serde_json::Deserializer::from_slice(encoded);\\n    let UniqueJson(value) = UniqueJson::deserialize(&mut deserializer)\\n        .map_err(|error| ProtocolError::InvalidJson(error.to_string()))?;\\n    deserializer\\n        .end()\\n        .map_err(|error| ProtocolError::InvalidJson(error.to_string()))?;\\n    Ok(value)\\n}\\n\\npub fn decode_strict_frame(encoded: &[u8], limits: &MechanicalLimits) -> Result<RunTurnFrame> {\\n    let value = decode_strict_value(encoded, limits)?;\\n    let frame: RunTurnFrame = serde_json::from_value(value)\\n        .map_err(|error| invalid(format!(\\\"invalid frame envelope: {error}\\\")))?;\\n    frame.validate_mechanical(limits)?;\\n    Ok(frame)\\n}\\n\\nfn validate_protocol_version(value: &Value) -> Result<()> {\\n    match value {\\n        Value::Number(number) if number.as_u64() == Some(u64::from(PROTOCOL_VERSION)) => Ok(()),\\n        Value::String(version) if version == &PROTOCOL_VERSION.to_string() => Ok(()),\\n        _ => Err(invalid(\\\"unsupported protocol_version\\\")),\\n    }\\n}\\n\\nfn validate_resume_pair(cursor: Option<&Value>, token: Option<&str>) -> Result<()> {\\n    if cursor.is_some() && token.is_some() {\\n        return Err(invalid(\\n            \\\"resume_cursor and resume_token are mutually exclusive\\\",\\n        ));\\n    }\\n    if let Some(cursor) = cursor {\\n        match cursor {\\n            Value::Number(number) if number.as_u64().is_some() => {}\\n            Value::String(value) if !value.is_empty() && !value.chars().any(char::is_control) => {}\\n            _ => return Err(invalid(\\\"resume_cursor has an invalid shape\\\")),\\n        }\\n    }\\n    Ok(())\\n}\\n\\nfn validate_mirrored_id(name: &str, envelope: Option<&str>, payload: &str) -> Result<()> {\\n    if envelope.is_some_and(|value| value != payload) {\\n        return Err(invalid(format!(\\n            \\\"envelope {name} conflicts with payload {name}\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_optional_alias(name: &str, first: Option<&str>, second: Option<&str>) -> Result<()> {\\n    if let (Some(first), Some(second)) = (first, second)\\n        && first != second\\n    {\\n        return Err(invalid(format!(\\n            \\\"envelope {name} conflicts with payload {name}\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_alias_pair(\\n    first_name: &str,\\n    first: Option<&str>,\\n    second_name: &str,\\n    second: Option<&str>,\\n) -> Result<()> {\\n    if let (Some(first), Some(second)) = (first, second)\\n        && first != second\\n    {\\n        return Err(invalid(format!(\\n            \\\"{first_name} conflicts with alias {second_name}\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_optional_digest(name: &str, value: Option<&str>) -> Result<()> {\\n    if value.is_some_and(|value| !is_lower_sha256(value)) {\\n        return Err(invalid(format!(\\\"{name} must be a lowercase SHA-256\\\")));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_command(command: &str, limits: &MechanicalLimits) -> Result<()> {\\n    if command.is_empty() {\\n        return Err(invalid(\\\"command is empty\\\"));\\n    }\\n    if command.len() > limits.max_command_bytes {\\n        return Err(invalid(\\\"command exceeds the configured byte bound\\\"));\\n    }\\n    if command.contains('\\\\0') {\\n        return Err(invalid(\\\"command contains NUL\\\"));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_argv(argv: &[String], limits: &MechanicalLimits) -> Result<()> {\\n    if argv.is_empty() {\\n        return Err(invalid(\\\"argv is empty\\\"));\\n    }\\n    if argv.len() > limits.max_argv_items {\\n        return Err(invalid(\\\"argv exceeds the configured item bound\\\"));\\n    }\\n    let mut total = 0usize;\\n    for argument in argv {\\n        if argument.len() > limits.max_argument_bytes {\\n            return Err(invalid(\\\"argv element exceeds the configured byte bound\\\"));\\n        }\\n        if argument.contains('\\\\0') {\\n            return Err(invalid(\\\"argv element contains NUL\\\"));\\n        }\\n        total = total\\n            .checked_add(argument.len())\\n            .ok_or_else(|| invalid(\\\"argv byte count overflow\\\"))?;\\n        if total > limits.max_total_argv_bytes {\\n            return Err(invalid(\\\"argv exceeds the configured total byte bound\\\"));\\n        }\\n    }\\n    Ok(())\\n}\\n\\nfn validate_env(env: &BTreeMap<String, Option<String>>, limits: &MechanicalLimits) -> Result<()> {\\n    if env.len() > limits.max_env_items {\\n        return Err(invalid(\\\"env exceeds the configured item bound\\\"));\\n    }\\n    let mut total = 0usize;\\n    for (key, value) in env {\\n        if key.is_empty()\\n            || key.len() > limits.max_env_key_bytes\\n            || key.contains('\\\\0')\\n            || key.contains('=')\\n        {\\n            return Err(invalid(\\\"env key is not mechanically representable\\\"));\\n        }\\n        if value\\n            .as_deref()\\n            .is_some_and(|value| value.len() > limits.max_env_value_bytes || value.contains('\\\\0'))\\n        {\\n            return Err(invalid(\\\"env value is not mechanically representable\\\"));\\n        }\\n        total = total\\n            .checked_add(key.len())\\n            .and_then(|total| total.checked_add(value.as_deref().map_or(0, str::len)))\\n            .ok_or_else(|| invalid(\\\"env byte count overflow\\\"))?;\\n    }\\n    if total > MAX_CODEC_TOTAL_ENV_BYTES {\\n        return Err(invalid(\\\"env exceeds the hard total byte bound\\\"));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_label(name: &str, value: &str, max_bytes: usize) -> Result<()> {\\n    if value.is_empty() || value.len() > max_bytes || value.chars().any(char::is_control) {\\n        return Err(invalid(format!(\\n            \\\"{name} is empty, oversized, or contains control bytes\\\"\\n        )));\\n    }\\n    Ok(())\\n}\\n\\nfn validate_id(name: &str, value: &str, max_bytes: usize) -> Result<()> {\\n    validate_label(name, value, max_bytes)\\n}\\n\\nfn is_lower_sha256(value: &str) -> bool {\\n    value.len() == 64\\n        && value\\n            .bytes()\\n            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))\\n}\\n\\nfn invalid(message: impl Into<String>) -> ProtocolError {\\n    ProtocolError::InvalidFrame(message.into())\\n}\\n\\nstruct UniqueJson(Value);\\n\\nimpl<'de> Deserialize<'de> for UniqueJson {\\n    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>\\n    where\\n        D: Deserializer<'de>,\\n    {\\n        deserializer.deserialize_any(UniqueJsonVisitor)\\n    }\\n}\\n\\nstruct UniqueJsonVisitor;\\n\\nimpl<'de> Visitor<'de> for UniqueJsonVisitor {\\n    type Value = UniqueJson;\\n\\n    fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\\n        formatter.write_str(\\\"JSON without duplicate object members\\\")\\n    }\\n\\n    fn visit_unit<E>(self) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::Null))\\n    }\\n\\n    fn visit_none<E>(self) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::Null))\\n    }\\n\\n    fn visit_some<D>(self, deserializer: D) -> std::result::Result<Self::Value, D::Error>\\n    where\\n        D: Deserializer<'de>,\\n    {\\n        UniqueJson::deserialize(deserializer)\\n    }\\n\\n    fn visit_bool<E>(self, value: bool) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::Bool(value)))\\n    }\\n\\n    fn visit_i64<E>(self, value: i64) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::Number(value.into())))\\n    }\\n\\n    fn visit_u64<E>(self, value: u64) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::Number(value.into())))\\n    }\\n\\n    fn visit_f64<E>(self, value: f64) -> std::result::Result<Self::Value, E>\\n    where\\n        E: de::Error,\\n    {\\n        serde_json::Number::from_f64(value)\\n            .map(Value::Number)\\n            .map(UniqueJson)\\n            .ok_or_else(|| E::custom(\\\"non-finite JSON number\\\"))\\n    }\\n\\n    fn visit_str<E>(self, value: &str) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::String(value.to_string())))\\n    }\\n\\n    fn visit_string<E>(self, value: String) -> std::result::Result<Self::Value, E> {\\n        Ok(UniqueJson(Value::String(value)))\\n    }\\n\\n    fn visit_seq<A>(self, mut sequence: A) -> std::result::Result<Self::Value, A::Error>\\n    where\\n        A: SeqAccess<'de>,\\n    {\\n        let mut output = Vec::new();\\n        while let Some(value) = sequence.next_element::<UniqueJson>()? {\\n            output.push(value.0);\\n        }\\n        Ok(UniqueJson(Value::Array(output)))\\n    }\\n\\n    fn visit_map<A>(self, mut map: A) -> std::result::Result<Self::Value, A::Error>\\n    where\\n        A: MapAccess<'de>,\\n    {\\n        let mut output = serde_json::Map::new();\\n        while let Some(key) = map.next_key::<String>()? {\\n            if output.contains_key(&key) {\\n                return Err(de::Error::custom(format!(\\\"duplicate key {key}\\\")));\\n            }\\n            let value = map.next_value::<UniqueJson>()?;\\n            output.insert(key, value.0);\\n        }\\n        Ok(UniqueJson(Value::Object(output)))\\n    }\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n    use serde_json::json;\\n\\n    fn base_tool_call() -> ToolCall {\\n        ToolCall {\\n            call_id: \\\"call-1\\\".to_string(),\\n            tool: \\\"shell.exec\\\".to_string(),\\n            session_id: Some(\\\"session-1\\\".to_string()),\\n            profile_id: Some(DEFAULT_PROFILE_ID.to_string()),\\n            task_id: Some(\\\"task-1\\\".to_string()),\\n            turn_id: Some(\\\"turn-1\\\".to_string()),\\n            turn_stream_id: Some(\\\"stream-1\\\".to_string()),\\n            request_sha256: None,\\n            binding_fingerprint: None,\\n            target: Some(\\\"rootlinux\\\".to_string()),\\n            target_id: None,\\n            mode: None,\\n            config_generation: None,\\n            command: None,\\n            argv: None,\\n            cwd: None,\\n            env: BTreeMap::new(),\\n            stdin: None,\\n            timeout_ms: Some(0),\\n            pty: None,\\n            stream: Some(true),\\n            extensions: BTreeMap::new(),\\n        }\\n    }\\n\\n    #[test]\\n    fn strict_decoder_rejects_duplicate_members_recursively() {\\n        let encoded = br#\\\"{\\n          \\\"kind\\\":\\\"tool.call\\\",\\n          \\\"seq\\\":1,\\n          \\\"payload\\\":{\\\"call_id\\\":\\\"one\\\",\\\"call_id\\\":\\\"two\\\",\\\"tool\\\":\\\"shell.exec\\\",\\\"command\\\":\\\"pwd\\\"}\\n        }\\\"#;\\n        let error = RunTurnFrame::decode(encoded, &MechanicalLimits::default()).unwrap_err();\\n        assert!(error.to_string().contains(\\\"duplicate key call_id\\\"));\\n    }\\n\\n    #[test]\\n    fn frame_extensions_round_trip_without_becoming_policy() {\\n        let encoded = br#\\\"{\\n          \\\"kind\\\":\\\"tool.call\\\",\\n          \\\"seq\\\":7,\\n          \\\"payload\\\":{\\\"call_id\\\":\\\"call-7\\\",\\\"tool\\\":\\\"vendor.future.exec\\\",\\\"argv\\\":[\\\"future\\\"]},\\n          \\\"vendor_trace\\\":{\\\"opaque\\\":true}\\n        }\\\"#;\\n        let frame = RunTurnFrame::decode(encoded, &MechanicalLimits::default()).unwrap();\\n        assert_eq!(frame.extensions[\\\"vendor_trace\\\"], json!({\\\"opaque\\\": true}));\\n        assert_eq!(\\n            serde_json::to_value(frame).unwrap()[\\\"vendor_trace\\\"],\\n            json!({\\\"opaque\\\": true})\\n        );\\n    }\\n\\n    #[test]\\n    fn shell_command_and_argv_are_first_class_and_mutually_exclusive() {\\n        let limits = MechanicalLimits::default();\\n        let mut call = base_tool_call();\\n        call.command = Some(\\\"printf 'owner-open\\\\\\\\n'\\\".to_string());\\n        call.validate_shell_exec(&limits).unwrap();\\n        call.command = None;\\n        call.argv = Some(vec![\\\"/bin/printf\\\".to_string(), \\\"owner-open\\\\\\\\n\\\".to_string()]);\\n        call.validate_shell_exec(&limits).unwrap();\\n        call.command = Some(\\\"pwd\\\".to_string());\\n        assert!(call.validate_shell_exec(&limits).is_err());\\n    }\\n\\n    #[test]\\n    fn adb_unknown_subcommands_and_absent_target_are_transport_valid() {\\n        let limits = MechanicalLimits::default();\\n        let mut call = base_tool_call();\\n        call.tool = \\\"adb.exec\\\".to_string();\\n        call.target = None;\\n        call.argv = Some(vec![\\n            \\\"future-subcommand\\\".to_string(),\\n            \\\"--future-flag\\\".to_string(),\\n        ]);\\n        call.validate_adb_exec(&limits).unwrap();\\n    }\\n\\n    #[test]\\n    fn no_serial_host_port_or_privilege_is_injected_by_the_codec() {\\n        let call: ToolCall = serde_json::from_value(json!({\\n            \\\"call_id\\\": \\\"adb-call\\\",\\n            \\\"tool\\\": \\\"adb.exec\\\",\\n            \\\"argv\\\": [\\\"shell\\\", \\\"id\\\"]\\n        }))\\n        .unwrap();\\n        call.validate_adb_exec(&MechanicalLimits::default())\\n            .unwrap();\\n        assert_eq!(\\n            call.argv.unwrap(),\\n            vec![\\\"shell\\\".to_string(), \\\"id\\\".to_string()]\\n        );\\n        assert!(call.target.is_none());\\n        assert!(call.target_id.is_none());\\n    }\\n\\n    #[test]\\n    fn turn_start_requires_exact_mirrored_correlation_when_present() {\\n        let frame = RunTurnFrame {\\n            kind: FRAME_TURN_START.to_string(),\\n            seq: 1,\\n            payload: json!({\\n                \\\"protocol\\\": PROTOCOL,\\n                \\\"protocol_version\\\": 1,\\n                \\\"session_id\\\": \\\"session-a\\\",\\n                \\\"task_id\\\": \\\"task-a\\\",\\n                \\\"turn_id\\\": \\\"turn-a\\\",\\n                \\\"user_input\\\": \\\"run pwd\\\"\\n            }),\\n            direction: Some(\\\"client_to_host\\\".to_string()),\\n            client_seq: Some(1),\\n            host_seq: None,\\n            frame_sha256: None,\\n            event_id: None,\\n            connection_id: None,\\n            stream_id: None,\\n            turn_stream_id: None,\\n            session_id: Some(\\\"session-b\\\".to_string()),\\n            profile_id: None,\\n            task_id: None,\\n            turn_id: None,\\n            call_id: None,\\n            job_id: None,\\n            tool: None,\\n            target: None,\\n            target_id: None,\\n            extensions: BTreeMap::new(),\\n        };\\n        let error = frame\\n            .turn_request(&MechanicalLimits::default())\\n            .unwrap_err();\\n        assert!(error.to_string().contains(\\\"envelope session_id conflicts\\\"));\\n    }\\n\\n    #[test]\\n    fn resource_limits_are_mechanical_not_semantic() {\\n        let limits = MechanicalLimits {\\n            max_argument_bytes: 3,\\n            max_total_argv_bytes: 3,\\n            ..MechanicalLimits::default()\\n        };\\n        let mut call = base_tool_call();\\n        call.argv = Some(vec![\\\"ab\\\".to_string(), \\\"cd\\\".to_string()]);\\n        let error = call.validate_shell_exec(&limits).unwrap_err();\\n        assert!(error.to_string().contains(\\\"argv exceeds\\\"));\\n    }\\n\\n    #[test]\\n    fn mechanical_limit_schema_ceilings_fail_closed() {\\n        let oversized = [\\n            MechanicalLimits {\\n                max_frame_bytes: MAX_CODEC_FRAME_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_label_bytes: MAX_CODEC_LABEL_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_id_bytes: MAX_CODEC_ID_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_user_input_bytes: MAX_CODEC_USER_INPUT_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_command_bytes: MAX_CODEC_COMMAND_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_argv_items: MAX_CODEC_ARGV_ITEMS + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_argument_bytes: MAX_CODEC_ARGUMENT_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_total_argv_bytes: MAX_CODEC_TOTAL_ARGV_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_env_items: MAX_CODEC_ENV_ITEMS + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_env_key_bytes: MAX_CODEC_ENV_KEY_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n            MechanicalLimits {\\n                max_env_value_bytes: MAX_CODEC_ENV_VALUE_BYTES + 1,\\n                ..MechanicalLimits::default()\\n            },\\n        ];\\n        for limits in oversized {\\n            assert!(\\n                limits.validate().is_err(),\\n                \\\"codec limit above schema ceiling must fail closed\\\"\\n            );\\n        }\\n        MechanicalLimits::default()\\n            .validate()\\n            .expect(\\\"default codec limits remain valid\\\");\\n\\n        let inconsistent = MechanicalLimits {\\n            max_argument_bytes: 1024,\\n            max_total_argv_bytes: 512,\\n            ..MechanicalLimits::default()\\n        };\\n        assert!(\\n            inconsistent.validate().is_err(),\\n            \\\"per-argument bound cannot exceed aggregate argv bound\\\"\\n        );\\n    }\\n\\n    #[test]\\n    fn tool_timeout_schema_ceiling_is_enforced() {\\n        let mut call = base_tool_call();\\n        call.timeout_ms = Some(MAX_CODEC_TIMEOUT_MS + 1);\\n        let error = call\\n            .validate_mechanical(&MechanicalLimits::default())\\n            .expect_err(\\\"oversized request timeout must fail closed\\\");\\n        assert!(error.to_string().contains(\\\"timeout_ms\\\"));\\n    }\\n\\n    #[test]\\n    fn turn_cancel_is_typed_and_correlation_bound() {\\n        let frame = RunTurnFrame {\\n            kind: FRAME_TURN_CANCEL.to_string(),\\n            seq: 2,\\n            payload: json!({\\n                \\\"session_id\\\": \\\"session-a\\\",\\n                \\\"turn_id\\\": \\\"turn-a\\\",\\n                \\\"turn_stream_id\\\": \\\"stream-a\\\"\\n            }),\\n            direction: Some(\\\"client_to_host\\\".to_string()),\\n            client_seq: Some(2),\\n            host_seq: None,\\n            frame_sha256: None,\\n            event_id: None,\\n            connection_id: None,\\n            stream_id: Some(\\\"stream-a\\\".to_string()),\\n            turn_stream_id: None,\\n            session_id: Some(\\\"session-a\\\".to_string()),\\n            profile_id: None,\\n            task_id: None,\\n            turn_id: Some(\\\"turn-a\\\".to_string()),\\n            call_id: None,\\n            job_id: None,\\n            tool: None,\\n            target: None,\\n            target_id: None,\\n            extensions: BTreeMap::new(),\\n        };\\n        let cancel = frame.turn_cancel(&MechanicalLimits::default()).unwrap();\\n        assert_eq!(cancel.turn_stream_id.as_deref(), Some(\\\"stream-a\\\"));\\n    }\\n\\n    #[test]\\n    fn aliases_must_not_conflict() {\\n        let frame = RunTurnFrame {\\n            kind: FRAME_HELLO.to_string(),\\n            seq: 0,\\n            payload: json!({}),\\n            direction: None,\\n            client_seq: None,\\n            host_seq: None,\\n            frame_sha256: None,\\n            event_id: None,\\n            connection_id: None,\\n            stream_id: Some(\\\"stream-a\\\".to_string()),\\n            turn_stream_id: Some(\\\"stream-b\\\".to_string()),\\n            session_id: None,\\n            profile_id: None,\\n            task_id: None,\\n            turn_id: None,\\n            call_id: None,\\n            job_id: None,\\n            tool: None,\\n            target: None,\\n            target_id: None,\\n            extensions: BTreeMap::new(),\\n        };\\n        assert!(\\n            frame\\n                .validate_mechanical(&MechanicalLimits::default())\\n                .is_err()\\n        );\\n    }\\n}\\n\\npub mod module_contract;\\n\"},{\"path\":\"crates/trillionnium-owner-open-provider-jsonl/src/protocol.rs\",\"sha\":\"29cd4548201a23347bc5f0d293c5cec63aaff53f\",\"text\":\"use std::os::unix::ffi::OsStrExt;\\nuse std::path::PathBuf;\\nuse std::time::Duration;\\n\\nuse base64::Engine as _;\\nuse base64::engine::DecodePaddingMode;\\nuse base64::engine::general_purpose::{GeneralPurpose, PAD, STANDARD as BASE64_STANDARD};\\nuse serde_json::{Map, Value, json};\\nuse sha2::{Digest, Sha256};\\nuse trillionnium_owner_open_call_registry::{CallKey, CallSnapshot};\\nuse trillionnium_owner_open_runtime::{\\n    AdbExecRequest, ExecutionEvent, ExecutionEventKind, ExecutionTerminal,\\n    MAX_RUNTIME_REQUEST_TIMEOUT, PtySize, ShellExecRequest, ShellInvocation, StreamKind,\\n};\\nuse trillionnium_owner_open_tool_bridge::{BoundToolCall, DirectToolRequest};\\nuse trillionnium_owner_open_turn_loop::{ProviderEvent, ProviderHost, ToolOutcome, TurnRequest};\\nuse trillionnium_owner_open_types::{\\n    MechanicalLimits as CodecLimits, PROTOCOL as DIRECT_PROTOCOL,\\n    PROTOCOL_VERSION as DIRECT_PROTOCOL_VERSION, ToolCall,\\n};\\n\\nuse super::{JsonlProviderConfig, JsonlProviderError, PROVIDER_PROTOCOL, Result};\\n\\npub(crate) fn validate_envelope(value: &Value, expected_seq: u64) -> Result<()> {\\n    if required_string(value, \\\"protocol\\\")? != PROVIDER_PROTOCOL {\\n        return Err(JsonlProviderError::Protocol(\\n            \\\"provider protocol does not match\\\".to_string(),\\n        ));\\n    }\\n    if value.get(\\\"seq\\\").and_then(Value::as_u64) != Some(expected_seq) {\\n        return Err(JsonlProviderError::Protocol(format!(\\n            \\\"provider seq is not the expected value {expected_seq}\\\"\\n        )));\\n    }\\n    required_string(value, \\\"kind\\\")?;\\n    Ok(())\\n}\\n\\npub(crate) fn handle_provider_event(value: &Value, host: &mut ProviderHost<'_>) -> Result<()> {\\n    let event = required_string(value, \\\"event\\\")?;\\n    let converted = match event {\\n        \\\"model.delta\\\" => ProviderEvent::ModelDelta(required_string(value, \\\"text\\\")?.to_string()),\\n        \\\"model.message\\\" => ProviderEvent::ModelMessage(required_string(value, \\\"text\\\")?.to_string()),\\n        \\\"provider.status\\\" => ProviderEvent::Status {\\n            status: required_string(value, \\\"status\\\")?.to_string(),\\n            detail: optional_string(value, \\\"detail\\\")?.map(str::to_string),\\n        },\\n        other => ProviderEvent::Opaque {\\n            kind: other.to_string(),\\n            payload: serde_json::to_string(value)\\n                .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?,\\n        },\\n    };\\n    host.emit(converted)\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string()))\\n}\\n\\npub(crate) fn decode_bound_tool_call(\\n    envelope: &Value,\\n    turn: &TurnRequest,\\n    config: &JsonlProviderConfig,\\n) -> Result<BoundToolCall> {\\n    let raw_call = envelope\\n        .get(\\\"call\\\")\\n        .cloned()\\n        .ok_or_else(|| JsonlProviderError::Protocol(\\\"tool.call has no call object\\\".to_string()))?;\\n    let raw_object = raw_call.as_object().ok_or_else(|| {\\n        JsonlProviderError::Protocol(\\\"tool.call call member must be an object\\\".to_string())\\n    })?;\\n    validate_direct_protocol_fields(raw_object)?;\\n    let mut call: ToolCall = serde_json::from_value(raw_call.clone())\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?;\\n    normalize_stream_alias(&mut call)?;\\n    // Validate the wire shape before aliases are collapsed.  In particular,\\n    // this catches a conflicting target/target_id pair before one alias is\\n    // moved into the canonical target_id member.\\n    call.validate_mechanical(&CodecLimits::default())\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?;\\n    bind_scope(&mut call, turn)?;\\n    normalize_target_alias(&mut call)?;\\n    normalize_config_generation(&mut call, raw_object, config)?;\\n    normalize_mode(&mut call)?;\\n    let pty = normalize_pty(&mut call)?;\\n    call.stdin = normalize_stdin(call.stdin.as_ref())?;\\n    // Zero, null and omission all select the owner-configured timeout.  Keep\\n    // one explicit sentinel in the digest while retaining the runtime's\\n    // existing `None`/zero handling in decode_timeout.\\n    if call.timeout_ms.unwrap_or(0) == 0 {\\n        call.timeout_ms = Some(0);\\n    }\\n    // Streaming is the owner-open default.  The runtime may still buffer a\\n    // complete result for this provider revision, but the requested option is\\n    // part of the stable call identity.\\n    call.stream = Some(call.stream.unwrap_or(true));\\n\\n    let claimed_request_sha256 = call.request_sha256.clone();\\n    let claimed_binding = call.binding_fingerprint.clone();\\n    call.request_sha256 = None;\\n    call.binding_fingerprint = None;\\n    let canonical_request = canonical_request_bytes(&call, raw_object)?;\\n    let binding_fingerprint = configuration_fingerprint(&call, config)?;\\n    if claimed_binding\\n        .as_deref()\\n        .is_some_and(|claimed| claimed != binding_fingerprint)\\n    {\\n        return Err(JsonlProviderError::Protocol(\\n            \\\"tool.call binding_fingerprint does not match resolved configuration\\\".to_string(),\\n        ));\\n    }\\n\\n    let target_id = call.target_id.clone();\\n    let direct_request = match call.tool.as_str() {\\n        \\\"shell.exec\\\" => {\\n            call.validate_shell_exec(&CodecLimits::default())\\n                .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?;\\n            DirectToolRequest::Shell(shell_request(&call, config)?)\\n        }\\n        \\\"adb.exec\\\" => {\\n            call.validate_adb_exec(&CodecLimits::default())\\n                .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?;\\n            DirectToolRequest::Adb(adb_request(&call, config)?)\\n        }\\n        _ => {\\n            return Err(JsonlProviderError::Protocol(format!(\\n                \\\"tool {} has no owner-open process backend\\\",\\n                call.tool\\n            )));\\n        }\\n    };\\n    let key = CallKey::new(turn.scope(), call.call_id.clone());\\n    match claimed_request_sha256 {\\n        Some(claimed) => BoundToolCall::with_claimed_digest_and_pty(\\n            key,\\n            binding_fingerprint,\\n            target_id,\\n            canonical_request,\\n            claimed,\\n            direct_request,\\n            pty,\\n        )\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string())),\\n        None => BoundToolCall::new_with_pty(\\n            key,\\n            binding_fingerprint,\\n            target_id,\\n            canonical_request,\\n            direct_request,\\n            pty,\\n        )\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string())),\\n    }\\n}\\n\\npub(crate) fn encode_tool_outcome(seq: u64, call_id: &str, outcome: ToolOutcome) -> Value {\\n    match outcome {\\n        ToolOutcome::Executed {\\n            generation,\\n            events,\\n            terminal,\\n            observation_sha256,\\n            snapshot,\\n        } => json!({\\n            \\\"protocol\\\": PROVIDER_PROTOCOL,\\n            \\\"kind\\\": \\\"tool.result\\\",\\n            \\\"seq\\\": seq,\\n            \\\"call_id\\\": call_id,\\n            \\\"status\\\": \\\"terminal\\\",\\n            \\\"generation\\\": generation,\\n            \\\"events\\\": events.iter().map(encode_execution_event).collect::<Vec<_>>(),\\n            \\\"terminal\\\": encode_terminal(&terminal),\\n            \\\"observation_sha256\\\": observation_sha256,\\n            \\\"registry\\\": encode_snapshot(&snapshot)\\n        }),\\n        ToolOutcome::Existing(snapshot) => json!({\\n            \\\"protocol\\\": PROVIDER_PROTOCOL,\\n            \\\"kind\\\": \\\"tool.result\\\",\\n            \\\"seq\\\": seq,\\n            \\\"call_id\\\": call_id,\\n            \\\"status\\\": \\\"existing\\\",\\n            \\\"registry\\\": encode_snapshot(&snapshot)\\n        }),\\n        ToolOutcome::Inhibited(snapshot) => json!({\\n            \\\"protocol\\\": PROVIDER_PROTOCOL,\\n            \\\"kind\\\": \\\"tool.result\\\",\\n            \\\"seq\\\": seq,\\n            \\\"call_id\\\": call_id,\\n            \\\"status\\\": \\\"inhibited\\\",\\n            \\\"registry\\\": encode_snapshot(&snapshot)\\n        }),\\n    }\\n}\\n\\npub(crate) fn encode_tool_error(seq: u64, call_id: &str, status: &str, error: &str) -> Value {\\n    json!({\\n        \\\"protocol\\\": PROVIDER_PROTOCOL,\\n        \\\"kind\\\": \\\"tool.result\\\",\\n        \\\"seq\\\": seq,\\n        \\\"call_id\\\": call_id,\\n        \\\"status\\\": status,\\n        \\\"error\\\": error\\n    })\\n}\\n\\npub(crate) fn required_string<'a>(value: &'a Value, field: &str) -> Result<&'a str> {\\n    value\\n        .get(field)\\n        .and_then(Value::as_str)\\n        .filter(|value| !value.is_empty() && !value.as_bytes().contains(&0))\\n        .ok_or_else(|| {\\n            JsonlProviderError::Protocol(format!(\\\"provider field {field} is absent or invalid\\\"))\\n        })\\n}\\n\\npub(crate) fn optional_string<'a>(value: &'a Value, field: &str) -> Result<Option<&'a str>> {\\n    match value.get(field) {\\n        None | Some(Value::Null) => Ok(None),\\n        Some(Value::String(value)) if !value.as_bytes().contains(&0) => Ok(Some(value)),\\n        _ => Err(JsonlProviderError::Protocol(format!(\\n            \\\"provider field {field} has an invalid shape\\\"\\n        ))),\\n    }\\n}\\n\\nfn bind_scope(call: &mut ToolCall, turn: &TurnRequest) -> Result<()> {\\n    bind_optional(&mut call.session_id, &turn.session_id, \\\"session_id\\\")?;\\n    bind_optional(&mut call.profile_id, &turn.profile_id, \\\"profile_id\\\")?;\\n    bind_optional(&mut call.task_id, &turn.task_id, \\\"task_id\\\")?;\\n    bind_optional(&mut call.turn_id, &turn.turn_id, \\\"turn_id\\\")?;\\n    bind_optional(\\n        &mut call.turn_stream_id,\\n        &turn.turn_stream_id,\\n        \\\"turn_stream_id\\\",\\n    )?;\\n    Ok(())\\n}\\n\\nfn bind_optional(field: &mut Option<String>, expected: &str, label: &str) -> Result<()> {\\n    match field {\\n        Some(value) if value != expected => Err(JsonlProviderError::Protocol(format!(\\n            \\\"tool.call {label} conflicts with the active turn\\\"\\n        ))),\\n        Some(_) => Ok(()),\\n        None => {\\n            *field = Some(expected.to_string());\\n            Ok(())\\n        }\\n    }\\n}\\n\\n/// The provider JSONL envelope is a transport wrapper.  The request digest is\\n/// defined over the direct-tools request schema, so a provider may optionally\\n/// repeat that schema's protocol/version in its call object only when the\\n/// values agree with the generated owner-open constants.\\nfn validate_direct_protocol_fields(object: &Map<String, Value>) -> Result<()> {\\n    if let Some(protocol) = object.get(\\\"protocol\\\")\\n        && protocol.as_str() != Some(DIRECT_PROTOCOL)\\n    {\\n        return Err(JsonlProviderError::Protocol(\\n            \\\"tool.call protocol does not match direct-tools protocol\\\".to_string(),\\n        ));\\n    }\\n    if let Some(version) = object.get(\\\"protocol_version\\\") {\\n        let valid = match version {\\n            Value::Number(number) => number.as_u64() == Some(u64::from(DIRECT_PROTOCOL_VERSION)),\\n            Value::String(value) => value == &DIRECT_PROTOCOL_VERSION.to_string(),\\n            _ => false,\\n        };\\n        if !valid {\\n            return Err(JsonlProviderError::Protocol(\\n                \\\"tool.call protocol_version does not match direct-tools protocol\\\".to_string(),\\n            ));\\n        }\\n    }\\n    Ok(())\\n}\\n\\nfn normalize_stream_alias(call: &mut ToolCall) -> Result<()> {\\n    let Some(alias) = call.extensions.remove(\\\"stream_id\\\") else {\\n        return Ok(());\\n    };\\n    let alias = match alias {\\n        Value::Null => None,\\n        Value::String(value) if !value.is_empty() && !value.as_bytes().contains(&0) => Some(value),\\n        _ => {\\n            return Err(JsonlProviderError::Protocol(\\n                \\\"tool.call stream_id alias has an invalid shape\\\".to_string(),\\n            ));\\n        }\\n    };\\n    if let (Some(existing), Some(alias)) = (&call.turn_stream_id, &alias)\\n        && existing != alias\\n    {\\n        return Err(JsonlProviderError::Protocol(\\n            \\\"tool.call stream_id conflicts with turn_stream_id\\\".to_string(),\\n        ));\\n    }\\n    if call.turn_stream_id.is_none() {\\n        call.turn_stream_id = alias;\\n    }\\n    Ok(())\\n}\\n\\nfn normalize_target_alias(call: &mut ToolCall) -> Result<()> {\\n    if let (Some(target), Some(target_id)) = (&call.target, &call.target_id)\\n        && target != target_id\\n    {\\n        return Err(JsonlProviderError::Protocol(\\n            \\\"tool.call target conflicts with target_id\\\".to_string(),\\n        ));\\n    }\\n    if call.target_id.is_none() {\\n        call.target_id = call.target.clone();\\n    }\\n    // `target_id` is the canonical spelling.  The original alias remains a\\n    // routing hint only and is not allowed to create a second digest identity.\\n    call.target = None;\\n    Ok(())\\n}\\n\\nfn normalize_config_generation(\\n    call: &mut ToolCall,\\n    raw_object: &Map<String, Value>,\\n    config: &JsonlProviderConfig,\\n) -> Result<()> {\\n    let snapshot = config.config_generation.clone().unwrap_or(Value::Null);\\n    validate_generation_value(&snapshot)?;\\n    if raw_object.contains_key(\\\"config_generation\\\") {\\n        let supplied = call.config_generation.clone().unwrap_or(Value::Null);\\n        validate_generation_value(&supplied)?;\\n        if supplied != snapshot {\\n            return Err(JsonlProviderError::Protocol(\\n                \\\"tool.call config_generation conflicts with the active provider snapshot\\\"\\n                    .to_string(),\\n            ));\\n        }\\n    }\\n    call.config_generation = Some(snapshot);\\n    Ok(())\\n}\\n\\nfn validate_generation_value(value: &Value) -> Result<()> {\\n    match value {\\n        Value::Null => Ok(()),\\n        Value::Number(number) if number.as_i64().is_some() || number.as_u64().is_some() => Ok(()),\\n        Value::String(value) if !value.as_bytes().contains(&0) => Ok(()),\\n        _ => Err(JsonlProviderError::Protocol(\\n            \\\"config_generation must be an integer, string or null\\\".to_string(),\\n        )),\\n    }\\n}\\n\\nfn normalize_mode(call: &mut ToolCall) -> Result<()> {\\n    if let Some(mode) = call.mode.as_deref()\\n        && !matches!(mode, \\\"command\\\" | \\\"argv\\\")\\n    {\\n        return Err(JsonlProviderError::Protocol(format!(\\n            \\\"tool.call mode {mode:?} is unsupported\\\"\\n        )));\\n    }\\n    let expected = match (&call.command, &call.argv) {\\n        (Some(_), None) => Some(\\\"command\\\"),\\n        (None, Some(_)) => Some(\\\"argv\\\"),\\n        _ => None,\\n    };\\n    let Some(expected) = expected else {\\n        // The tool-specific codec below reports the mutually-exclusive or\\n        // missing command/argv shape.  Do not manufacture a mode for it.\\n        return Ok(());\\n    };\\n    if let Some(mode) = call.mode.as_deref()\\n        && mode != expected\\n    {\\n        return Err(JsonlProviderError::Protocol(format!(\\n            \\\"tool.call mode {mode:?} conflicts with the requested {expected} form\\\"\\n        )));\\n    }\\n    call.mode = Some(expected.to_string());\\n    Ok(())\\n}\\n\\nfn normalize_pty(call: &mut ToolCall) -> Result<Option<PtySize>> {\\n    let decoded = decode_pty(call.pty.as_ref())?;\\n    match decoded {\\n        Some(decoded) => {\\n            // An explicit env.TERM entry, including null/unset, wins over the\\n            // PTY object's term.  With no entry, materialize the owner default\\n            // into the effective process environment so the digest and the\\n            // launched process observe the same bytes.\\n            let effective_term = match call.env.get(\\\"TERM\\\").cloned() {\\n                Some(Some(term)) => Value::String(term),\\n                Some(None) => Value::Null,\\n                None => {\\n                    call.env\\n                        .insert(\\\"TERM\\\".to_string(), Some(decoded.term.clone()));\\n                    Value::String(decoded.term.clone())\\n                }\\n            };\\n            call.pty = Some(json!({\\n                \\\"enabled\\\": true,\\n                \\\"rows\\\": decoded.size.rows,\\n                \\\"cols\\\": decoded.size.cols,\\n                \\\"term\\\": effective_term\\n            }));\\n            Ok(Some(decoded.size))\\n        }\\n        None => {\\n            // Omitted, null and false are one disabled transport mode in the\\n            // provider protocol; use one explicit canonical spelling.\\n            call.pty = Some(Value::Bool(false));\\n            Ok(None)\\n        }\\n    }\\n}\\n\\nfn shell_request(call: &ToolCall, config: &JsonlProviderConfig) -> Result<ShellExecRequest> {\\n    let invocation = match (&call.command, &call.argv) {\\n        (Some(command), None) => ShellInvocation::Command(command.clone()),\\n        (None, Some(argv)) => ShellInvocation::Argv(argv.clone()),\\n        _ => {\\n            return Err(JsonlProviderError::Protocol(\\n                \\\"shell.exec command/argv shape is invalid\\\".to_string(),\\n            ));\\n        }\\n    };\\n    Ok(ShellExecRequest {\\n        call_id: call.call_id.clone(),\\n        target_id: call.target_id.clone(),\\n        invocation,\\n        shell_executable: config.shell_executable.clone(),\\n        cwd: call.cwd.as_ref().map(PathBuf::from),\\n        env: call.env.clone(),\\n        stdin: decode_stdin(call.stdin.as_ref())?,\\n        timeout: decode_timeout(call.timeout_ms)?,\\n    })\\n}\\n\\nfn adb_request(call: &ToolCall, config: &JsonlProviderConfig) -> Result<AdbExecRequest> {\\n    Ok(AdbExecRequest {\\n        call_id: call.call_id.clone(),\\n        target_id: call.target_id.clone(),\\n        argv: call\\n            .argv\\n            .clone()\\n            .ok_or_else(|| JsonlProviderError::Protocol(\\\"adb.exec has no argv\\\".to_string()))?,\\n        adb_executable: config.adb_executable.clone(),\\n        cwd: call.cwd.as_ref().map(PathBuf::from),\\n        env: call.env.clone(),\\n        stdin: decode_stdin(call.stdin.as_ref())?,\\n        timeout: decode_timeout(call.timeout_ms)?,\\n    })\\n}\\n\\n#[derive(Debug, Clone)]\\nstruct DecodedPty {\\n    size: PtySize,\\n    term: String,\\n}\\n\\nfn decode_pty(value: Option<&Value>) -> Result<Option<DecodedPty>> {\\n    let Some(value) = value else {\\n        return Ok(None);\\n    };\\n    match value {\\n        Value::Null | Value::Bool(false) => Ok(None),\\n        Value::Bool(true) => Ok(Some(DecodedPty {\\n            size: PtySize::default(),\\n            term: \\\"xterm-256color\\\".to_string(),\\n        })),\\n        Value::Object(object) => {\\n            let enabled = match object.get(\\\"enabled\\\") {\\n                None => true,\\n                Some(Value::Bool(value)) => *value,\\n                Some(_) => {\\n                    return Err(JsonlProviderError::Protocol(\\n                        \\\"pty.enabled must be boolean\\\".to_string(),\\n                    ));\\n                }\\n            };\\n            let rows = decode_pty_dimension(object.get(\\\"rows\\\"), \\\"rows\\\", 24)?;\\n            let cols = decode_pty_dimension(object.get(\\\"cols\\\"), \\\"cols\\\", 80)?;\\n            if !enabled {\\n                return Ok(None);\\n            }\\n            let term = match object.get(\\\"term\\\") {\\n                None | Some(Value::Null) => \\\"xterm-256color\\\".to_string(),\\n                Some(Value::String(value))\\n                    if !value.is_empty()\\n                        && value.len() <= 256\\n                        && !value.as_bytes().contains(&0)\\n                        && !value.chars().any(char::is_control) =>\\n                {\\n                    value.clone()\\n                }\\n                Some(_) => {\\n                    return Err(JsonlProviderError::Protocol(\\n                        \\\"pty.term must be a non-empty control-free string\\\".to_string(),\\n                    ));\\n                }\\n            };\\n            Ok(Some(DecodedPty {\\n                size: PtySize::new(rows, cols),\\n                term,\\n            }))\\n        }\\n        _ => Err(JsonlProviderError::Protocol(\\n            \\\"pty must be boolean or object\\\".to_string(),\\n        )),\\n    }\\n}\\n\\nfn decode_pty_dimension(value: Option<&Value>, label: &str, default: u16) -> Result<u16> {\\n    let Some(value) = value else {\\n        return Ok(default);\\n    };\\n    let Some(value) = value.as_u64() else {\\n        return Err(JsonlProviderError::Protocol(format!(\\n            \\\"pty.{label} must be an integer\\\"\\n        )));\\n    };\\n    let value = u16::try_from(value).map_err(|_| {\\n        JsonlProviderError::Protocol(format!(\\\"pty.{label} is outside the u16 bound\\\"))\\n    })?;\\n    if value == 0 {\\n        return Err(JsonlProviderError::Protocol(format!(\\n            \\\"pty.{label} must be non-zero\\\"\\n        )));\\n    }\\n    Ok(value)\\n}\\n\\nfn decode_stdin(value: Option<&Value>) -> Result<Vec<u8>> {\\n    let Some(value) = value else {\\n        return Ok(Vec::new());\\n    };\\n    match value {\\n        Value::Null => Ok(Vec::new()),\\n        Value::String(value) => Ok(value.as_bytes().to_vec()),\\n        Value::Object(object) => decode_stdin_data_object(object),\\n        _ => Err(JsonlProviderError::Protocol(\\n            \\\"stdin has an unsupported shape\\\".to_string(),\\n        )),\\n    }\\n}\\n\\nfn decode_stdin_data_object(object: &Map<String, Value>) -> Result<Vec<u8>> {\\n    let encoding = object\\n        .get(\\\"encoding\\\")\\n        .and_then(Value::as_str)\\n        .ok_or_else(|| JsonlProviderError::Protocol(\\\"stdin object has no encoding\\\".to_string()))?;\\n    let data = object\\n        .get(\\\"data\\\")\\n        .and_then(Value::as_str)\\n        .ok_or_else(|| JsonlProviderError::Protocol(\\\"stdin object has no data\\\".to_string()))?;\\n    match encoding {\\n        \\\"utf8\\\" | \\\"utf-8\\\" => Ok(data.as_bytes().to_vec()),\\n        \\\"base64\\\" => GeneralPurpose::new(\\n            &base64::alphabet::STANDARD,\\n            PAD.with_decode_padding_mode(DecodePaddingMode::Indifferent),\\n        )\\n        .decode(data)\\n        .map_err(|error| JsonlProviderError::Protocol(format!(\\\"stdin base64 is invalid: {error}\\\"))),\\n        other => Err(JsonlProviderError::Protocol(format!(\\n            \\\"stdin encoding {other} is unsupported\\\"\\n        ))),\\n    }\\n}\\n\\nfn normalize_stdin(value: Option<&Value>) -> Result<Option<Value>> {\\n    let Some(value) = value else {\\n        return Ok(None);\\n    };\\n    match value {\\n        Value::Null => Ok(Some(Value::Null)),\\n        Value::String(value) => Ok(Some(canonical_stdin_bytes(value.as_bytes()))),\\n        Value::Object(object) => {\\n            let has_encoding = object.contains_key(\\\"encoding\\\");\\n            let has_data = object.contains_key(\\\"data\\\");\\n            let has_fd = object.contains_key(\\\"fd_id\\\");\\n            let has_spool = object.contains_key(\\\"spool_path\\\");\\n            let data_variant = has_encoding || has_data;\\n            let descriptor_count = usize::from(has_fd) + usize::from(has_spool);\\n            if (data_variant && descriptor_count != 0) || descriptor_count > 1 {\\n                return Err(JsonlProviderError::Protocol(\\n                    \\\"stdin data, fd_id and spool_path are mutually exclusive\\\".to_string(),\\n                ));\\n            }\\n            if data_variant {\\n                let bytes = decode_stdin_data_object(object)?;\\n                let mut canonical = object.clone();\\n                canonical.insert(\\\"encoding\\\".to_string(), Value::String(\\\"base64\\\".to_string()));\\n                canonical.insert(\\n                    \\\"data\\\".to_string(),\\n                    Value::String(BASE64_STANDARD.encode(bytes)),\\n                );\\n                Ok(Some(Value::Object(canonical)))\\n            } else if descriptor_count != 0 {\\n                // The current direct process backend cannot dereference an\\n                // inherited FD or target spool path.  Preserve its descriptor\\n                // bytes for a truthful unsupported-mechanism result, while\\n                // normalizing the documented close-after default.\\n                let mut canonical = object.clone();\\n                canonical\\n                    .entry(\\\"close_after\\\".to_string())\\n                    .or_insert(Value::Bool(true));\\n                Ok(Some(Value::Object(canonical)))\\n            } else {\\n                Err(JsonlProviderError::Protocol(\\n                    \\\"stdin object has no supported data or descriptor variant\\\".to_string(),\\n                ))\\n            }\\n        }\\n        _ => Err(JsonlProviderError::Protocol(\\n            \\\"stdin has an unsupported shape\\\".to_string(),\\n        )),\\n    }\\n}\\n\\nfn canonical_stdin_bytes(bytes: &[u8]) -> Value {\\n    json!({\\n        \\\"encoding\\\": \\\"base64\\\",\\n        \\\"data\\\": BASE64_STANDARD.encode(bytes)\\n    })\\n}\\n\\n// These members identify a transport instance or a caller-supplied digest;\\n// none describe the requested direct effect.  They are deliberately removed\\n// only at the top level of the ToolCall object.  Unknown extension members,\\n// including nested values, remain opaque and continue to participate in JCS.\\nconst VOLATILE_CALL_MEMBERS: &[&str] = &[\\n    \\\"call_id\\\",\\n    \\\"turn_stream_id\\\",\\n    \\\"stream_id\\\",\\n    \\\"connection_id\\\",\\n    \\\"event_id\\\",\\n    \\\"client_request_id\\\",\\n    \\\"server_request_id\\\",\\n    \\\"parent_turn_id\\\",\\n    \\\"continuation_of\\\",\\n    \\\"prior_connection_id\\\",\\n    \\\"resume_cursor\\\",\\n    \\\"resume_token\\\",\\n    \\\"seq\\\",\\n    \\\"client_seq\\\",\\n    \\\"host_seq\\\",\\n    \\\"timestamps\\\",\\n    \\\"frame_sha256\\\",\\n    \\\"request_sha256\\\",\\n    \\\"binding_fingerprint\\\",\\n    \\\"resolved_endpoint\\\",\\n    \\\"resolved_target\\\",\\n];\\n\\nfn canonical_request_bytes(call: &ToolCall, raw_object: &Map<String, Value>) -> Result<Vec<u8>> {\\n    let value = serde_json::to_value(call)\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?;\\n    let mut object = value.as_object().cloned().ok_or_else(|| {\\n        JsonlProviderError::Protocol(\\\"normalized tool.call is not an object\\\".to_string())\\n    })?;\\n\\n    for member in VOLATILE_CALL_MEMBERS {\\n        object.remove(*member);\\n    }\\n    // The direct-tools schema has one canonical target spelling.  Explicit\\n    // null is retained when the caller sent only the alias; an omitted target\\n    // remains omitted, so a configured target is never invented here.\\n    if (raw_object.get(\\\"target\\\").is_some_and(Value::is_null)\\n        || raw_object.get(\\\"target_id\\\").is_some_and(Value::is_null))\\n        && !object.contains_key(\\\"target_id\\\")\\n    {\\n        object.insert(\\\"target_id\\\".to_string(), Value::Null);\\n    }\\n    // serde's skip-if-empty representation cannot distinguish an explicitly\\n    // supplied empty env object from omission.  Preserve that wire choice;\\n    // it is an extension-compatible value and costs no execution semantics.\\n    if raw_object.get(\\\"env\\\").is_some_and(Value::is_object) && !object.contains_key(\\\"env\\\") {\\n        object.insert(\\\"env\\\".to_string(), raw_object[\\\"env\\\"].clone());\\n    }\\n    // An explicit null cwd is meaningful under the schema's null-preservation\\n    // rule even though ToolCall stores it as None.\\n    if raw_object.get(\\\"cwd\\\").is_some_and(Value::is_null) {\\n        object.insert(\\\"cwd\\\".to_string(), Value::Null);\\n    }\\n\\n    // Protocol/version belong to the direct request preimage (the enclosing\\n    // provider protocol is only a transport envelope).  Numeric version 1 is\\n    // canonical even when a caller supplied the equivalent string \\\"1\\\".\\n    object.insert(\\n        \\\"protocol\\\".to_string(),\\n        Value::String(DIRECT_PROTOCOL.to_string()),\\n    );\\n    object.insert(\\n        \\\"protocol_version\\\".to_string(),\\n        json!(DIRECT_PROTOCOL_VERSION),\\n    );\\n\\n    serde_jcs::to_vec(&Value::Object(object))\\n        .map_err(|error| JsonlProviderError::Protocol(error.to_string()))\\n}\\n\\nfn decode_timeout(value: Option<i64>) -> Result<Option<Duration>> {\\n    match value {\\n        None | Some(0) => Ok(None),\\n        Some(value) if value > 0 => {\\n            let timeout = Duration::from_millis(u64::try_from(value).map_err(|_| {\\n                JsonlProviderError::Protocol(\\\"timeout_ms is out of range\\\".to_string())\\n            })?);\\n            if timeout > MAX_RUNTIME_REQUEST_TIMEOUT {\\n                return Err(JsonlProviderError::Protocol(format!(\\n                    \\\"timeout_ms exceeds runtime hard bound {MAX_RUNTIME_REQUEST_TIMEOUT:?}\\\"\\n                )));\\n            }\\n            Ok(Some(timeout))\\n        }\\n        Some(_) => Err(JsonlProviderError::Protocol(\\n            \\\"timeout_ms must be nonnegative\\\".to_string(),\\n        )),\\n    }\\n}\\n\\nfn configuration_fingerprint(call: &ToolCall, config: &JsonlProviderConfig) -> Result<String> {\\n    let mut hasher = Sha256::new();\\n    hash_field(\\n        &mut hasher,\\n        b\\\"schema\\\",\\n        b\\\"trillionnium.owner-open.binding.v1\\\",\\n    );\\n    hash_field(&mut hasher, b\\\"tool\\\", call.tool.as_bytes());\\n    let executable = if call.tool == \\\"adb.exec\\\" {\\n        &config.adb_executable\\n    } else {\\n        &config.shell_executable\\n    };\\n    hash_field(\\n        &mut hasher,\\n        b\\\"executable\\\",\\n        executable.as_os_str().as_bytes(),\\n    );\\n    hash_field(\\n        &mut hasher,\\n        b\\\"config_generation\\\",\\n        &serde_jcs::to_vec(&call.config_generation)\\n            .map_err(|error| JsonlProviderError::Protocol(error.to_string()))?,\\n    );\\n    Ok(hex_lower(&hasher.finalize()))\\n}\\n\\nfn encode_execution_event(event: &ExecutionEvent) -> Value {\\n    let body = match &event.kind {\\n        ExecutionEventKind::Accepted => json!({\\\"kind\\\": \\\"accepted\\\"}),\\n        ExecutionEventKind::Started { pid } => json!({\\\"kind\\\": \\\"started\\\", \\\"pid\\\": pid}),\\n        ExecutionEventKind::Output { stream, bytes } => json!({\\n            \\\"kind\\\": \\\"output\\\",\\n            \\\"stream\\\": match stream {\\n                StreamKind::Stdout => \\\"stdout\\\",\\n                StreamKind::Stderr => \\\"stderr\\\",\\n                StreamKind::Pty => \\\"pty\\\",\\n            },\\n            \\\"encoding\\\": \\\"base64\\\",\\n            \\\"data\\\": BASE64_STANDARD.encode(bytes),\\n            \\\"byte_count\\\": bytes.len()\\n        }),\\n        ExecutionEventKind::Terminal(terminal) => json!({\\n            \\\"kind\\\": \\\"terminal\\\",\\n            \\\"terminal\\\": encode_terminal(terminal)\\n        }),\\n    };\\n    json!({\\n        \\\"call_id\\\": &event.call_id,\\n        \\\"target_id\\\": &event.target_id,\\n        \\\"tool\\\": event.tool.as_str(),\\n        \\\"seq\\\": event.seq,\\n        \\\"elapsed_ms\\\": event.elapsed_ms,\\n        \\\"event\\\": body\\n    })\\n}\\n\\nfn encode_terminal(terminal: &ExecutionTerminal) -> Value {\\n    json!({\\n        \\\"kind\\\": terminal.kind.as_str(),\\n        \\\"exit_code\\\": terminal.exit_code,\\n        \\\"signal\\\": terminal.signal,\\n        \\\"stdout_bytes\\\": terminal.stdout_bytes,\\n        \\\"stderr_bytes\\\": terminal.stderr_bytes,\\n        \\\"output_truncated\\\": terminal.output_truncated,\\n        \\\"elapsed_ms\\\": terminal.elapsed_ms,\\n        \\\"error\\\": &terminal.error\\n    })\\n}\\n\\nfn encode_snapshot(snapshot: &CallSnapshot) -> Value {\\n    json!({\\n        \\\"call_id\\\": &snapshot.key.call_id,\\n        \\\"request_sha256\\\": &snapshot.request.request_sha256,\\n        \\\"binding_fingerprint\\\": &snapshot.request.binding_fingerprint,\\n        \\\"tool\\\": &snapshot.request.tool,\\n        \\\"target_id\\\": &snapshot.request.target_id,\\n        \\\"state\\\": format!(\\\"{:?}\\\", snapshot.state),\\n        \\\"cancellation_requested\\\": snapshot.cancellation_requested,\\n        \\\"connection_lost\\\": snapshot.connection_lost,\\n        \\\"earliest_history_seq\\\": snapshot.earliest_history_seq,\\n        \\\"next_event_seq\\\": snapshot.next_event_seq\\n    })\\n}\\n\\nfn hash_field(hasher: &mut Sha256, name: &[u8], value: &[u8]) {\\n    hasher.update((name.len() as u64).to_be_bytes());\\n    hasher.update(name);\\n    hasher.update((value.len() as u64).to_be_bytes());\\n    hasher.update(value);\\n}\\n\\nfn hex_lower(value: &[u8]) -> String {\\n    use std::fmt::Write as _;\\n    let mut output = String::with_capacity(value.len() * 2);\\n    for byte in value {\\n        write!(&mut output, \\\"{byte:02x}\\\").expect(\\\"writing to String cannot fail\\\");\\n    }\\n    output\\n}\\n\\n#[cfg(test)]\\nmod tests {\\n    use super::*;\\n\\n    fn turn() -> TurnRequest {\\n        TurnRequest {\\n            session_id: \\\"session-protocol-test\\\".to_string(),\\n            profile_id: \\\"owner-open\\\".to_string(),\\n            task_id: \\\"task-protocol-test\\\".to_string(),\\n            turn_id: \\\"turn-protocol-test\\\".to_string(),\\n            turn_stream_id: \\\"stream-protocol-test\\\".to_string(),\\n            user_input: \\\"test\\\".to_string(),\\n        }\\n    }\\n\\n    #[test]\\n    fn equivalent_pty_spellings_have_one_canonical_digest() {\\n        let config = JsonlProviderConfig::default();\\n        let boolean = json!({\\n            \\\"call\\\": {\\n                \\\"call_id\\\": \\\"call-pty-normalized\\\",\\n                \\\"tool\\\": \\\"shell.exec\\\",\\n                \\\"command\\\": \\\"printf ok\\\",\\n                \\\"pty\\\": true\\n            }\\n        });\\n        let object = json!({\\n            \\\"call\\\": {\\n                \\\"call_id\\\": \\\"call-pty-normalized\\\",\\n                \\\"tool\\\": \\\"shell.exec\\\",\\n                \\\"command\\\": \\\"printf ok\\\",\\n                \\\"pty\\\": {\\\"enabled\\\": true, \\\"rows\\\": 24, \\\"cols\\\": 80, \\\"term\\\": \\\"xterm-256color\\\"}\\n            }\\n        });\\n        let first = decode_bound_tool_call(&boolean, &turn(), &config).unwrap();\\n        let second = decode_bound_tool_call(&object, &turn(), &config).unwrap();\\n        assert_eq!(first.canonical_request, second.canonical_request);\\n        assert_eq!(first.request_sha256, second.request_sha256);\\n        assert_eq!(first.pty, second.pty);\\n    }\\n\\n    #[test]\\n    fn explicit_null_term_wins_and_stays_in_the_digest() {\\n        let config = JsonlProviderConfig::default();\\n        let call = json!({\\n            \\\"call\\\": {\\n                \\\"call_id\\\": \\\"call-pty-unset-term\\\",\\n                \\\"tool\\\": \\\"shell.exec\\\",\\n                \\\"command\\\": \\\"printf ok\\\",\\n                \\\"env\\\": {\\\"TERM\\\": null},\\n                \\\"pty\\\": {\\\"enabled\\\": true}\\n            }\\n        });\\n        let bound = decode_bound_tool_call(&call, &turn(), &config).unwrap();\\n        let canonical: Value = serde_json::from_slice(&bound.canonical_request).unwrap();\\n        assert_eq!(canonical[\\\"env\\\"][\\\"TERM\\\"], Value::Null);\\n        assert_eq!(canonical[\\\"pty\\\"][\\\"term\\\"], Value::Null);\\n    }\\n\\n    #[test]\\n    fn explicit_null_target_aliases_have_one_canonical_member() {\\n        let config = JsonlProviderConfig::default();\\n        let call = json!({\\n            \\\"call\\\": {\\n                \\\"call_id\\\": \\\"call-null-target\\\",\\n                \\\"tool\\\": \\\"shell.exec\\\",\\n                \\\"command\\\": \\\"printf ok\\\",\\n                \\\"target\\\": null,\\n                \\\"target_id\\\": null\\n            }\\n        });\\n        let bound = decode_bound_tool_call(&call, &turn(), &config).unwrap();\\n        let canonical: Value = serde_json::from_slice(&bound.canonical_request).unwrap();\\n        assert_eq!(canonical[\\\"target_id\\\"], Value::Null);\\n        assert!(canonical.get(\\\"target\\\").is_none());\\n    }\\n\\n    #[test]\\n    fn request_timeout_decode_enforces_the_runtime_hard_bound() {\\n        let maximum_millis = i64::try_from(MAX_RUNTIME_REQUEST_TIMEOUT.as_millis())\\n            .expect(\\\"runtime timeout bound fits the provider protocol integer\\\");\\n        assert_eq!(\\n            decode_timeout(Some(maximum_millis)).unwrap(),\\n            Some(MAX_RUNTIME_REQUEST_TIMEOUT)\\n        );\\n        let error = decode_timeout(Some(maximum_millis + 1))\\n            .expect_err(\\\"provider timeout above the runtime bound must fail closed\\\");\\n        assert!(error.to_string().contains(\\\"timeout_ms\\\"));\\n        assert_eq!(decode_timeout(Some(0)).unwrap(), None);\\n    }\\n}\\n\"}]}")
