def audit(event,args):
 denied=event in {"socket.__new__","socket.connect","socket.bind","subprocess.Popen","os.system","os.fork","os.posix_spawn","os.exec"}
 if event=="open"and len(args)>2 and isinstance(args[0],(str,bytes,os.PathLike))and isinstance(args[2],int)and args[2]&(os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND):
  p=os.path.abspath(os.fsdecode(args[0]));denied=denied or not(p==str(ROOT)or p.startswith(str(ROOT)+os.sep))
 if denied:raise PermissionError("host-only trust audit denied "+event)
